CREATE FUNCTION [dbo].[BrokerLstIDform] 
(
@ID AS INT
)

RETURNS CHAR(2)
AS
BEGIN

DECLARE @Form AS CHAR(2)
DECLARE @nCount AS INT

SELECT @nCount = COUNT(*) FROM dbo.BrokerLst_Master WHERE ID = @ID

