AS
BEGIN


--SELECT dbo.f_BandSaw_Price(1)

declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @nPrice DECIMAL(7,2) = 0

-- $.3 per SQR Inch
IF @nDia > 650
	SET @nPrice = 0
ELSE
IF @nDia > 0
	SET @nPrice = CAST( (3.14156 * (@nDia/2)*(@nDia/2)* .300 ) AS DECIMAL(7,2))


