CREATE FUNCTION [dbo].[f_Bracket_Pounds]
(	
	@Bracket TINYINT
)
RETURNS  INT

AS
BEGIN

--Print dbo.f_Bracket_Pounds(nBracket)
--Print dbo.f_Pound_Bracket(sWeight)

DECLARE @MaxLBS INT = 0

IF @Bracket   = 0
	SET @MaxLBS = 5
ELSE
IF @Bracket = 1
	SET @MaxLBS = 10
ELSE
IF @Bracket = 2
	SET @MaxLBS = 20
ELSE
IF @Bracket   = 3
	SET @MaxLBS = 50
ELSE
IF @Bracket   = 4
	SET @MaxLBS = 100
ELSE
IF @Bracket   = 5
	SET @MaxLBS = 200
ELSE
IF @Bracket   = 6
	SET @MaxLBS = 500
ELSE
IF @Bracket   = 7
	SET @MaxLBS = 1000
ELSE
IF @Bracket   = 8
	SET @MaxLBS = 2000
ELSE
IF @Bracket   = 9
	SET @MaxLBS = 5000
ELSE
	SET @MaxLBS   = 0
	
--Bracket 0 is Bracket 5, the most expensive!
	
RETURN @MaxLBS
END

