/****** Object:  UserDefinedFunction [dbo].[f_Calc_CW]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_Calc_CW]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'
CREATE FUNCTION [dbo].[f_Calc_CW] 
(
@nDiaIn DECIMAL(10,4),
@nDiaOut DECIMAL(10,4)
)

RETURNS DECIMAL(5,4)
AS
BEGIN
--PRINT dbo.[f_Calc_CW](.3,.25)
--PRINT dbo.[f_Calc_CW](dbo.f_Get_Next_Dia(Dia),Dia)
--Calculate ColdWork on Diameter CW
--SET NOCOUNT ON
--[ A0-Af ] / A0

IF @nDiaIn*@nDiaOut = 0
	RETURN 0

IF @nDiaIn<=@nDiaOut
	RETURN 0

DECLARE @nCW DECIMAL(5,4)

SET @nCW = CAST(((@nDiaIn*@nDiaIn)-(@nDiaOut*@nDiaOut))/ (@nDiaIn*@nDiaIn) AS DECIMAL(5,4))

RETURN ISNULL(@nCW,0)
END


-- GRANT EXECUTE ON [dbo].[f_Calc_CW] TO [WINDFALL\HPA] AS [dbo];' 
END
GO
/****** Object:  UserDefinedFunction [dbo].[f_Calc_CW_Input]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_Calc_CW_Input]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'
CREATE FUNCTION [dbo].[f_Calc_CW_Input] 
(
@nWorkSize DECIMAL(10,4),
@nlevel TinyInt
)

RETURNS DECIMAL(10,4)
AS
BEGIN
--PRINT dbo.[f_Calc_CW_Input](0.3,4)  --.4110
--PRINT dbo.[f_Calc_CW_Input](1.3,4)  --.4370
--PRINT dbo.[f_Calc_CW_Input](2.3,4)  --.4760

--Calculate ColdWork and sSize to achieve Level
--Does not return a Standard Dia
--USE dbo.f_Calc_CW_Stand_sSize(2,.05,.42)(WorkDia,+Tol,CW) to get a bar standard Dia

--SET NOCOUNT ON
--[ A0-Af ] / A0

IF @nWorkSize= 0
	RETURN 0

IF @nlevel < 1 or @nlevel > 6
	RETURN 0

DECLARE @nColdWork DECIMAL(4,3) = 0
SET @nColdWork = dbo.f_Calc_CW_Level(@nWorkSize,@nlevel)  --.4110

IF @nColdWork > 0
	-- ColdWork = [ A0-Af ] / A0 = [1 -Af/ A0 ] 
	--                      ColdWork * A0 = 1-Af
	-- StartSize A0 = (1-Af)/ColdWork
	--SET @nCW = CAST(((@nDiaIn*@nDiaIn)-(@nDiaOut*@nDiaOut))/ (@nDiaIn*@nDiaIn) AS DECIMAL(5,4))

	DECLARE @nsSize decimal(10,3) = 0
	--sSize = WorkSize / √(1 - ColdWork)
	SET @nsSize = @nWorkSize / SQRT(1-@nColdWork)

	--@nStandDia = dbo.f_Calc_CW_Stand_sSize(@nsSize,.05,@nColdWork)

RETURN ISNULL(@nsSize,0)
END


-- GRANT EXECUTE ON [dbo].[f_Calc_CW_Input] TO [WINDFALL\HPA] AS [dbo];' 
END
GO
/****** Object:  UserDefinedFunction [dbo].[f_Calc_CW_Level]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_Calc_CW_Level]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'
CREATE FUNCTION [dbo].[f_Calc_CW_Level] 
(
@nWorkSize DECIMAL(10,4),
@nlevel TinyInt
)

RETURNS DECIMAL(10,3)
AS
BEGIN
--PRINT dbo.[f_Calc_CW_Level](0.3,4)  --.4110
--PRINT dbo.[f_Calc_CW_Level](1.3,4)  --.4370
--PRINT dbo.[f_Calc_CW_Level](2.3,4)  --.4760

--Calculate ColdWork to achieve Level
--See SELECT dbo.f_Is_GFMlot_toSpec(4800,''HPA-MS-102                    '','''') AS MS_102
-- to list the Level


--SET NOCOUNT ON
--[ A0-Af ] / A0

IF @nWorkSize= 0
	RETURN 0

IF @nlevel < 1 or @nlevel > 6
	RETURN 0

DECLARE @nColdWork DECIMAL(4,3) = 0

IF @nWorkSize < .5
	begin
	--PRINT ''0-0.5''

	IF @nlevel = 1
		SET @nColdWork = .147

	ELSE IF @nlevel = 2
		SET @nColdWork = .279

	ELSE IF @nlevel = 3
		SET @nColdWork = .350

	ELSE IF @nlevel = 4
		SET @nColdWork = .411

	ELSE IF @nlevel = 5
		SET @nColdWork = .542

	ELSE IF @nlevel = 6
		SET @nColdWork = .610

	end
ELSE IF @nWorkSize >= .5 AND @nWorkSize < 1
	begin
	--PRINT ''0.5-1''

	IF @nlevel = 1
		SET @nColdWork = .139

	ELSE IF @nlevel = 2
		SET @nColdWork = .214

	ELSE IF @nlevel = 3
		SET @nColdWork = .326

	ELSE IF @nlevel = 4
		SET @nColdWork = .401

	ELSE IF @nlevel = 5
		SET @nColdWork = .494

	ELSE IF @nlevel = 6
		SET @nColdWork = .540

	end 
ELSE IF @nWorkSize >= 1 AND @nWorkSize < 1.5
	begin
	--PRINT ''1-1.5''

	IF @nlevel = 1
		SET @nColdWork = .120

	ELSE IF @nlevel = 2
		SET @nColdWork = .233

	ELSE IF @nlevel = 3
		SET @nColdWork = .338

	ELSE IF @nlevel = 4
		SET @nColdWork = .437

	ELSE IF @nlevel = 5
		SET @nColdWork = .497

	ELSE IF @nlevel = 6
		SET @nColdWork = .526

	end 
ELSE IF @nWorkSize >= 1.5 AND @nWorkSize < 2
	begin
	--PRINT ''1.5-2''
	
	IF @nlevel = 1
		SET @nColdWork = .148

	ELSE IF @nlevel = 2
		SET @nColdWork = .226

	ELSE IF @nlevel = 3
		SET @nColdWork = .364

	ELSE IF @nlevel = 4
		SET @nColdWork = .486

	ELSE IF @nlevel = 5
		SET @nColdWork = .509

	ELSE IF @nlevel = 6
		SET @nColdWork = .56


	end 
ELSE IF @nWorkSize >= 2 AND @nWorkSize < 2.5
	begin
	--PRINT ''2-2.5''

	IF @nlevel = 1
		SET @nColdWork = .141

	ELSE IF @nlevel = 2
		SET @nColdWork = .270

	ELSE IF @nlevel = 3
		SET @nColdWork = .362

	ELSE IF @nlevel = 4
		SET @nColdWork = .476

	ELSE IF @nlevel = 5
		SET @nColdWork = .51

	ELSE IF @nlevel = 6
		SET @nColdWork = .55


	end 

ELSE IF @nWorkSize >= 2.5 AND @nWorkSize < 3
	begin
	--PRINT ''2.5-3''
	
	IF @nlevel = 1
		SET @nColdWork = .126

	ELSE IF @nlevel = 2
		SET @nColdWork = .265

	ELSE IF @nlevel = 3
		SET @nColdWork = .362

	ELSE IF @nlevel = 4
		SET @nColdWork = .422

	ELSE IF @nlevel = 5
		SET @nColdWork = .48

	ELSE IF @nlevel = 6
		SET @nColdWork = .55


	end 
ELSE IF @nWorkSize >= 3 AND @nWorkSize < 3.5
	begin
	--PRINT ''3-3.5''
	
	IF @nlevel = 1
		SET @nColdWork = .148

	ELSE IF @nlevel = 2
		SET @nColdWork = .240

	ELSE IF @nlevel = 3
		SET @nColdWork = .382

	ELSE IF @nlevel = 4
		SET @nColdWork = .45

	ELSE IF @nlevel = 5
		SET @nColdWork = .49

	ELSE IF @nlevel = 6
		SET @nColdWork = .55

	end 
ELSE IF @nWorkSize >= 3.5 AND @nWorkSize < 4
	begin
	--PRINT ''3.5-4''
	
	IF @nlevel = 1
		SET @nColdWork = .168

	ELSE IF @nlevel = 2
		SET @nColdWork = .28

	ELSE IF @nlevel = 3
		SET @nColdWork = .33

	ELSE IF @nlevel = 4
		SET @nColdWork = .42

	ELSE IF @nlevel = 5
		SET @nColdWork = .48

	ELSE IF @nlevel = 6
		SET @nColdWork = .55

	end 

ELSE IF @nWorkSize >= 4 AND @nWorkSize < 4.5
	begin
	--PRINT ''4-4.5''
	
	IF @nlevel = 1
		SET @nColdWork = .15

	ELSE IF @nlevel = 2
		SET @nColdWork = .206

	ELSE IF @nlevel = 3
		SET @nColdWork = .269

	ELSE IF @nlevel = 4
		SET @nColdWork = .43

	ELSE IF @nlevel = 5
		SET @nColdWork = .48

	ELSE IF @nlevel = 6
		SET @nColdWork = .55

	end 
