	begin
	--PRINT ''4.5-5''
	end 

ELSE IF @nWorkSize >= 5 AND @nWorkSize < 5.5
	begin
	--PRINT ''5-5.5''
	end 
ELSE IF @nWorkSize >= 5.5 AND @nWorkSize < 6
	begin
	--PRINT ''5.5-6''
	end 
*/



RETURN ISNULL(@nColdWork,0)
END


