	@cCL CHAR(1),
	@nfSize Decimal(9,3)
)
RETURNS TinyInt
AS
BEGIN


--SELECT dbo.f_CC_CL_Max_Cw(''HPA N60'',''7'',''2'',1)
DECLARE @ReturnTinyInt TinyInt = 0
		

	SELECT @ReturnTinyInt =
		Max(t.MaxCW) * 100
	 FROM (
		SELECT 
