		FROM dbo.GFMlog G 
		INNER JOIN dbo.NR_AlloyCodeLevel l ON G.AlloyName = l.Alloy 
			AND l.CC = @cCC
			AND l.CL = @cCL
			AND G.Tensile > (ISNULL(l.UTS,0)+1)*1000 
