/****** Object:  UserDefinedFunction [dbo].[f_CCCLtoOldCC]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_CCCLtoOldCC]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'CREATE FUNCTION [dbo].[f_CCCLtoOldCC]
(
@cCC CHAR(1)
,@cCL CHAR(1)
)
RETURNS CHAR(1)
AS
BEGIN
-- PRINT SELECT dbo.f_CCCLtoOldCC(''8'',''2'')

DECLARE @cCCStandard CHAR(1)

declare @err int,
        @RC int

set @err = 0
set @rc = 0

SET @cCCStandard = ''1''

SET @cCCStandard = 
	CASE @cCC 
	WHEN ''7'' THEN ( 
		CASE @cCL 
		WHEN ''1'' THEN ''T''
		WHEN ''2'' THEN ''U''
		WHEN ''3'' THEN ''V''
		WHEN ''4'' THEN ''W''
		WHEN ''5'' THEN ''X''
		WHEN ''6'' THEN ''Y''	
		END
		)
	WHEN ''S'' THEN ( 
		CASE @cCL 
		WHEN ''1'' THEN ''T''
		WHEN ''2'' THEN ''U''
		WHEN ''3'' THEN ''V''
		WHEN ''4'' THEN ''W''
		WHEN ''5'' THEN ''X''
		WHEN ''6'' THEN ''Y''
		END	
		)
	WHEN ''L'' THEN ( 
		CASE @cCL 
		WHEN ''1'' THEN ''A''
		WHEN ''2'' THEN ''B''
		WHEN ''3'' THEN ''C''
		WHEN ''4'' THEN ''D''
		WHEN ''5'' THEN ''E''
		END	
		)
	ELSE @cCC END
	
--select @RC = @@ROWCOUNT, @err = @@ERROR

RETURN @cCCStandard
END

' 
END
GO
