BEGIN
execute dbo.sp_executesql @statement = N'
create FUNCTION [dbo].[f_CountIDinLst_Detail] 
(
@ID INT,
@TBL CHAR(1)
)
RETURNS INT
AS
BEGIN
DECLARE @nCount INT = 0


IF @TBL = ''S''
	SELECT @nCount = COUNT(ID_Detail) 
	FROM dbo.StockLst_Detail 
	WHERE ID = @ID

IF @TBL = ''B''
	SELECT @nCount = COUNT(ID_Detail) 
	FROM dbo.BrokerLst_Detail 
	WHERE ID = @ID

IF @TBL = ''W''
	SELECT @nCount = COUNT(ID_Detail) 
	FROM dbo.WIPLst_Detail 
	WHERE ID = @ID

RETURN (@nCount)
END

' 
END
