AS
BEGIN
-- test
--SELECT dbo.f_Descript(''C-276'',''B'',''40'',.25,36,120,0,0)
--dbo.f_Descript(Alloy,CC,Form,Thck,Sz2,Sz3,Weight,RandLen)
