IF @cString LIKE ''[A-Z]%''
	SET @cMachine = TRIM(SUBSTRING(@cString,PATINDEX(''[A-Z]%'',@cString),1))




--See if Initial is possible, return ''''
IF LEN(dbo.f_GetMachine_Table(@cMachine)) = 0
	RETURN ''''


RETURN @cMachine
