CREATE FUNCTION [dbo].[f_Get_Price_Lot]
(	
	@iPieces INT
	,@cAlloy CHAR(12)
	,@cForm  CHAR(2)
	,@nThck Decimal(10,4)
	,@nSz2 Decimal(9,3)
	,@nSz3 Decimal(9,3)
	,@nWeight Decimal(9,1)
	,@mP_LB Money
	,@mP_Pc Money
	,@mP_Ft Money
	,@mLotP Money

)
RETURNS MONEY
AS
BEGIN

--depricated ; use [f_GetPriceQuote] 

--use f_GetPrice_lot for McMaster

-- Print dbo.f_get_P(@Pieces,@Alloy,@Form,@Thck,@Sz2,@Sz3,@Weight,@P_LB,@P_Pc,@P_Ft,@LotP)
-- Print dbo.f_get_P( Pieces, Alloy, Form, Thck, Sz2, Sz3, Weight, P_LB, P_Pc, P_Ft, LotP)
--like dbo.f_Calc_QTY(Alloy,Form,Pieces,Thck,Sz2,Sz3)
--

declare @err int,
        @RC int

set @err = 0
set @rc = 0


DECLARE @tiSigDim TinyInt
DECLARE @iFtLen INT
SET @tiSigDim = 0
SET @iFtLen = 0

IF @mLotP = 0
	begin
	-- get Universal LotP

	
	IF @mP_LB > 0
		begin

		IF @nWeight = 0
			SET @nWeight = dbo.f_Calc_Weight(@cAlloy,@cForm,@iPieces,@nThck,@nSz2,@nSz3) 
		
		
		IF @nWeight > 0
			SET @mLotP = @mP_LB * @nWeight
		ELSE
			SET @mLotP = -1
		
		end

	IF @mP_Ft > 0
		begin

		If @iPieces < 1 
				SET @iPieces = 1

		SET @tiSigDim = dbo.f_getSigDim( @cForm )

		IF @tiSigDim = 2
			SET @iFtLen = @iPieces * @nSz2/12
		
		IF @tiSigDim = 3 OR @tiSigDim = 6
			SET @iFtLen = @iPieces * @nSz3/12
		
		IF @iFtLen > 0
			SET @mLotP = @mP_Ft * @iFtLen
		ELSE
			SET @mLotP = -1
		
		end

	IF @mP_Pc > 0
		IF @iPieces > 0
			SET @mLotP = @mP_Pc * @iPieces
		ELSE
			SET @mLotP = -1

	end
------------


DECLARE @mNew_P MONEY
DECLARE @tiPU TinyInt

SET @mNew_P	= 0
SET @tiPU	=  dbo.f_GetFormPU( @cForm )

IF @tiPU = 1
	-- $/Lb
	IF @mP_LB > 0
		SET @mNew_P = @mP_LB
	ELSE
		begin

		--*Convert to $/Lb
		IF @nWeight = 0
			SET @nWeight = dbo.f_Calc_Weight(@cAlloy,@cForm,@iPieces,@nThck,@nSz2,@nSz3) 
		

		IF @nWeight > 0
			IF @mLotP > 0
				SET @mNew_P = ROUND( @mLotP / @nWeight, 4)
			
		end

IF @tiPU = 2
	--* $/Ft
	IF @mP_Ft > 0
		SET @mNew_P = @mP_Ft
	ELSE
		begin

		--*Convert to $/Ft
		IF @iFtLen = 0
			begin

			If @iPieces < 1 
				SET @iPieces = 1

			SET @tiSigDim = dbo.f_getSigDim(@cForm)

			IF @tiSigDim = 2
				SET @iFtLen = @iPieces * @nSz2/12
			
			IF @tiSigDim = 3 OR @tiSigDim = 6
				SET @iFtLen = @iPieces * @nSz3/12
			
			end

		IF @iFtLen > 0
			IF @mLotP > 0
				SET @mNew_P = ROUND( @mLotP / @iFtLen, 4)
		
		end
		
IF @tiPU = 3
	--* $/Pc
	IF @mP_Pc > 0
		SET @mNew_P = @mP_Pc
	ELSE
		IF @iPieces > 0
			IF @mLotP > 0
				SET @mNew_P = ROUND( @mLotP / @iPieces, 4)
			
RETURN @mNew_P
END

' 
END
GO
