WHERE (MWeight+10)*1.2 < dbo.f_Calc_mS_QTY_StockLst_ID(ID)+10
OR MWeight+10 > (dbo.f_Calc_mS_QTY_StockLst_ID(ID)+10)*1.2
*/

DECLARE @MWeight Decimal(18,8)

