	SET @cSO = LEFT(@cSO, CHARINDEX(''-'',@cSO)-1 )

--Convert to number
--IF ISNUMERIC(@cSO) = 1
--	SET @nSalesNum = CAST(@cSO AS INT)

SET @nSalesNum = Try_Cast(@cSO AS INT)


RETURN @nSalesNum
END


' 
END
