		SET @nCurrentInt = @nCurrentInt - 16384
		--SET @cReturn = @cReturn + ''Fabricator ''
		SELECT @cReturn = @cReturn + RTRIM(Industry) + '' '' FROM dbo.IND_type WHERE Number = 16384
