(
@cSOitem CHAR(10)

)
RETURNS BIT
AS
BEGIN

--SELECT dbo.f_Is_HPA_Cert('''')

DECLARE @lReturn BIT

declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @nCount INT

SELECT @nCount = COUNT(PS.Packingsli)
	FROM dbo.PackingSlip PS WITH(NOLOCK)
	WHERE PS.SOitem = @cSOitem
	AND Heat LIKE ''%HPA%''

SET @lReturn = 0
IF @nCount > 0
	SET @lReturn = 1

	
RETURN @lReturn
END
