/****** Object:  UserDefinedFunction [dbo].[f_Is_IND_Type]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_Is_IND_Type]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'
CREATE FUNCTION [dbo].[f_Is_IND_Type] 
(
@nVendCode INT,
@nIND_Type INT
)
RETURNS BIT
AS
BEGIN
--Is the Vendor of a certain IND_Type
--SELECT dbo.f_Is_IND_Type( 10012, 2 ) AS IsType

--Also see f_IND_Type, f_Is_IND_Complete_Type
--Also See p_IND_Number, p_IND_Type

DECLARE @lReturn BIT
SET @lReturn = 0

DECLARE @nInd_Type2 INT
SELECT @nInd_Type2 = Ind_Type FROM dbo.Vendor WHERE VendCode = @nVendCode

IF @nInd_Type2 >= 131072
	begin
	IF @nIND_Type = 131072
		RETURN 1
		--''Government ''

	SET @nInd_Type2 = @nInd_Type2 - 131072
	end

IF @nInd_Type2 >= 65536
	begin
	IF @nIND_Type = 65536
		RETURN 1
		--''GOV_Sub ''

	SET @nInd_Type2 = @nInd_Type2 - 65536
	end

IF @nInd_Type2 >= 32768
	begin
	--Food
	IF @nIND_Type = 32768
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 32768

	end

IF @nInd_Type2 >= 16384
	begin
	--Fabricator
	IF @nIND_Type = 16384
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 16384

	end
IF @nInd_Type2 >= 8192
	begin
	--Medical
	IF @nIND_Type = 8192
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 8192

	end

IF @nInd_Type2 >= 4096
	begin
	--Service
	IF @nIND_Type = 4096
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 4096

	end
		
IF @nInd_Type2 >= 2048
	begin
	--Conversion
	IF @nIND_Type = 2048
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 2048

	end
		
IF @nInd_Type2 >= 1024
	begin
	--Nuclear
	IF @nIND_Type = 1024
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 1024

	end
		
IF @nInd_Type2 >= 512
	begin
	--Military
	IF @nIND_Type = 512
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 512

	end
		
IF @nInd_Type2 >= 256
	begin
	--Pharm
	IF @nIND_Type = 256
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 256

	end
	
IF @nInd_Type2 >= 128
	begin
	--oil
	IF @nIND_Type = 128
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 128

	end
		
IF @nInd_Type2 >= 64
	--Chemical
	begin
	IF @nIND_Type = 64
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 64

	end
	
IF @nInd_Type2 >= 32
	begin
	--AeroSpace
	IF @nIND_Type = 32
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 32

	end
		
IF @nInd_Type2 >= 16
	begin
	--HighTemp
	IF @nIND_Type = 16
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 16

	end
		
IF @nInd_Type2 >= 8
	begin
	--Wear
	IF @nIND_Type = 8
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 8

	end

IF @nInd_Type2 >= 4
	begin
	--Corrosion
	IF @nIND_Type = 4
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 4

	end

IF @nInd_Type2 >= 2
	begin
	--Competitor
	IF @nIND_Type = 2
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 2
	
	end

IF @nInd_Type2 >= 1
	begin
	--Consumer
	IF @nIND_Type = 1
		SET @lReturn = 1
	
	SET @nInd_Type2 = @nInd_Type2 - 1
	
	end


RETURN @lReturn

END
' 
END
