/****** Object:  UserDefinedFunction [dbo].[f_LMA_Gr]    Script Date: 12/26/2025 5:48:51 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[f_LMA_Gr]') AND type in (N'FN', N'IF', N'TF', N'FS', N'FT'))
BEGIN
execute dbo.sp_executesql @statement = N'
CREATE FUNCTION [dbo].[f_LMA_Gr] 
(
@cCC char(1),
@cCL CHAR(1),
@cDescript VARCHAR(50),
@cComments VarChar(MAX)
)
RETURNS TinyInt
AS
BEGIN

--SELECT dbo.f_LMA_Gr(@CC,@CL,@cDescript,@cComments)
--SELECT dbo.f_LMA_Gr(AQ.CC,AQ.CL,AQ.Descript,AQ.Comments)

--SELECT dbo.f_SPX_Gr(@CC,@CL,@cDescript,@cComments)
--SELECT * FROM dbo.ConditionCode
-- LMA M7060

DECLARE @LMA TinyInt = 0

IF @cCC=''L''
	begin
	IF @cCL = ''1''
		SET @LMA = 1
	ELSE
	IF @cCL = ''2''
		SET @LMA = 2
	ELSE
	IF @cCL = ''3''
		SET @LMA = 3
	ELSE
	IF @cCL = ''4''
		SET @LMA = 4
	ELSE
	IF @cCL = ''5''
		SET @LMA = 5
	ELSE
	IF @cCL = ''6''
		SET @LMA = 6
	
	IF @LMA>0
		RETURN (@LMA)

	end


-- CC is not ''L'' and CL not 1-6
-- ignore CC, check Descript

DECLARE @FoundLMA BIT = 0
IF @cDescript LIKE ''%LMA%''
	begin
	SET @FoundLMA = 1

	IF @cCL = ''1''
		SET @LMA = 1
	ELSE
	IF @cCL = ''2''
		SET @LMA = 2
	ELSE
	IF @cCL = ''3''
		SET @LMA = 3
	ELSE
	IF @cCL = ''4''
		SET @LMA = 4
	ELSE
	IF @cCL = ''5''
		SET @LMA = 5
	ELSE
	IF @cCL = ''6''
		SET @LMA = 6
	
	IF @LMA > 0
		RETURN (@LMA)

	end

--Exit if not LMA
--IF @FoundLMA = 0
--	RETURN 0

DECLARE @cGrade CHAR(5) = ''''
DECLARE @nGradeAt TinyInt = 0
DECLARE @nGradeNum TinyInt = 0

--Locate Grade GRADE
SET @nGradeAt =  CHARINDEX(''GRADE'',@cDescript)
IF @nGradeAt > 0 AND @FoundLMA = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+6, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		--ELSE
		-- Check Comments
		

	end

--
--Locate Grade GR.
SET @nGradeAt =  CHARINDEX(''GR. '',@cDescript)
IF @nGradeAt > 0 AND @FoundLMA = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+4, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		--ELSE
		-- Check Comments
		

	end

--Locate Grade GR
SET @nGradeAt =  CHARINDEX(''GR '',@cDescript)
IF @nGradeAt > 0 AND @FoundLMA = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+3, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		--ELSE
		--check comments
		--	RETURN 0
	
	end

--Locate Grade LEVEL
SET @nGradeAt =  CHARINDEX(''LEVEL'',@cDescript)
IF @nGradeAt > 0 AND @FoundLMA = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+5, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		--ELSE
		--Check Comments
			
	end

--------------------------------
--------------------------------
--------------------------------
-- CC is not ''L'' and CL not 1-6
-- ignore CC, checking comments

SET @FoundLMA = 0
IF @cComments LIKE ''%LMA%''
	begin
	SET @FoundLMA = 1

	IF @cCL = ''1''
		SET @LMA = 1
	ELSE
	IF @cCL = ''2''
		SET @LMA = 2
	ELSE
	IF @cCL = ''3''
		SET @LMA = 3
	ELSE
	IF @cCL = ''4''
		SET @LMA = 4
	ELSE
	IF @cCL = ''5''
		SET @LMA = 5
	ELSE
	IF @cCL = ''6''
		SET @LMA = 6
	
	IF @LMA > 0
		RETURN (@LMA)

	end

--------------------------------
--Exit if not LMA or Descript
IF @FoundLMA = 0
	RETURN 0

SET @cGrade = ''''
SET @nGradeAt = 0
SET @nGradeNum = 0

--Locate Grade
SET @nGradeAt =  CHARINDEX(''GRADE'',@cComments)
IF @nGradeAt > 0 SET @FoundLMA = 1
	begin

	SET @cGrade = SUBSTRING ( @cComments, @nGradeAt+6, 2 ) 
	--SET @nGradeNum = CAST(@cGrade AS TinyInt )
	--SET @nGradeNum = CONVERT(INT, REPLACE(@cGrade, CHAR(0), ''''))
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		ELSE
			RETURN 0

	end

--
--Locate Grade
SET @nGradeAt =  CHARINDEX(''GR. '',@cComments)
IF @nGradeAt > 0
	begin

	SET @cGrade = SUBSTRING ( @cComments, @nGradeAt+4, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		ELSE
			RETURN 0
	end

--Locate Grade
SET @nGradeAt =  CHARINDEX(''GR '',@cComments)
IF @nGradeAt > 0
	begin

	SET @cGrade = SUBSTRING ( @cComments, @nGradeAt+3, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		ELSE
			RETURN 0
	
	end

--Locate Grade
SET @nGradeAt =  CHARINDEX(''LEVEL'',@cComments)
IF @nGradeAt > 0
	begin

	SET @cGrade = SUBSTRING ( @cComments, @nGradeAt+5, 2 ) 
	--SET @nGradeNum = CAST(@cGrade AS TinyInt )
	--SET @nGradeNum = CONVERT(INT, REPLACE(@cGrade, CHAR(0), ''''))
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @LMA = 1
		ELSE
		IF @cGrade like ''2%''
			SET @LMA = 2
		ELSE
		IF @cGrade like ''3%''
			SET @LMA = 3
		ELSE
		IF @cGrade like ''4%''
			SET @LMA = 4
		ELSE
		IF @cGrade like ''5%''
			SET @LMA = 5
		ELSE
		IF @cGrade like ''6%''
			SET @LMA = 6
	
		IF @LMA > 0
			RETURN (@LMA)


		end
		ELSE
			RETURN 0

	end


RETURN @LMA

END



