 --AND AQ.HPApo > 0
 AND S.Typ = ''B''
 AND AQ.Alloy = @Alloy
 AND AQ.Form = @Form
 AND dbo.f_GetCCSortValue(AQ.CC) = dbo.f_GetCCSortValue(@CC)
 AND AQ.StandardSize = ERP_1.dbo.f_SizeStandard(@Size)
 AND S.cncld = 0

SET @nReturn = ISNULL(@nReturn,0)
RETURN @nReturn

END
' 
END
