(
@INT1 INT
,@INT2 INT
)
RETURNS INT

--returns the Higher INT
--Never return NULL
--Do not use 0 as lowest!

AS
BEGIN

--SELECT dbo.f_Return_Lower_INT (2,3) ; SELECT dbo.f_Return_Lower_INT (3,2) ;SELECT dbo.f_Return_Lower_INT (1,0) ; SELECT dbo.f_Return_Lower_INT (0,1)

