execute dbo.sp_executesql @statement = N'CREATE FUNCTION [dbo].[f_SizeStandard] (
@nThickness DECIMAL(9,4)
)
RETURNS DECIMAL(9,3)
AS
--Name is backwards, use StandadSize

-- PRINT dbo.f_SizeStandard(.060)
-- Returns value from a Size case statement
-- Used in Reports for conformity
--
--Also See: f_StandardSize  -- Returns value from StandardSize table
--
-- Tables like NR:
--UPDATE dbo.NR_Sales_Summary SET Size=ERP_1.dbo.f_SizeStandard(Size) WHERE Size<>ERP_1.dbo.f_SizeStandard(Size)


--UPDATE dbo.NR_StockLst_Totals SET Size=ERP_1.dbo.f_SizeStandard(Size) WHERE Size<>ERP_1.dbo.f_SizeStandard(Size)
--    SQL Server Agent job [End of Month Stock Totals] EXEC dbo.p_StockLst_Make_Totals

--UPDATE ERP_1.dbo.StockLst_Mins SET Thck=dbo.f_SizeStandard(Thck) WHERE Thck<>dbo.f_SizeStandard(Thck)

--UPDATE ERP_1.dbo.AllQuotes SET StandardSize=dbo.f_SizeStandard(Thck) WHERE StandardSize<>dbo.f_SizeStandard(Thck)
--SELECT Thck,StandardSize,dbo.f_SizeStandard(Thck) FROM ERP_1.dbo.AllQuotes  WHERE StandardSize<>dbo.f_SizeStandard(Thck)
--

BEGIN

DECLARE @nSizeStandard NUMERIC(9,3)
