CREATE FUNCTION [dbo].[f_SPX_Gr] 
(
@cCC char(1),
@cCL CHAR(1),
@cDescript VARCHAR(50),
@cComments VarChar(MAX)
)
RETURNS TinyInt
AS
BEGIN

--SELECT dbo.f_SPX_Gr(@CC,@CL,@cDescript,@cComments)

DECLARE @SPX TinyInt = 0

IF @cCC=''S''
	begin
	IF @cCL = ''1''
		SET @SPX = 1
	ELSE
	IF @cCL = ''2''
		SET @SPX = 2
	ELSE
	IF @cCL = ''3''
		SET @SPX = 3
	ELSE
	IF @cCL = ''4''
		SET @SPX = 4
	ELSE
	IF @cCL = ''5''
		SET @SPX = 5
	ELSE
	IF @cCL = ''6''
		SET @SPX = 6
	
	IF @SPX>0
		RETURN (@SPX)

	end


-- CC is not ''S'' and CL not 1-5
-- ignore CC, check Descript

DECLARE @FoundSPX BIT = 0
IF @cDescript LIKE ''%SPX%''
	begin
	SET @FoundSPX = 1

	IF @cCL = ''1''
		SET @SPX = 1
	ELSE
	IF @cCL = ''2''
		SET @SPX = 2
	ELSE
	IF @cCL = ''3''
		SET @SPX = 3
	ELSE
	IF @cCL = ''4''
