IF @nGradeAt > 0 AND @FoundSPX = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+6, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @SPX = 1
		ELSE
		IF @cGrade like ''2%''
			SET @SPX = 2
		ELSE
		IF @cGrade like ''3%''
			SET @SPX = 3
		ELSE
