			SET @SPX = 6

		IF @SPX > 0
			RETURN (@SPX)


		end
		--ELSE
		-- Check Comments
		

	end

--
--Locate Grade
SET @nGradeAt =  CHARINDEX(''GR. '',@cDescript)
IF @nGradeAt > 0 AND @FoundSPX = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+4, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
