			SET @SPX = 6
	
		IF @SPX > 0
			RETURN (@SPX)


		end
		--ELSE
		--check comments
		--	RETURN 0
	
	end

--Locate Grade
SET @nGradeAt =  CHARINDEX(''LEVEL'',@cDescript)
IF @nGradeAt > 0 AND @FoundSPX = 1
	begin

	SET @cGrade = SUBSTRING ( @cDescript, @nGradeAt+5, 2 ) 
	SET @cGrade = LTRIM(RTRIM(@cGrade))

	IF LEN(@cGrade) > 0
		begin
		IF @cGrade like ''1%''
			SET @SPX = 1
		ELSE
		IF @cGrade like ''2%''
			SET @SPX = 2
		ELSE
		IF @cGrade like ''3%''
			SET @SPX = 3
		ELSE
