			RETURN (@SPX)


		end
		--ELSE
		--Check Comments
			
	end

--------------------------------
--------------------------------
--------------------------------
-- CC is not ''S'' and CL not 1-5
-- ignore CC, checking comments

SET @FoundSPX = 0
IF @cComments LIKE ''%SPX%''
	begin
	SET @FoundSPX = 1

