	--SET @nGradeNum = CAST(@cGrade AS TinyInt )
	--SET @nGradeNum = CONVERT(INT, REPLACE(@cGrade, CHAR(0), ''''))
	SET @cGrade = LTRIM(RTRIM(@cGrade))

