ALTER PROCEDURE [dbo].[p_AllQuotes_AddPOitem]
	@BuyFrom	VarChar(15),
	@pPOitem		CHAR(12),
	@pSOitem		CHAR(10)
AS

--EXEC dbo.p_AllQuotes_AddPOitem 'BuyFrom','POitem','SOitem'

--fill the AllQuotes fields, HPAPO and HPAPO2

Set NoCount On
DECLARE @PO INT = 0
DECLARE @POitem	CHAR(12)
SET @POitem = dbo.f_ProperPOitem( @pPOitem )
SET @PO = CAST(@POitem AS INT)
DECLARE @SOitem	CHAR(10)
SET @SOitem = dbo.f_ProperSOitem( @pSOitem )

DECLARE @cnt AS INT
SET @cnt = 0
SELECT @cnt = COUNT(*) FROM dbo.AllQuotes WITH(NOLOCK) WHERE SOitem = @SOitem

IF @cnt > 0
	BEGIN
	
	--If the SOitem is Found in HPApo
	SELECT @cnt = COUNT(*) FROM dbo.AllQuotes 
		WHERE SOitem = @SOitem 
		AND  POitem = @POitem
		--AND BuyFrom = @BuyFrom
		--AND ( HPApo = @PO OR HPApo2 = @PO )
	IF @cnt >= 1
		GOTO DONE
		--Found POitem with the SOitem 
/*	
	--check HPApo
	SET @cnt = 0
	SELECT @cnt = COUNT(*) FROM dbo.AllQuotes 
		WHERE SOitem = @SOitem 
		AND HPApo = @PO
	IF @cnt >= 1
		GOTO DONE
		--Found PO with the SOitem 

	--check HPApo2
	SET @cnt = 0
	SELECT @cnt = COUNT(*) FROM dbo.AllQuotes 
		WHERE SOitem = @SOitem 
		AND HPApo2 = @PO
	IF @cnt >= 1
		GOTO DONE
		--Found PO with the SOitem 
	
*/	
	SET @cnt = 0	
	--Get HPAPO and HPAPO2
	DECLARE @HPAPO INT = 0
	DECLARE @HPAPO2 INT = 0
	DECLARE @fndPOitem	CHAR(12)=''

	SELECT @HPAPO=ISNULL(HPAPO,0), @HPAPO2=ISNULL(HPApo2,0), @fndPOitem=dbo.f_ProperPOitem(ISNULL(POitem,'')) 
		FROM dbo.AllQuotes WITH(NOLOCK)
		WHERE SOitem = @SOitem 
		
	IF @HPAPO = @PO OR @HPAPO2 = @PO	
		begin
			--found PO, save Name Change?
			IF @HPAPO = @PO
				UPDATE dbo.AllQuotes SET BuyFrom = @BuyFrom, POitem = @POitem WHERE SOitem = @SOitem
				
			IF @HPAPO2 = @PO
				UPDATE dbo.AllQuotes SET BuyFrom2 = @BuyFrom WHERE SOitem = @SOitem
				
			GOTO DONE
		end
		--Found PO with that SOitem 
		
	--Did not find PO being used!
	--Is there an empty PO spot to use?
	IF @HPAPO = 0 AND @fndPOitem = dbo.f_ProperPOitem( '' )
		BEGIN
			UPDATE dbo.AllQuotes SET HPAPO=@PO, BuyFrom = @BuyFrom, POitem = @POitem WHERE SOitem = @SOitem
			GOTO DONE
		END
		
	ELSE
		IF @HPAPO2 = 0
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO2=@PO, BuyFrom2 = @BuyFrom WHERE SOitem = @SOitem
			GOTO DONE
			END
			
	--No empty PO spots to Add PO
	--Value the PO's		
	DECLARE @nPOiv		TinyInt = 0
	DECLARE @nHPAPOv	TinyInt = 0
	DECLARE @nHPAPO2v	TinyInt = 0
	
	
	SELECT @nPOiv = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE POitem = @POitem
		
	SELECT @nHPAPOv = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE HPApo = @HPAPO	

		
	SELECT @nHPAPO2v = CASE 
			WHEN ISNULL(Cancelled,0) = 1 THEN 1
			WHEN ISNULL(Services,0) = 1 THEN 2
			WHEN ISNULL(Equipment,0) = 1 THEN 3
			WHEN ISNULL(ConvServ,0) = 1 THEN 4
			WHEN ISNULL(Delivered,0) = 1 THEN 5
			WHEN ISNULL(Printed,0) = 1 THEN 6
			ELSE 9 END
		FROM dbo.PurchaseOrder WHERE HPApo = @HPAPO2
	
	IF @nPOiv < @nHPAPOv AND @nPOiv < @nHPAPO2v
		BEGIN
		--Need to Swap and use the nPO
		IF @nPOiv < @nHPAPOv
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO=@PO, BuyFrom = @BuyFrom, POitem = @POitem WHERE SOitem = @SOitem
			GOTO DONE
			END
		
		IF @nPOiv < @nHPAPO2v
			BEGIN
			UPDATE dbo.AllQuotes SET HPAPO2=@PO, BuyFrom2 = @BuyFrom WHERE SOitem = @SOitem
			GOTO DONE
			END

		END
	
	END
	
/* at the end of the sp */
DONE:
GO
