--	@Cover [char](1),
--	@Cut [char](1) ,
	

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;
	--EXEC dbo.p_AllQuotes_ins @SalesP = 'D'

	DECLARE @InqNum [int]
	DECLARE @InqNumP [char](9) 
	DECLARE @ID int
	
	SET @ID = 0
	
	--Grab InqNum, then try to insert.
	SELECT @InqNum = MAX(inqnum) FROM dbo.AllQuotes WHERE SalesP = @SalesP
	IF @InqNum = null
	BEGIN
		SET @InqNum = 0
	END
	SET @InqNum = @InqNum + 1
	SET @InqNumP = STR(@inqNum,8,0)+@SalesP

	WHILE @ID=0
	BEGIN
		
		BEGIN TRY
		
			INSERT INTO [dbo].[AllQuotes]  (
			  InqNum,
			  InqNumP,
			  SalesP )
			  Values (
			  @InqNum,
			  @InqNumP,
			  @SalesP )
				
			SET @ID = SCOPE_IDENTITY()
		
		END TRY
		BEGIN CATCH
			--Failed because InqNumP was used, Increment and try again
			SELECT @InqNum = MAX(inqnum) FROM dbo.AllQuotes WHERE SalesP = @salesp
			SET @InqNum = @InqNum + 1
			SET @InqNumP = STR(@inqNum,8,0)+@SalesP
		END CATCH
	END
	
SELECT @ID AS AllQuotes_ID

END

