	-- Add the parameters for the stored procedure here

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;



DECLARE @filename VARCHAR(512),@sql VARCHAR(512);
--using dynamic sql in order to use the @filename variable
SET @sql ='     INSERT INTO bindata(data) SELECT * FROM OPENROWSET(BULK '''+ @filename+''', SINGLE_BLOB) as f;'
EXEC (@sql);


DECLARE @a INT
DECLARE @i INT,@cmd VARCHAR(500)
SET @filename = 'd:\tmp\'+CAST (@i AS VARCHAR)+'.dat';
SELECT @filename;
SET @cmd =     'bcp "SELECT data FROM db1.dbo.bindata WHERE file_id='+    CAST(@i+1 AS VARCHAR)+'" queryout '+@filename+' -T -N'
EXEC master..xp_cmdshell @cmd;


END
