ALTER PROCEDURE [dbo].[p_BrokerLst_Process_QTY] 
(
@ID_Detail	INT
)
AS
BEGIN

--Returns QTY and Weight for BrokerLst ID_Detal, and Summary of Process against it!
--EXEC dbo.p_Process_QTY 23185

--DECLARE @ID_Detail	INT = 9913

DECLARE @MasterLB	INT,
	@MasterQTY INT,
	@MProcQTY	INT ,
	@MProcPounds INT,
	@DetailLB	INT,
	@DetailQTY INT,
	@DProcQTY	INT,
	@DProcPounds INT


SET NOCOUNT ON

DECLARE @err INT,
        @RC INT

SET @err = 0
SET @RC = 0

SELECT @MasterLB = M.mWeight, @MasterQTY = M.mS_QTY 
	FROM dbo.BrokerLst_Master M
	INNER JOIN dbo.BrokerLst_Detail D ON M.ID = D.ID
	WHERE D.ID_Detail = @ID_Detail

SELECT @MasterQTY = SUM(D.S_QTY) FROM dbo.BrokerLst_Detail D WHERE D.ID_Detail = @ID_Detail

SELECT @MProcQTY = SUM(P.QTY) 
	,@MProcPounds = SUM(P.Pounds) 
	FROM dbo.BrokerLst_Process P
	WHERE P.ID_Detail = @ID_Detail
	AND ( P.Process_ID  = 'SELECTED' 
		OR P.Process_ID  = 'Shipped'
		OR P.Process_ID  = 'Partl Ship' )

SELECT @DetailLB = Weight, @DetailQTY = S_QTY FROM dbo.BrokerLst_Detail WHERE ID_Detail = @ID_Detail 

SELECT @DProcQTY = SUM(QTY) FROM dbo.BrokerLst_Process 
	WHERE ID_Detail = @ID_Detail 
	AND ( Process_ID  = 'SELECTED' 
		OR Process_ID  = 'Shipped'
		OR Process_ID  = 'Partl Ship' )

SELECT @DProcPounds = SUM(Pounds) FROM dbo.BrokerLst_Process 
	WHERE ID_Detail = @ID_Detail 
	AND ( Process_ID  = 'SELECTED' 
		OR Process_ID  = 'Shipped'
		OR Process_ID  = 'Partl Ship' )

--NOT 'INCOMING','PARTRECV','CORRECTION','Receiving'

SELECT @MasterLB AS MasterLBS,
	@MasterQTY AS MasterQTY,
	@DetailLB AS DetailLBS,
	@DetailQTY AS DetailQTY,
	@MProcPounds AS MProcLBS,
	@MProcQTY AS MProcQTY,
	@DProcPounds AS DProcLBS,
	@DProcQTY AS DProcQTY
	
END



GO
