ALTER PROCEDURE [dbo].[p_CalcPriceCL]
(
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@cCL CHAR(1),
@nStdSize DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nPounds DECIMAL(9,1),
@nForceBracket TinyInt,
@nPrice DECIMAL(11,2) OUTPUT,
@nBracket TinyInt OUTPUT, 
@cMessage CHAR(2000) OUTPUT,
@bActivePrice BIT OUTPUT
)
AS

/*
DECLARE @cAlloy char(12),@cForm CHAR(2),@cCC CHAR(1),@cCL CHAR(1), @nStdSize DECIMAL(9,4),@nSize2 DECIMAL(9,3),@nPounds DECIMAL(9,1),@nForceBracket INT
SELECT @cAlloy='400',@cForm='10',@cCC='1',@cCL='',@nStdSize=1,@nSize2=0,@nPounds=10,@nForceBracket=0
--SELECT @cAlloy='HPA N50',@cForm='10',@cCC='8',@cCL='2',@nStdSize=1,@nSize2=0,@nPounds=10,@nForceBracket=0
--SELECT @cAlloy='HPA N60',@cForm='10',@cCC='2',@cCL='',@nStdSize=1,@nSize2=0,@nPounds=10,@nForceBracket=0
DECLARE @nPrice DECIMAL(9,2), @nBracket TinyInt, @cMessage CHAR(2000), @bActivePrice BIT 
EXEC p_CalcPriceCL @cAlloy,@cForm,@cCC,@cCL,@nStdSize,@nSize2,@nPounds,@nForceBracket,@nPrice OUTPUT,@nBracket OUTPUT , @cMessage OUTPUT, @bActivePrice OUTPUT

PRINT 'Price  $:'+CAST(@nPrice AS CHAR)
PRINT 'Bracket :'+CAST(@nBracket AS CHAR)
PRINT 'Message :'+@cMessage
PRINT 'Active  :'+CAST(@bActivePrice AS CHAR)
*/

--sql_sp = "{CALL p_CalcPriceCL ('"+cAlloy+"','"+cForm+"','1',"+LEFT(STR(nStdSize,9,4),8)+ ","+STR(nSize2,9,3)+","+STR(nPounds,9,1)+",?@nPrice,?@nBracket,?@cMessage,?@bActivePrice )}"
--nSQLEXEC = SQLEXEC(nConnHandle, SQL_SP )

--RETURNS:
--@nPrice= Price per Quantity.
--@nBracket= Price bracket used.
--@cMessage= Empty or 'Price not found in table.'
--@bActivePrice= Active Price

BEGIN
SET NOCOUNT ON
declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @cCCorig CHAR(1)
SET @cCCorig = @cCC

--Check User login
--IF UserName, sesionID Parameter = UserName, SesionID stored in users table and Login limit date not expired

SET @cMessage = '' 
--+ rtrim(@cAlloy)

--DECLARE @lActivePrice BIT
SET @bActivePrice = 0
--Find Thickness used in PriceTable

IF @nForceBracket = 0
	SET @nPounds = @nPounds
ELSE
IF @nForceBracket = 1
	SET @nPounds = 4
ELSE
IF @nForceBracket = 2
	SET @nPounds = 9
ELSE
IF @nForceBracket = 3
	SET @nPounds = 24
ELSE
IF @nForceBracket = 4
	SET @nPounds = 49
ELSE
IF @nForceBracket = 5
	SET @nPounds = 99
ELSE
IF @nForceBracket = 6
	SET @nPounds = 199
ELSE
IF @nForceBracket = 7
	SET @nPounds = 499
ELSE
IF @nForceBracket = 8
	SET @nPounds = 999
ELSE
IF @nForceBracket = 9
	SET @nPounds = 1999
ELSE
IF @nForceBracket = 10
	SET @nPounds = 4999
ELSE
IF @nForceBracket = 11
	SET @nPounds = 5001

DECLARE @cCCAdjust CHAR(1)
SET @cCCAdjust = '0'



---------------------------------------------------

DECLARE @nAdjust SmallMoney
SET @nAdjust = dbo.f_Price_Adjust( @cCC, @cCL, @nStdSize )
--PRINT 'The Price Adjustment'
--PRINT @nAdjust

---------------------------------------------------

DECLARE @cAdjustCC char(1)
SET @cAdjustCC = dbo.f_Price_AdjustCC( @cCC, @cCL, @nStdSize )
PRINT 'Returns the CC to Search in PriceTable'
PRINT @cAdjustCC

---------------------------------------------------
/*
DECLARE @cAdjustPT char(1)
SET @cAdjustPT = dbo.f_Price_Use_Adjust( @cCC, @cCL, @nStdSize )
--Return T or F if CC,CL for PriceTable needs an adjustment

IF @cAdjustPT = 'T'
	begin
	--the CL is not set in the Price Table
	--search for Alloy Form and AdjustCC
	SET @cCC = @cAdjustCC
	SET @cCL = ''
	end

--If the AdjustPT is 'F'
	--the PricingTable is ready to be searched by Alloy, Form, CC and CL
*/

---------------------------------------------------

DECLARE @cUsePriceTable char(1)
SET @cUsePriceTable = dbo.f_Price_Table_Use( @cCC, @cCL, @nStdSize )
--PRINT 'cUsePriceTable = dbo.f_Price_Table_Use'
--PRINT 'if F is PriceTable needs an adjustment'
--PRINT @cUsePriceTable

IF @cUsePriceTable = 'F'
	begin
	--the CC CL is not set in the Price Table
	--search for Alloy Form and the AdjustedCC
	--SET @cMessage = RTRIM(@cMessage) +' Alloy '+@cAlloy+', Form '+@cForm+',  CC='+@cCC+' CL='+@cCL+', not in the Price Table'
	SET @cMessage = RTRIM(@cMessage) +' Alloy '+@cAlloy+', Form '+@cForm+',  CC='+@cCC+' CL='+@cCL+', '+LTRIM(RTRIM(CAST(@nStdSize AS CHAR(10) )))+' not in the Price Table'
	SET @cCC = @cAdjustCC
	SET @cCL = ''
	
	end

If @cUsePriceTable = 'T'
--	begin
--	PRINT 'the PricingTable is ready to be searched by Alloy, Form, CC and CL'
--	SET @cMessage = RTRIM(@cMessage) + ' PricingTable: Alloy '+@cAlloy+', Form '+@cForm+', CC '+@cCc+', and CL '+@cCL
--	PRINT '@cMessage='+@cMessage
--	end


---------------------------------------------------

SET @nPrice=0
--@nPrice
IF @nPounds < 5
  BEGIN
	SELECT TOP 1 @nPrice = w0, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 1
   END
ELSE 
IF @nPounds >= 5 AND @nPounds < 10
  BEGIN
	SELECT TOP 1 @nPrice = w5, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 2
   END
ELSE 
IF @nPounds >= 10 AND @nPounds < 25
  BEGIN
	SELECT TOP 1 @nPrice = w10, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 3
   END
ELSE 
IF @nPounds >= 25 AND @nPounds < 50
  BEGIN
	SELECT TOP 1 @nPrice = w25, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 4
   END
ELSE 
IF @nPounds >= 50 AND @nPounds < 100
  BEGIN
	SELECT TOP 1 @nPrice = w50, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 5
   END
ELSE 
IF @nPounds >= 100 AND @nPounds < 200
  BEGIN
	SELECT TOP 1 @nPrice = w100, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 6
   END
ELSE 
IF @nPounds >= 200 AND @nPounds < 500
  BEGIN
	SELECT TOP 1 @nPrice = w200, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 7
   END
ELSE 
IF @nPounds >= 500 AND @nPounds < 1000
  BEGIN
	SELECT TOP 1 @nPrice = w500, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 8
   END
ELSE 
IF @nPounds >= 1000 AND @nPounds < 2000
  BEGIN
	SELECT TOP 1 @nPrice = w1000, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 9
   END
ELSE 
IF @nPounds >= 2000 AND @nPounds < 5000
  BEGIN
	SELECT TOP 1 @nPrice = w2000, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 10
   END
ELSE
IF @nPounds >= 5000
  BEGIN
	SELECT TOP 1 @nPrice = wBase, @bActivePrice = ActivePric 
		FROM dbo.pricetable 
		WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )
	IF @nPrice = 0
		SELECT TOP 1 @nPrice = w2000, @bActivePrice = ActivePric 
			FROM dbo.pricetable 
			WHERE Alloy = @cAlloy AND Form = @cForm AND CC = @cCC AND CL = @cCL AND (Thk = @nStdSize OR Size = @nStdSize )

	SET @nBracket = 11
   END
ELSE
   BEGIN
	SET @nBracket = 0

	SET @cMessage = 'Weight Bracket Price not found in table. '+RTRIM(@cMessage)
   END

IF @cCCAdjust != '0'
	SET @nPrice = @nPrice * @nAdjust

DECLARE @nSurcharge FLOAT =0
SET @nSurcharge = dbo.f_Alloy_Surcharge(@cAlloy)

--IF @nSurcharge > 0
--	SET @nPrice = @nPrice * @nSurcharge


--select @RC = @@ROWCOUNT, @err = @@ERROR


/*PRINT 'p_CalcPriceCL Completed'
PRINT '@cForm' 
PRINT @cForm
PRINT '@nStdSize'
PRINT @nStdSize

PRINT '@nPrice '
PRINT @nPrice 
PRINT '@nBracket'
PRINT @nBracket
PRINT '@cMessage'
PRINT @cMessage
PRINT '@bActivePrice'
PRINT @bActivePrice
*/
--REPLACE Quotes.descript WITH ThisFormSet.QuotesDescription( @cForm, @@nStdSize, @nSize2)

RETURN
END




