ALTER PROCEDURE [dbo].[p_Check_Inv]
(
@cAkaAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),
@nStandardSize DECIMAL(9,4) OUTPUT,
@cMessage CHAR(2000) OUTPUT
)
AS
BEGIN
--SET NOCOUNT ON
DECLARE @err INT,
        @RC INT
	
SET @err = 0
SET @RC = 0
SET @nStandardSize = 0

DECLARE @cAlloy char(12)
SET @cAlloy = dbo.AlloyName(@cAkaAlloy)

--Check User login
--IF UserName, sesionID Parameter = UserName, SesionID stored in users table and Login limit date not expired

--Search Inventory
SELECT @RC = COUNT(*) FROM stocklst_master WHERE Alloy = @cAlloy ;
IF @RC = 0
   BEGIN
	SET @cMessage = 'Unable to find Alloy ('+RTRIM(IsNull(@cAlloy,@cAkaAlloy))+').' 
	RETURN
   END


SELECT @RC = COUNT(*) FROM stocklst_master WHERE Alloy = @cAlloy AND Form = @cForm ; 
IF @RC = 0
   BEGIN
	SET @cMessage = 'Unable to find Form ('+RTRIM(@cForm)+') for Alloy ('+RTRIM(@cAlloy)+').' 
	RETURN
   END


DECLARE @sh NUMERIC(9,3)
DECLARE @sl NUMERIC(9,3)
SET @sh = @nThickness * 1.1
SET @sl = @nThickness * .9

SELECT @RC = COUNT(*) FROM stocklst_master, stocklst_detail WHERE Alloy = @cAlloy AND Form = @cForm AND stocklst_master.id=stocklst_detail.id AND stocklst_detail.size_h >= @sl AND stocklst_detail.size_l <= @sh

SET @nStandardSize = @RC
IF @RC = 0
   BEGIN
	SET @cMessage = 'Unable to find Thickness ('+RTRIM(STR(@sl,9,3))+'" to '+RTRIM(STR(@sh,9,3))+'") for this Alloy ('+RTRIM(@cAlloy)+') and Form.' 
	RETURN
   END
ELSE
	SET @cMessage = 'Found '+LTRIM(STR(@RC))+' Inventory Items.' 	
 
--Find Thickness used in PriceTable
--SELECT thk FROM pricetbl WHERE Alloy = @cAlloy AND Form = @cForm AND Thk = @nThickness 
--select @RC = @@ROWCOUNT, @e@r = @@ERROR
--SELECT thk FROM pricetbl WHERE Alloy = @cAlloy AND Form = @cForm AND Thk > @nThickness-.010 AND Thk < @nThickness +.010

--REPLACE Quotes.descript WITH ThisFormSet.QuotesDescription( @cForm, @nThickness, @nSize2, @nSize3 )

RETURN
END
GO
