	BEGIN
		SET @nReturnCode = -1
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		RETURN @nReturnCode
	END

--SET @nReturnCode = -3

BEGIN TRANSACTION Move_BrokerLst_StockLst
----------------------------------
PRINT 'ADD Master'
INSERT INTO dbo.StockLst_Master 
	([Alloy],[Form],[cc],[CL],[Size],[Cond],[MWeight],[specs],[Heat],[Lot],[PAID],[PO_Item]
	,[PODueDate],[Mill],[StkDate],[History],[Num],[POStatus],[BrandName],[MillTrace],[From_ID]
	,Melt,mS_QTY,WO_Detail)
SELECT [Alloy],[Form],[cc],[CL],[Size],[Cond],[MWeight],[specs],[Heat],[Lot],[PAID],[PO_Item]
	,[PODueDate],[Mill],GetDate(),[History],[Num],[POStatus],[BrandName],[MillTrace],[From_ID]
	,Melt,mS_QTY,WO_Detail 
   FROM dbo.Ar.BrokerLst_Master_History   WITH (NOLOCK)
   WHERE [ID] = @ID AND [What] = 'DELETE'
 

SET @nNewID = SCOPE_IDENTITY()
PRINT @nNewID
SET @nReturnCode = @nNewID

IF @nNewID < 1
	BEGIN
		SET @nReturnCode = -4
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))+'. Failed to INSERT INTO dbo.StockLst_Master'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END


DECLARE @Comment VARCHAR(100)
SET @Comment = 'Moved from BrokerLst History ID:'+CAST(@ID AS CHAR(10))+' to StockLst as '+CAST(@nNewID AS CHAR(10))

/*
----------------------------------
