INSERT INTO dbo.StockLst_Process
    ([StartDate], [comment], [Process_ID], [Processor], [AllowSub], [pWeight], [pPc], [ID_Detail]) VALUES
    (GETDATE(), @Comment, 'RECEIVED', 'RMA Rcv', 'N', 0, 0, @nNewID_Detail)

SET @nNewID_Detail_Process = SCOPE_IDENTITY()
PRINT @nNewID_Detail_Process

IF @nNewID_Detail_Process < 1
	BEGIN
		SET @nReturnCode = -6
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to INSERT INTO dbo.StockLst_Process'
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END

----------------------------------
PRINT 'Add Process Detail'
INSERT INTO dbo.StockLst_Process_detail 
    ( [What], [ID], [ID_Detail], [ID_Detail_Process] ) VALUES 
    ( 'ADD', @nNewID, @nNewID_Detail, @nNewID_Detail_Process )

SELECT @RC = @@ROWCOUNT, @err = @@ERROR

IF @err <> 0
	BEGIN
		SET @nReturnCode = -7
		PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
		PRINT 'Failed to (Add Process Detail) INSERT INTO dbo.StockLst_Process_detail '
		ROLLBACK TRANSACTION Move_BrokerLst_StockLst
		RETURN @nReturnCode
	END



----------------------------------
--Email Error			

DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()

IF LEN(@Body) > 1
begin

	SET @Body = @Body+CHAR(13)
		+'User '+RTRIM(suser_sname())+' on '+RTRIM(CAST(GETDATE()AS CHAR))+' '+CHAR(13)
		+@@SERVERNAME+' TRIGGER '+' p_Move_BrokerLst_StockLst '+CHAR(13)
		+' [ID] = '+CAST(@ID AS CHAR(10))
		

	EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'Admin.Alerts@ERP_1s.com', 
	@SubjectEmail = 'p_Create_StockLstRMA_From_Broker_History.',
		@BodyEmail = @Body,
		@BodyType = 'TEXT'
					
	RAISERROR( @Body, 16, -1)

end
----------------------------------
*/

IF @nReturnCode < 0
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
	 --SELECT @nReturnCode
     --PRINT 'ROLLBACK TRANSACTION Move_BrokerLst_StockLst'
     --ROLLBACK TRANSACTION Move_BrokerLst_StockLst
    end
ELSE
	begin
	 PRINT 'nReturnCode = '+CAST(@nReturnCode AS CHAR(10))
     SET @nReturnCode = @nNewID
     SELECT @nReturnCode
     PRINT 'COMMIT TRANSACTION Move_BrokerLst_StockLst'
     COMMIT TRANSACTION Move_BrokerLst_StockLst
	end
	
RETURN @nReturnCode



  
GO
