-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 07/21/2021
-- Description:	Creates Survey Assignments
-- =============================================
ALTER PROCEDURE [dbo].[p_Create_Survey_Assignment] 
	-- Add the parameters for the stored procedure here
	@surveyID uniqueidentifier,
	@assignmentType smallint = 0, -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
	@identifier varchar(50) -- Could be EmployeeID, SOitem, POitem, Quote, etc. This should match the type provided above
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Declare the return variable here
	DECLARE @assignmentID uniqueidentifier

	-- Add the T-SQL statements to compute the return value here
	DECLARE @_surveyID uniqueidentifier,
		@_contactInfoID uniqueidentifier,
		@dateNow datetime = GETDATE(),
		@phoneNumber varchar(15), -- Required for Creating Contact Info
		@email varchar(254), -- Required for Creating Contact Info
		@companyName varchar(100), -- Required for Creating Contact Info
		@contactName varchar(100) -- Optional for Creating Contact Info


	-- Verify that the Survey Exists
	SELECT TOP(1) @_surveyID = ID
	FROM [dbo].[Survey]
	WHERE ID = @surveyID

	IF (@_surveyID is not NULL) -- Survey exists, continue
	BEGIN
		--GET CONTACT DATA TO CREATE SURVEY CONTACT INFO 
		IF (@assignmentType = 1) -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
		BEGIN
			SELECT TOP(1) 
				@phoneNumber = '(765)945-8230',
				@email = [FirstName] + '.' + [LastName] + '@ERP_1s.com',
				@companyName = 'High Performance Alloys',
				@contactName = [FirstName] + ' ' + [LastName]
			FROM [dbo].[TC_Replacement_Employees]
			WHERE [EmployeeId] = LTRIM(RTRIM(@identifier))
		END

		IF (@assignmentType = 2) -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
		BEGIN
			SELECT TOP(1) 
				@phoneNumber = [Phone],
				@email = [Email],
				@companyName = [Company],
				@contactName = [Name]
			FROM [dbo].[AllQuotes]
			WHERE LTRIM(RTRIM([InqNumP])) = LTRIM(RTRIM(@identifier))
		END

		IF (@assignmentType = 3) -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
		BEGIN
			SELECT TOP(1) 
				@phoneNumber = [Phone],
				@email = [Email],
				@companyName = [Company],
				@contactName = [Name]
			FROM [dbo].[AllQuotes]
			WHERE [SalesNum] = LTRIM(RTRIM(@identifier))
		END

		IF (@phoneNumber is not NULL AND @email is not NULL AND @companyName is not NULL) -- Make sure data was found
		BEGIN 

			-- Create Survey Contact Info
			DECLARE @contactInfoIDTabler table([ID] [uniqueidentifier]);
			INSERT INTO [dbo].[Survey_Assignment_ContactInfos]
			(
				[DateCreated]
				,[PhoneNumber]
				,[Email]
				,[CompanyName]
				,[ContactName]
				,[SalesOrder]
				,[Quote]
			)
			OUTPUT INSERTED.[ID] INTO @contactInfoIDTabler
			VALUES
			(
				@dateNow,
				@phoneNumber,
				@email,
				@companyName,
				@contactName,
				CASE @assignmentType -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
					WHEN 3 THEN @identifier
					ELSE NULL
				END,
				CASE @assignmentType -- 1: Employee, 2: Quote, 3: Sales Order, 4: Purchase Order, 5: General Customer Survey
					WHEN 2 THEN @identifier
					ELSE NULL
				END
			)

			-- GET Contact Info ID
			SELECT TOP(1) @_contactInfoID = ID
			FROM @contactInfoIDTabler
			

			-- Create Survey Assignment
			DECLARE @surveyAssignmentIDTabler table([ID] [uniqueidentifier]);
			INSERT INTO [dbo].[Survey_Assignments]
			(
				[SurveyID]
				,[DateAssigned]
				,[AssignmentType]
				,[TargetIdentifier]
				,[Survey_Assignment_ContactInfoID]
			)
			OUTPUT INSERTED.[ID] INTO @surveyAssignmentIDTabler
			VALUES
			(
				@_surveyID,
				@dateNow,
				@assignmentType,
				LTRIM(RTRIM(@identifier)),
				@_contactInfoID
			)

			-- GET Assignment ID
			SELECT TOP(1) @assignmentID = ID
			FROM @surveyAssignmentIDTabler

		END
	END

	-- Return the result of the Procedure
	SELECT @assignmentID
END
GO
