ALTER PROCEDURE [dbo].[p_Duplicate_Stock]
AS

--EXEC [dbo].[p_Duplicate_Stock]

  Set NoCount On


----------------------------
-- show the Duplictes
PRINT 'show the Duplictes'
----------------------------

SELECT Distinct t.ID, heat
FROM dbo.[N50_CC2_regraded] As t
Inner Join
(
  SELECT id
  FROM dbo.[N50_CC2_regraded]
--  WHERE NOT ( SOitem = '      0-00' OR  SOitem = '      0-01')
  --!= dbo.f_ProperSOitem(SOitem)
  Group By ID
  Having Count(*) > 1
) dt
  On (dt.ID = t.ID)
-- And  dt.MiddleName = t.MiddleName )



----------------------------
-- Delete the previous Duplicates 
-- where SOitem same and not in temp table 
-- only MAX(ID) in temp table
----------------------------

Print 'Count number of records to start with'
SELECT COUNT(*) AS Records FROM dbo.[N50_CC2_regraded]

--SELECT Max(Id) Id, SOitem,ISNULL(QShipped,0) AS Qshipped FROM dbo.Ship WHERE NOT ( SOitem = '      0-00' OR  SOitem = '      0-01') GROUP BY SOitem,ISNULL(QShipped,0) HAVING COUNT(*) > 1
--SELECT Max(Id) Id FROM dbo.['N60 CC2 regraded StockLst'] GROUP BY ID

SELECT Max(dWeight) dWeight, heat
into #t1 
FROM dbo.[N50_CC2_regraded]
GROUP BY dWeight, heat

PRINT 'Delete the previous Duplicates'

DELETE D FROM dbo.[N50_CC2_regraded] D 
join #t1 t ON D.heat = t.heat  

AND D.dWeight <> t.dWeight

--AND t.ID <> D.ID   
--WHERE NOT ( D.SOitem = '      0-00' OR  D.SOitem = '      0-01')
--SELECT * FROM dbo.Ship D join #t1 t ON D.SOitem = t.SOitem and t.ID <> D.ID   WHERE NOT ( D.SOitem = '      0-00' OR  D.SOitem = '      0-01')

-- clean up
Drop table #t1

SELECT * FROM dbo.[N50_CC2_regraded] order by [ID] desc -- no dupes !!

Print 'Count number of records to now'
SELECT COUNT(*) AS Records FROM dbo.[N50_CC2_regraded]

--SELECT * FROM dbo.Ship WHERE ShipDate = '1899-12-30 00:00:00.000'
--UPDATE dbo.Ship SET ShipDate = null WHERE ShipDate = '1899-12-30 00:00:00.000'
--UPDATE dbo.Ship SET ShipDate = null WHERE ShipDate = '1900-01-01 00:00:00.000'

