ALTER PROCEDURE [dbo].[p_Duplicates]
AS

--EXEC [dbo].[p_Duplicates]

  Set NoCount On


----------------------------
-- show the Duplictes
PRINT 'show the Duplictes'
----------------------------

SELECT Distinct t.ID,t.SOitem,ISNULL(t.QShipped,0) AS qShipped
FROM dbo.Ship As t
Inner Join
(
  SELECT SOitem
  FROM dbo.Ship
  WHERE NOT ( SOitem = '      0-00' OR  SOitem = '      0-01')
  --!= dbo.f_ProperSOitem(SOitem)
  Group By SOitem
  Having Count(*) > 1
) dt
  On (dt.SOitem = t.SOitem)
-- And  dt.MiddleName = t.MiddleName )



----------------------------
-- Delete the previous Duplicates 
-- where SOitem same and not in temp table 
-- only MAX(ID) in temp table
----------------------------

