/****** Object:  StoredProcedure [dbo].[p_eMail_Send_Attachments]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_eMail_Send_Attachments]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_eMail_Send_Attachments] AS' 
END
GO

ALTER PROCEDURE [dbo].[p_eMail_Send_Attachments]
    @FromEmail VARCHAR(8000),
    @ToEmail VARCHAR(8000),
    @BCC VARCHAR(8000),
    @SubjectEmail VARCHAR(8000),
    @BodyEmail VARCHAR(MAX),
    @Body_Format CHAR(4),
    @File_Attach VARCHAR(8000)
AS

IF SUSER_NAME() = 'SuperMicro\talkt'
	begin
	PRINT 'SUSER_NAME() = "SuperMicro\talkt"'
	PRINT 'Decline to run'
	RETURN
	end

--DECLARE @FromEmail VARCHAR(8000),    @ToEmail VARCHAR(8000),    @SubjectEmail VARCHAR(8000),    @BodyEmail VARCHAR(8000),   @Body_Format CHAR(4), @file VARCHAR(8000),    @NewName VARCHAR(8000)
--SET @FromEmail = 'David.Kirchner@ERP_1s.com'
--SET @ToEmail = 'DavidKirchner@yahoo.com'
--SET @BCC = N'4012785@bcc.hubspot.com'
--SET @SubjectEmail = 'Quote From HPA'
--SET @BodyEmail = 'Test PDF'
--SET @Body_Format = 'TEXT' --'HTML'
--SET @File_Attach = '19626D.PDF;21626D.PDF'
--EXEC [dbo].[p_eMail_Send_Attachments] @FromEmail, @ToEmail, @SubjectEmail, @BodyEmail, @Body_Format, @File_Attach
--or
--EXEC [dbo].[p_eMail_Send_Attachments] @FromEmail  = 'David.Kirchner@ERP_1s.com', @ToEmail = 'DavidKirchner@yahoo.com',@BCC = N'addy@addresstwo.com', @SubjectEmail = 'Quote From HPA', @BodyEmail  = 'Test PDF', @Body_Format='HTML', @File_Attach = '19626D.PDF;21686D.PDF'


DECLARE @result INT
DECLARE @object INT
DECLARE @cmd VARCHAR(8000)
DECLARE @tofrom VARCHAR(8000)

IF @ToEmail = @FromEmail
	SET @tofrom = @ToEmail
ELSE
	SET @tofrom = @ToEmail+';'+@FromEmail 

--@Body_Format 'TEXT' 'HTML'

DECLARE @name VARCHAR(8000)
SET @name = LEFT( @FromEmail , CHARINDEX( '@', @FromEmail)-1 )
--SET @name = UPPER( LEFT( @name, 1) ) + LOWER( RIGHT( @name, LEN(@name)-1  ) )
SET @name = @name+' at HPA'+' <'+@FromEmail+'>'

IF LEN(@BCC) < 1
	SET @BCC = dbo.f_Get_BCC()
ELSE
	SET @BCC = @BCC+' ; '+dbo.f_Get_BCC()

--SET @FromEmail = @FromEmail+';'+@BCC

--**************************

DECLARE @FileName VARCHAR(8000)
--DECLARE @File VarChar(8000)

--SET @FILE = RTRIM(@FILE)
--SET @FileName = '\\'+@@ServerName+'\Email\'+@File

DECLARE @i INT
SET @i = 1


--Declare @curIndex int = 0
Declare @pos int = 1
Declare @FileLength INT = 0
Declare @prevPos int = 0
Declare @curIndex Int = 0
Declare @HaveFile2Attach int = 1
Declare @AttachFileName varchar(8000)
Declare @AttachedFiles varchar(8000)
Declare @testFileName varchar(8000)

set @AttachFileName = ''
set @AttachedFiles = ''

set @FileLength =  CHARINDEX(';', @File_Attach);

--WHILE @HaveFile2Attach > 0
while @FileLength > 0
Begin
	PRINT 'drop the last ;'
    set @pos =  CHARINDEX(';', @File_Attach, @prevPos+1);
	PRINT 'Pos PrevPos Index'
	PRINT @pos
	PRINT @prevPos
	PRINT @curIndex
    if(@pos > 0)
        begin-- get the chars between the prev position to next delimiter pos
			set @testFileName = SUBSTRING(@File_Attach, @prevPos, @pos-@prevPos)
			IF CHARINDEX(';', @testFileName) = 1
				set @testFileName = SUBSTRING(@File_Attach, @prevPos+1, @pos-@prevPos)
			PRINT 'testFileName 0 a ' + @testFileName

			IF CHARINDEX(';', @testFileName) >  1
				set @testFileName = SUBSTRING(@testFileName,1, LEN(@testFileName)-1)
			PRINT 'testFileName 0 b ' + @testFileName

            set @AttachFileName = @AttachFileName + '\\'+@@ServerName+'\Email\'+@testFileName+';'
			
            SET @FileName = '\\'+@@ServerName+'\Email\'+@testFileName
			set @AttachedFiles = @AttachedFiles + @FileName

        end
        else
			begin--get last delimited message
				set @testFileName = SUBSTRING(@File_Attach, @prevPos, LEN(@File_Attach))
				IF CHARINDEX(';', @testFileName) = 1
					set @testFileName = SUBSTRING(@File_Attach, @prevPos+1, @pos-@prevPos)
					PRINT 'testFileName 1 a ' + @testFileName

		        set @AttachFileName = @AttachFileName + '\\'+@@ServerName+'\Email\'+@testFileName

				IF CHARINDEX(';', @testFileName) >  1
					set @testFileName = SUBSTRING(@testFileName,1, LEN(@testFileName)-1)
				PRINT 'testFileName 1 b ' + @testFileName

		        
				SET @FileName = '\\'+@@ServerName+'\Email\'+ @testFileName
				set @AttachedFiles = @AttachedFiles + @FileName

			end

	


	PRINT 'FileName: '+@FileName

	EXEC master..xp_fileexist @FileName, @i OUTPUT
	
	IF @i <> 1
		BEGIN
			PRINT 'File does not exists to attach:'+@FileName
			SELECT 2 AS EXP
			RETURN
		END
	ELSE
		PRINT 'File exists to attach:'+@FileName

	

	
   set @prevPos = @pos 
   set @curIndex = @curIndex + 1;
   set @FileLength =  CHARINDEX(';', @File_Attach, @pos+1);

   PRINT 'Next File Length:'
   PRINT '@FileLength='+CAST(@FileLength AS VARCHAR(8000))

end


--*********************************

IF @FileLength = 0
	--Only one file was Sent.
	begin

	set @FileLength = LEN(@File_Attach);
	PRINT '@FileLength = '+CAST(@FileLength AS VARCHAR(8000))

	--set @testFileName = SUBSTRING(@File_Attach, @FileLength, LEN(@File_Attach))
	--SET @FileName = '\\'+@@ServerName+'\Email\'+ @testFileName
	SET @FileName = '\\'+@@ServerName+'\Email\'+ @File_Attach
	set @AttachedFiles = @AttachedFiles + @FileName
	Set @AttachFileName = @AttachedFiles

	PRINT '@File_Attach='+ @File_Attach
	end

--*********************************


--set @AttachFileName = LEFT(@AttachFileName, LEN(@AttachFileName)-1)
--set @AttachedFiles = LEFT(@AttachedFiles, LEN(@AttachedFiles)-1)
PRINT 'AtachedFiles =' +@AttachedFiles
PRINT 'AttachFileName =' +@AttachFileName
	
DECLARE @cProfile_Name VarChar(50)
SET @cProfile_Name = dbo.f_Get_profile_name(@FromEmail)
--SET @cProfile_Name = 'HPA-NotSpam' 
--dbo.f_Get_profile_name defaults to when not found!
WAITFOR DELAY '00:00:01'

	EXEC @result = msdb.dbo.sp_send_dbmail 
		 @profile_name = @cProfile_Name
		, @recipients = @ToEmail
		, @blind_copy_recipients = @BCC
		, @copy_recipients = @FromEmail
		, @subject = @SubjectEmail 
		, @body = @BodyEmail
		, @body_format = @Body_Format
		, @file_attachments = @AttachFileName

	IF @result = 0
	BEGIN
		PRINT 'Sent Email with sp_send_dbmail'
		SELECT 1 AS EXP
	END
	ELSE
    BEGIN
		PRINT 'sp_send_dbmail Failed'
		PRINT @result
		SELECT 3 AS EXP
		RETURN 
    END

--Place files in \\Peregrine\Email\
--List files in @File_Attach delimited with ;
--call [p_eMail_Send_Atachments]
--remove files from server after send.
GO
