	@BodyType CHAR(4)
AS

--DECLARE @FromEmail VARCHAR(8000), @ToEmail VARCHAR(8000), @BCC VARCHAR(8000), @SubjectEmail VARCHAR(8000), @BodyEmail VARCHAR(8000), @File VARCHAR(8000), @NewName VARCHAR(8000)
--SET @FromEmail = 'David@ERP_1s.com'
--SET @ToEmail = 'David@ERP_1s.com'
--SET @BCC=N'4012785@bcc.hubspot.com'
--SET @SubjectEmail = 'SQL Test'
