-- --EXEC P_eMail_Send_BCC @FromEmail, @ToEmail, @SubjectEmail, @BodyEmail, 'HTML'
-- EXEC P_eMail_Send_BCC 'David@ERP_1s.com','DavidKirchner@yahoo.com','TalktoDK@hotmail.com','Subject','Body Mess','TEXT'

--EXEC dbo.p_eMail_Send_BCC  @FromEmail=N'David.Kirchner@ERP_1s.com',@ToEmail=N'DavidKirchner@yahoo.com',@BCC=N'TalktoDK@hotmail.com',@SubjectEmail=N'Quote from ERP_1 #10457V',@BodyEmail='Body',@BodyType='TEXT'

IF SUSER_NAME() = 'SuperMicro\talkt'
	begin
	PRINT 'SUSER_NAME() = "SuperMicro\talkt"'
	PRINT 'Decline to run [p_eMail_Send_BCC]'
	RETURN
	end



DECLARE @result INT
DECLARE @object INT


IF LEN(@FromEmail) < 1
	SET @FromEmail = 'admin.Alerts@ERP_1s.com'
IF LEN(@BCC) < 1
	SET @BCC = dbo.f_Get_BCC()
ELSE
	SET @BCC = @BCC+' ; '+dbo.f_Get_BCC()

DECLARE @cProfile_Name VarChar(50)
SET @cProfile_Name = dbo.f_Get_profile_name(@FromEmail)
IF @cProfile_Name = @@SERVERNAME
	INSERT INTO dbo.Errors ( [nError],[mess1],[cprogram],[nlineno],[Memo1] ) 
		VALUES (0,'No Profile match','dbo.p_eMail_Send_BCC',20,'dbo.f_Get_profile_name( @FromEmail='+@FromEmail+')' )

PRINT 'cProfile_Name =<' + @cProfile_Name + '>'


WAITFOR DELAY '00:00:01'


	EXEC @result =  msdb.dbo.sp_send_dbmail 
		 @profile_name = @cProfile_Name,
		 @recipients = @ToEmail,
		 @blind_copy_recipients = @BCC,
		 @copy_recipients = @FromEmail,
		 @subject = @SubjectEmail, 
		 @body = @BodyEmail,
		 @body_format = @BodyType 
--		, @file_attachments = @NewFileName
		

		IF @result IS NULL
			SET @result = -1

		IF @result <> 0
		     BEGIN
				PRINT 'msdb.dbo.sp_send_dbmail Failed'
				PRINT @result
				RETURN 6
		     END
		ELSE
		     BEGIN
				PRINT 'Sent Email'
		     END
	
RETURN @result























GO
