ALTER PROCEDURE [dbo].[p_eMail_Send_File]
    @FromEmail VARCHAR(8000),
    @ToEmail VARCHAR(8000),
    @SubjectEmail VARCHAR(8000),
    @BodyEmail VARCHAR(MAX),
    @Body_Format CHAR(4),
    @File VARCHAR(8000)
AS

--DECLARE @FromEmail VARCHAR(8000),    @ToEmail VARCHAR(8000),    @SubjectEmail VARCHAR(8000),    @BodyEmail VARCHAR(8000),   @Body_Format CHAR(4), @file VARCHAR(8000),    @NewName VARCHAR(8000)
--SET @FromEmail = 'David.Kirchner@ERP_1s.com'
--SET @ToEmail = 'DavidKirchner@yahoo.com'
--SET @SubjectEmail = 'Quote From HPA'
--SET @BodyEmail = 'Test PDF'
--SET @Body_Format = 'TEXT' --'HTML'
--SET @file = '19626D.PDF'
--EXEC [dbo].[p_eMail_Send_File] @FromEmail, @ToEmail, @SubjectEmail, @BodyEmail, @Body_Format, @file 
--or
--EXEC [dbo].[p_eMail_Send_File] @FromEmail  = 'David.Kirchner@ERP_1s.com', @ToEmail = 'DavidKirchner@yahoo.com', @SubjectEmail = 'Quote From HPA', @BodyEmail  = 'Test PDF', @Body_Format='HTML', @file = '19626D.PDF'

--EXEC dbo.p_eMail_Send_File_BCC  @FromEmail='David.Kirchner@ERP_1s.COM',@ToEmail='David.Kirchner@ERP_1s.com'" 


IF SUSER_NAME() = 'SuperMicro\talkt'
	begin
	PRINT 'SUSER_NAME() = "SuperMicro\talkt"'
	PRINT 'Decline to run [p_eMail_Send_File]'
	RETURN
	end


DECLARE @result INT
DECLARE @object INT
DECLARE @cmd VARCHAR(8000)
DECLARE @tofrom VARCHAR(8000)

IF @ToEmail = @FromEmail
	SET @tofrom = @ToEmail
ELSE
	SET @tofrom = @ToEmail+';'+@FromEmail 

--@Body_Format 'TEXT' 'HTML'

DECLARE @BCC VarChar(100)
SET @BCC = dbo.f_Get_BCC()

DECLARE @name VARCHAR(8000)
SET @name = LEFT( @FromEmail , CHARINDEX( '@', @FromEmail)-1 )
--SET @name = UPPER( LEFT( @name, 1) ) + LOWER( RIGHT( @name, LEN(@name)-1  ) )
SET @name = @name+' at HPA'+' <'+@FromEmail+'>'

DECLARE @FileName VARCHAR(8000)
SET @FILE = RTRIM(@FILE)
SET @FileName = '\\'+@@ServerName+'\Email\'+@File
--PRINT '\\'+@@ServerName+'\Email\'
--PRINT '\\'+@@ServerName+'\Email\TestPage.pdf'

DECLARE @cProfile_Name VarChar(50)
SET @cProfile_Name = dbo.f_Get_profile_name(@FromEmail)


--SET @cProfile_Name = 'HPA-NotSpam' 
--dbo.f_Get_profile_name defaults to when not found!
WAITFOR DELAY '00:00:01'

DECLARE @i INT
SET @i = 1
EXEC master..xp_fileexist @FileName, @i OUTPUT
--EXEC master..xp_fileexist '\\PEREGRINE\Email\TestPage.pdf'


IF @i = 1
	BEGIN
--		Print 'Found PDF'
		WAITFOR DELAY '00:00:01'

	EXEC @result = msdb.dbo.sp_send_dbmail 
		 @profile_name = @cProfile_Name
		, @recipients = @ToEmail
		, @blind_copy_recipients = @BCC 
		, @copy_recipients = @FromEmail
		, @subject = @SubjectEmail 
		, @body = @BodyEmail
		, @body_format = @Body_Format
		, @file_attachments = @FileName

		IF @result <> 0
		     BEGIN
--				PRINT 'sp_send_dbmail Failed'
				PRINT @result
				SELECT 3 AS EXP
				RETURN 
		     END
		ELSE
		     BEGIN
--				PRINT 'Sent Email'
				WAITFOR DELAY '00:00:01'
				SELECT @cmd = 'DEL ' +@FileName +''
				EXEC master..xp_cmdshell @cmd--, NO_OUTPUT
--				PRINT 'Delete local PDF File :'+@cmd

				EXEC master..xp_fileexist @FileName, @i OUTPUT
				SELECT 1 AS EXP
		     END

    END
ELSE
	BEGIN
		PRINT 'File does not exists to attach :'+@FileName
		SELECT 2 AS EXP
	END
GO
