/****** Object:  StoredProcedure [dbo].[p_EmployeeTimePunch]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_EmployeeTimePunch]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_EmployeeTimePunch] AS' 
END
GO
-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 05/24/2019
-- Description:	Process For storing time punches in the database
-- UPDATES:
-- [11/04/2019] - Changed from -12 hours to -10 hours
-- [04/08/2020] - Changed return from row ID to row data. Fixed bugs where 'SET @insertedId = @@Identity' was not set after inserting
-- [04/08/2020] - Fixed bugs where 'SET @insertedId = @punchId' was not set after updating data row
-- =============================================
ALTER PROCEDURE [dbo].[p_EmployeeTimePunch] 
	-- Add the parameters for the stored procedure here
	@employeeBadge int, 
	@punchTime datetime,
	@punchActivityType smallint,	-- Work = 1, Lunch = 2, Break = 3, Transfer = 4 -- We only really care about work and lunch 
	@punchStatusType smallint		-- Auto = 1, In = 2, Out = 3	-- For Auto, we need to consider if the user forgot to clock-out. 
																	-- We may have to assume that if the time between punches is greater than 12 hours, then the punch is assumed to be a clock-in rather than
																	-- Looking at what the previous clock status is, then fill in the missing clock punch at a point that provides the person with an auto lunch + 8 work hrs 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	declare @existingEmployee bigint,
			@punchId int,
			@timeIn datetime,
			@inActivityId smallint,
			@inBillable bit,
			@timeOut datetime,
			@outActivityId smallint,
			@outBillable bit,
			@insertedId int

	SELECT @existingEmployee = [EmployeeId]
	FROM [dbo].[v_TimeClockPlus_EmployeeList]
	where [EmployeeId] = @employeeBadge

	--PRINT 'Existing Employee: ' + ISNULL(CAST(@existingEmployee AS varchar), 'NULL')

	IF (@existingEmployee is null)
	BEGIN
		--PRINT 'Employee not found. Inserting new employee: ' + @employeeBadge

		INSERT INTO TC_Replacement_Employees (EmployeeId, FirstName, LastName, Position, Pin, DateLeft, IsSuspended)
		VALUEs (@employeeBadge, 'New FirstName', 'New LastName', 'Unknown', @employeeBadge, null, null)
	END

	-- GET LAST PUNCH
	SELECT top(1) @punchId = et.[Id],
	@timeIn = [TimeIn],
	@inActivityId = [InActivityType],
	@inBillable = ad1.[Billable],
	@timeOut = [TimeOut],
	@outActivityId = [OutActivityType],
	@outBillable = ad2.[Billable]
	FROM [dbo].[TC_Replacement_Employees_Times] et
	LEFT JOIN [dbo].[TC_Replacement_Employees_Times_ActivityDefinition] ad1 on et.[InActivityType] = ad1.[ActivityId]
	LEFT JOIN [dbo].[TC_Replacement_Employees_Times_ActivityDefinition] ad2 on et.[OutActivityType] = ad2.[ActivityId]
	WHERE et.[EmployeeId] = @employeeBadge
	order by et.[Id] desc

	--PRINT 'Last Punch - PunchId: [' + ISNULL(CAST(@punchId AS varchar), 'NULL') + '], TimeIn: [' + ISNULL(CAST(@timeIn AS varchar), 'NULL') + '], TimeOut: [' + ISNULL(CAST(@timeOut AS varchar), 'NULL') + ']' 

	IF (@punchStatusType = 1) --AUTO
	BEGIN
		--PRINT '@punchStatusType: 1 (AUTO)'
		IF (@punchId is not NULL) -- EXCEPT FOR FIRST PUNCH, THIS SHOULD NEVER BE NULL
		BEGIN
			--PRINT '@punchId: NOT NULL'
			IF (@timeOut is not NULL) -- IN
			BEGIN
				--PRINT '@timeOut: NOT NULL - Inserting new "IN" punch entry.'
				INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
				VALUES (@employeeBadge, @punchTime, @punchActivityType, 1, 0, null, null, null, null)

				-- GET INESRTED ID
				SET @insertedId = @@Identity;
			END

			ELSE IF (@timeIn is not NULL) -- THIS SHOULD NOT BE NULL -- OUT
			BEGIN
				--PRINT '@timeIn: NOT NULL - Validating "OUT" punch entry.'
				
				-- CHECK IF THE LAST PUNCH WAS RECENT <12 HRS, IF NOT RECENT, THIS IS LIKELY 'IN'
				--PRINT '@punchTime (-12Hours) [' + CAST(DATEADD(HOUR, -12, @punchTime) AS varchar) + '] > last punch IN [' + CAST(@timeIn AS varchar) + ']: ' + CASE WHEN DATEADD(HOUR, -12, @punchTime) > @timeIn THEN 'TRUE' ELSE 'FALSE' END
				IF (DATEADD(HOUR, -10, @punchTime) > @timeIn) -- NOT RECENT SO FIX MISSING PUNCH -- IN
				BEGIN
					--PRINT '@punchTime NOT RECENT SO FIX MISSING PUNCH - Inserting new "IN" punch entry.'
					INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
					VALUES (@employeeBadge, @punchTime, @punchActivityType, 1, 0, null, null, null, null)

					-- GET INESRTED ID
					SET @insertedId = @@Identity;

					--PRINT 'exec [dbo].[p_AutoFixMissingTimePunch] ' + CAST(@punchId AS varchar)
					exec [dbo].[p_AutoFixMissingTimePunch] @punchId
				END
				ELSE
				BEGIN
					--PRINT 'Updating punch entry - TimeOut: [' + CAST(@punchTime AS varchar) + '], OutActivityType: [' + CAST(@punchActivityType AS varchar) + ']'
					UPDATE [dbo].[TC_Replacement_Employees_Times]
					SET [TimeOut] = @punchTime, OutActivityType = @punchActivityType, [OutAutoStatus] = 1, [TimeOutMissed] = 0
					where [Id] = @punchId

					-- GET INESRTED ID
					SET @insertedId = @punchId;
				END
			END

		END

		ELSE -- FIRST PUNCH - 'IN'
		BEGIN 
			--PRINT 'Insearting FIRST PUNCH - "IN"'
			INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
			VALUES (@employeeBadge, @punchTime, @punchActivityType, 1, 0, null, null, null, null)

			-- GET INESRTED ID
			SET @insertedId = @@Identity;
		END
	END

	ELSE IF (@punchStatusType = 2) --IN
	BEGIN
		--PRINT '@punchStatusType: 2 (IN)'
		--PRINT 'Inserting new "IN" punch entry.'
		INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
		VALUES (@employeeBadge, @punchTime, @punchActivityType, 0, 0, null, null, null, null)

		-- GET INESRTED ID
		SET @insertedId = @@Identity;

		IF (@timeOut is null) -- NEED TO HANDLE A MISSED TIME PUNCH
		BEGIN 
			-- IF NULL, IT WAS THE FIRST TIME THE EMPLOYEE WAS TRACKED, IGNORE
			IF (@timeIn is NOT null)
			BEGIN 
				--PRINT '@timeOut: IS NULL -- NEED TO HANDLE A MISSED TIME PUNCH. exec [dbo].[p_AutoFixMissingTimePunch] ' + CAST(@punchId AS varchar)
				-- call SP to fix missing time punch
				exec [dbo].[p_AutoFixMissingTimePunch] @punchId
			END
		END 
	END
	
	ELSE IF (@punchStatusType = 3) --OUT
	BEGIN
		--PRINT '@punchStatusType: 3 (OUT)'
		IF (@punchId is not null)
		BEGIN
			--PRINT '@punchId: is NOT NULL. Verify that @timeOut is NULL.'
			IF (@timeOut is null) -- UPDATE EXISTING RECORD
			BEGIN
				--PRINT '@timeOut: IS NULL. Updating punch entry - TimeOut: [' + CAST(@punchTime AS varchar) + '], OutActivityType: [' + CAST(@punchActivityType AS varchar) + ']'
				UPDATE [dbo].[TC_Replacement_Employees_Times]
				SET [TimeOut] = @punchTime, OutActivityType = @punchActivityType, [OutAutoStatus] = 0, [TimeOutMissed] = 0
				where [Id] = @punchId

				-- GET INESRTED ID
				SET @insertedId = @punchId;
			END
			
			ELSE -- MISSED PUNCH
			BEGIN
				--PRINT '@timeOut: is NOT NULL -- NEED TO HANDLE A MISSED TIME PUNCH. - Inserting new punch entry.'
				INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
				VALUES (@employeeBadge, null, null, null, null, @punchTime, @punchActivityType, 0, 0)

				-- GET INESRTED ID
				SET @insertedId = @@Identity;
				--PRINT '@insertedId: ' + CAST(@insertedId AS varchar)

				--PRINT 'exec [dbo].[p_AutoFixMissingTimePunch] ' + CAST(@insertedId AS varchar)
				exec [dbo].[p_AutoFixMissingTimePunch] @insertedId
			END
		END

		ELSE -- IF @punchId is null, it was the first time the employee punched
		BEGIN
			--PRINT '@punchId: IS NULL. - FIRST PUNCH - "OUT" - Inserting new punch entry.'
			INSERT INTO [dbo].[TC_Replacement_Employees_Times] (EmployeeId, TimeIn, InActivityType, [InAutoStatus], [TimeInMissed], [TimeOut], OutActivityType, [OutAutoStatus], [TimeOutMissed])
			VALUES (@employeeBadge, null, null, null, null, @punchTime, @punchActivityType, 0, 0)

			-- GET INESRTED ID
			SET @insertedId = @@Identity;
			--PRINT '@insertedId: ' + CAST(@insertedId AS varchar)

			--PRINT 'exec [dbo].[p_AutoFixMissingTimePunch] ' + CAST(@insertedId AS varchar)
			exec [dbo].[p_AutoFixMissingTimePunch] @insertedId
		END
		
	END

	SELECT * FROM [dbo].[TC_Replacement_Employees_Times] WHERE ID = @InsertedId
END
GO
