ALTER PROCEDURE [dbo].[p_FIX_Sales_ItemTot_Mismatch]

AS

--EXEC dbo.p_FIX_Sales_ItemTot_Mismatch 
--p_Maintenance_Sales_ItemTot
--ran from Maintenace Plans: 

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)
