DECLARE @CntSO INT = 0
DECLARE @SalesNum INT = 0
--DECLARE @SItemTot TinyInt = 0
--DECLARE @SNItemTot TinyInt = 0
DECLARE @ItemTotMax tinyInt = 0
DECLARE @ItemTotCnt tinyInt = 0

--SELECT @CntSO = COUNT(*)
SELECT TOP 1 @SalesNum = SN.SalesNum
--SELECT SN.SalesNum AS SNSalesNum, SN.ItemTot AS SNItems, S.ItemTot AS SItems, (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE Sales.SalesNum = SN.Salesnum) AS S_Items
 FROM dbo.Sales_No SN 
 INNER JOIN dbo.Sales S ON SN.salesnum = S.salesnum
 AND SN.ItemTot < (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE Sales.SalesNum = SN.Salesnum )
 AND ISNULL(SN.cncld,0) = 0;

 IF @SalesNum > 0
	BEGIN
