	 FROM dbo.Sales_No SN 
	 INNER JOIN dbo.Sales S ON SN.salesnum = S.salesnum
	 WHERE SN.SalesNum = @SalesNum
	 AND SN.ItemTot < (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE Sales.SalesNum = SN.Salesnum )
	 AND ISNULL(SN.cncld,0) = 0; */

	SELECT @ItemTotMax = (SELECT MAX(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE SalesNum = SN.Salesnum) --MAX(SN.ItemTot)
	, @ItemTotCnt= (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE SalesNum = SN.Salesnum)
	 FROM dbo.Sales_No SN 
	 INNER JOIN dbo.Sales S ON SN.salesnum = S.salesnum
	 WHERE SN.SalesNum = @SalesNum
	 AND ISNULL(SN.cncld,0) = 0;

	PRINT '@SalesNum   '+CAST(@SalesNum   AS CHAR(10));
	PRINT '@ItemTotMax '+CAST(@ItemTotMax AS CHAR(10));
	PRINT '@ItemTotCnt '+CAST(@ItemTotCnt AS CHAR(10));

	SELECT @Body = 
	  ' --Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)+CHAR(13)
	 +' --Fixing an ItemTot Problems in Sales_No. Counted: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13) 
	 +' --@ItemTotMax '+CAST(@ItemTotMax AS CHAR(10))+'.'+CHAR(13) 
	 +' --@ItemTotCnt '+CAST(@ItemTotCnt AS CHAR(10))+'.'+CHAR(13) 

	Print '---------'+CHAR(13)
	PRINT @Body

	
	/*--UPDATE dbo.Sales_No SET ItemTot =
	SELECT SN.ItemTot , SN.SalesNum, 
	 ( SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales WITH (NOLOCK) WHERE Sales.SalesNum = SN.salesnum )
	 FROM dbo.Sales_No SN 
	 INNER JOIN dbo.Sales S ON SN.salesnum = S.salesnum 
	 AND SN.ItemTot <> (SELECT COUNT(SalesNum) AS CNTD FROM dbo.Sales S WITH (NOLOCK) WHERE S.SalesNum = SN.Salesnum ) AND ISNULL(SN.cncld,0) = 0; */


	PRINT RTRIM(GETDATE())	+ @@SERVERNAME+'.  Sales_No.ItemTot in dbo.p_Sales_ItemTot_Mismatch p_Maintenance_Sales_ItemTot ' 
	Print '---------'+CHAR(13)
	
	Set @Body= 'Found a ItemTot Problem. Sales_No Tot is less than Sales Tot.'+CHAR(13)+CHAR(13) +@Body

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Sales_No to Sales ItemTot issue.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';
	
	PRINT 'Updating Sales_No ItemTot'

	END

PRINT '****************************************************************'

RETURN

/*
    --begin transaction fixSOitem
SELECT * FROM dbo.AllQuotes WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Sales WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Sales_No WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Sales_Detail WHERE SalesNum = @SalesNum

DECLARE @nCount INT = 0
