PRINT ' Count Item' + STR(@nCount)     + ' in dbo.Sales      Item Tot' + STR(@nSItemTot)+ ' in dbo.Sales'
PRINT '  Count Tot' + STR(@nCountItot) + ' in dbo.Sales_No'
PRINT 'Count Quote' + STR(@nCountQuote)+ ' in dbo.AllQuotes   Dist ID' + STR(@nCntInqID)+ ' in dbo.AllQuotes'
PRINT ''

--DELETE from dbo.sales where soitem=' 138929-02'

