ALTER PROCEDURE [dbo].[P_ForceLogShrink]
    @MaxMins int=1 ,
    @TargetSizeMB INT=500 
AS 
	SET NOCOUNT ON
    
	DECLARE @OriginalSize INT
    DECLARE @LogicalFileName sysname       

	SELECT        @LogicalFileName=name
    FROM        sys.database_files    
	WHERE        type_desc='log'       

	SELECT        @OriginalSize=size -- in 8K pages
    FROM        sysfiles    
	WHERE        name=@LogicalFileName      

	CREATE TABLE DummyTrans
        (         DummyColumn char(8000) not null        )
   -- Wrap log and truncate it.    
	DECLARE        @Counter INT ,
        @StartTime DATETIME ,
        @TruncLog VARCHAR(255)
    SELECT        @StartTime=GETDATE() ,
        @TruncLog='BACKUP LOG ['+db_name()+'] WITH TRUNCATE_ONLY'
   -- Try an initial shrink.
    DBCC SHRINKFILE (@LogicalFileName, @TargetSizeMB) WITH NO_INFOMSGS

    EXEC (@TruncLog)

   -- Wrap the log if necessary.
    WHILE     @MaxMins>DATEDIFF(mi , @StartTime , GETDATE()) -- time has not expired
        AND @OriginalSize=(                           SELECT size FROM sysfiles WHERE name = @LogicalFileName                          )  -- the log has not shrunk
        AND (@OriginalSize*8/1024)>@TargetSizeMB  -- The value passed in for new size is smaller than the current size.
        BEGIN -- Outer loop.
            SELECT @Counter=0            
			WHILE ((@Counter<@OriginalSize/16) AND (@Counter<50000))
                BEGIN -- update
                    INSERT DummyTrans
                    VALUES ('Fill Log')  -- Because it is a char field it inserts 8000 bytes.
                    DELETE DummyTrans
                    SELECT @Counter=@Counter+1
                END   -- update
            EXEC (@TruncLog)  -- See if a trunc of the log shrinks it.
        END   -- outer loop
    DROP TABLE DummyTrans
    SELECT
         db_name() AS dbName ,
           --CONVERT(VARCHAR(30),size) as pagesSize,
         CONVERT(VARCHAR(30) , (size*8/1024)) AS NewSizeMB ,
         CONVERT(VARCHAR(30) , (@OriginalSize*8/1024)) AS OriginalSizeMB
    FROM        sysfiles    
	WHERE        name=@LogicalFileName
   --PRINT '*** Perform a full database backup ***'
    SET NOCOUNT OFF

GO
