-- =============================================
-- Author:		Sean Lykins
-- Create date: 2015 07 14
-- Description:	Get available inventory pieces - designed for use in calculating cut costs
-- =============================================
ALTER PROCEDURE [dbo].[p_GetMatchingInventory] 
	-- Add the parameters for the stored procedure here
	@alloy char(12),
	@form CHAR(2),
	@cc CHAR(1),
	@thickness DECIMAL(11,4),
	@size2 DECIMAL(10,3),
	@size3 DECIMAL(10,3)
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SELECT
	m.alloy
	,m.form
	,m.cc
	,m.Size
	--,d.Dim1
	,d.Dim2
	,d.Dim3
	FROM  dbo.stocklst_master AS m
		INNER JOIN dbo.stocklst_detail AS d ON m.id = d.id 
		LEFT JOIN dbo.Receiving r ON d.ReceivingID = r.ID
		LEFT OUTER JOIN dbo.stockLst_process AS p ON d.id_detail = p.id_detail
	WHERE ISNULL(StockTable, 'S') = 'S'
		AND ISNULL(RMA_No,0) = 0
		AND @alloy = m.Alloy
		AND @form = m.Form
		AND @cc = m.CC
		AND @thickness = m.Size
		AND (
				(@size2 <= d.Dim2 AND @size3 <= d.Dim3)
				OR
				(@size2 <= d.Dim3 AND @size3 <= d.Dim2)
			)
	AND ISNULL(p.Process_ID,'') NOT LIKE '%SELECTED%'
END
GO
/****** Object:  StoredProcedure [dbo].[p_GetMonthlyQuotedTotal]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_GetMonthlyQuotedTotal]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_GetMonthlyQuotedTotal] AS' 
END
GO
-- =============================================
-- Author:		Sean Lykins and David Kirchner
-- Create date: 2015 02 03
-- Description:	Gets the Quoted total for the month, with 7 day review.  Sales Shipped, cmplt, not cancld, sum Quoted price. 
-- Now used for 50 dollar, Million sales month
-- in HPA Chatter
-- UPDATES:
-- 07/29/2020 - Changed calculation from Sales.Quoted_Total to Sales.ItemSale
-- =============================================
ALTER PROCEDURE [dbo].[p_GetMonthlyQuotedTotal] 
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	--EXEC dbo.p_GetMonthlyQuotedTotal

    -- Insert statements for procedure here
	DECLARE @today DATETIME = GETDATE()
	DECLARE @thismonth int = MONTH(@today)
	,@thisday int = DAY(@today)
	,@thisyear int = YEAR(@today)
	
	SELECT SUM(Sales.ItemSale) AS Quoted_Total
	, IIF(@thismonth-1=0 AND @thisday <8, @thisyear - 1,@thisyear) AS Year
	, IIF(@thisday <8, IIF(@thismonth=1,12,@thismonth-1) ,@thismonth) AS Month
	FROM dbo.Sales 
	WHERE ISNULL(Sales.SalesNum,0)>0 
	AND ISNULL(Sales.Cncld,0)=0  
	AND ISNULL(Sales.cmplt,0)=1 
	AND YEAR(SHIPPED) = IIF(@thismonth-1=0 AND @thisday<8,@thisyear-1,@thisyear)
	AND (MONTH(SHIPPED) = IIF(@thisday<8, IIF(@thismonth=1 ,12, @thismonth - 1) ,@thismonth) )
END


