/****** Object:  Stored Procedure dbo.p_GetQuote    Script Date: 12/6/2005 11:46:01 AM ******/

ALTER   PROCEDURE [dbo].[p_GetQuote]
(
@nPieces INT,
@cAlloy CHAR(12),
@cForm	CHAR(2),
@cC	CHAR(1),
@nThickness DECIMAL(9,4),
@nSize2	DECIMAL(9,3),
@nSize3	DECIMAL(9,3)
)
AS
-- EXEC dbo.p_GetQuote 1,'C-276','40','1',.75,12,48
--RETURNS @nPounds, @nPoundsInCut, @nDensity, @cLbsMessage

BEGIN
SET NOCOUNT ON

DECLARE @cLbsMessage CHAR(2000)
SET @cLbsMessage = ''

DECLARE @nSawCurf DECIMAL(4,2)
SET @nSawCurf = .3


IF @nPieces < 1
	SET @nPieces = 1

DECLARE @cAlloyStd CHAR(12)
SET @cAlloyStd =  dbo.AlloyName(@cAlloy)
 
DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( @cAlloyStd ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
    SET @cLbsMessage = RTRIM(@cLbsMessage)+' Alloy Density not found!'
   END
ELSE
   SET @cLbsMessage = RTRIM(@cLbsMessage)+'Used Density of '+STR(@nDensity,5,3)
--Find Thickness used in PriceTable

DECLARE @nPounds DECIMAL(18,1)
SET @nPounds = 0
DECLARE @nPoundsInCut DECIMAL(18,1)
SET @nPoundsInCut = 0

IF @cForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		BEGIN
		SET @nPounds = 0
		SET @nPoundsInCut = 0
		END
	ELSE
	IF @nThickness > 4
		BEGIN
		SET @nPounds = (POWER(((@nThickness/2) *1.025)*2 ,2)* 3.14 * @nDensity* @nSize2* @nPieces /4)
		SET @nPoundsInCut = (POWER(@nThickness+.005,2)* 3.14* @nDensity*(@nSawCurf)* @nPieces /4)
		END
	--Changed from <3* .01 and <6 *.020 >6 *.032  2010
	--SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
   END
ELSE
IF @cForm = '11' 
   BEGIN
	--Flat Bar
	SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
	SET @nPoundsInCut = (@nDensity* @nThickness* 1.01* @nSize2*(@nSawCurf)* @nPieces )
   END
ELSE
IF @cForm = '12'
	BEGIN
	 --HEX Bar
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	SET @nPoundsInCut = (@nDensity* @nThickness*@nThickness* .866*(@nSawCurf)* @nPieces )
	END
ELSE
IF @cForm = '13' 
	BEGIN
	--Square Bar
	SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
	SET @nPoundsInCut = (@nDensity* @nThickness* 1.01* @nSize2*(@nSawCurf)* @nPieces )
	END
ELSE
IF @cForm = '20' 
	BEGIN
	--Wire Spool
	SET @nPounds = @nSize2* @nPieces 
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '21' 
	BEGIN
	--TIG Cans
	SET @nPounds = @nSize3 * @nPieces 
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '30' 
	BEGIN
	--Coated Electrodes
	SET @nPounds = @nSize3* @nPieces 
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '40' 
	BEGIN
	--Plate / Sheet
	IF @nThickness < 4
		SET @nPounds = (@nDensity* @nThickness* 1.001* @nSize2* @nSize3* @nPieces )
	ELSE
		SET @nPounds = (@nDensity* @nThickness* 1.05* @nSize2* @nSize3* @nPieces )
	
	
	IF @nThickness > .060 OR @cAlloy = '6B' OR @cAlloy = '6BH'
		SET @nPoundsInCut =((@nDensity* @nThickness* 1.005* (@nSize2+(@nSawCurf))* (@nSize3+(@nSawCurf))* @nPieces )  )-@nPounds
	ELSE
		SET @nPoundsInCut = 0

	END
ELSE
IF @cForm = '60'
   BEGIN
	SET @nPounds = @nDensity *@nSize3*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	SET @nPoundsInCut = 0
   END
ELSE
IF @cForm = '65'
   BEGIN
	DECLARE @nPipeWeight DECIMAL(9,4)
	SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
	IF @nPipeWeight = 0
		   SET @cLbsMessage = RTRIM(@cLbsMessage)+' Pipe Weight not found!'

	SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	SET @nPoundsInCut = 0
   END
ELSE
IF @cForm = '80'
   BEGIN
	--SET @nPounds = ROUND((@nDensity* @nThickness* 1.015*3.23/4* (POWER(@nSize2,2)- POWER(@nSize3,2))* @nPieces ),1)
	SET @nPounds = (@nDensity* @nThickness* 1.015* (@nSize2)* (@nSize2)* @nPieces )
	DECLARE @pcurf DECIMAL(9,5)
	
	IF @nThickness < .5  
		SET @pcurf = .5
	ELSE
		SET @pcurf = @nThickness

	SET @nPoundsInCut  = (@nDensity* @nThickness* 1.015* (@nSize2+ @pcurf)* (@nSize2+ @pcurf)* @nPieces ) - @nPounds
   END





DECLARE @nWeight DECIMAL(9,1)
SET @nWeight = @nPounds

DECLARE @nUnitPrice as DECIMAL(7,2)
DECLARE @Bracket Int
--SET @cMessage = ''

IF @nWeight < 5
	begin
	SELECT @nUnitPrice = w0 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 1
	end
ELSE
IF @nWeight >= 5 AND @nWeight < 10
	begin
	SELECT @nUnitPrice = w5 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 2
	end
ELSE
IF @nWeight >= 10 AND @nWeight < 20
	begin
	SELECT @nUnitPrice = w10 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 3
	end
ELSE
IF @nWeight >= 20 AND @nWeight < 50
	begin
	SELECT @nUnitPrice = w25 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 4
	end
ELSE
IF @nWeight >= 50 AND @nWeight < 100
	begin
	SELECT @nUnitPrice = w50 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 5
	end
ELSE
IF @nWeight >= 100 AND @nWeight < 200
	begin
	SELECT @nUnitPrice = w100 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 6
	end
ELSE
IF @nWeight >= 200 AND @nWeight < 500
	begin
	SELECT @nUnitPrice = w200 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 7
	end
ELSE
IF @nWeight >= 500 AND @nWeight < 1000
	begin
	SELECT @nUnitPrice = w500 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 8
	end
ELSE
IF @nWeight >= 1000 AND @nWeight < 2000
	begin
	--w1000
	SELECT @nUnitPrice = w1000 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 9
	end
ELSE
IF @nWeight >= 2000 AND @nWeight < 5000
	begin
	--w2000
	SELECT @nUnitPrice = w2000 FROM dbo.PriceTable WHERE Alloy=@cAlloyStd and Form=@cForm and thk=@nThickness
	SET @Bracket   = 0
	end
ELSE
	begin
	SET @nUnitPrice = 0
	SET @Bracket   = 0
	end





DECLARE @cFormUnitPrice CHAR(2)
SELECT @cFormUnitPrice = dbo.f_GetFormUnitPrice(@cForm)

DECLARE @lcFormDescription varchar(11)
SELECT @lcFormDescription = dbo.FormDescription(@cForm,@nThickness)

DECLARE @lnSurcharge REAL
SELECT @lnSurcharge = dbo.Alloy_Surcharge(@cAlloyStd)

SELECT @nPounds AS Lbs, @nPoundsInCut AS LbsCut, @nDensity AS Density, @nUnitPrice AS UnitPrice, @lnSurcharge AS Surcharge, @cFormUnitPrice AS Unit, @Bracket AS Bracket, @lcFormDescription AS Form, @cAlloyStd AS AlloyStd
--, @cLbsMessage AS LbsMess

RETURN
END




