ALTER  PROCEDURE [dbo].[p_ImageData_ins]
@Name VARCHAR(50),
@Description VARCHAR(250),
@File VARCHAR(250),
@ContentType VARCHAR(100),
@FileSize INT

AS
SET NOCOUNT ON

--Inserting FILESTREAM data
DECLARE @FileName VARCHAR(8000)
SELECT @FILE = RTRIM(@FILE)
SELECT @FileName = '\\Peregrine\Email\'+@File

DECLARE @i INT
SET @i = 1
EXEC master..xp_fileexist @FileName, @i OUT

IF @i = 1
BEGIN
--	Print 'Found File'
	WAITFOR DELAY '00:00:01'
			
	-- Declare a variable to store the image data
	DECLARE @img AS VARBINARY(MAX)
	 
	-- Load the image data
	SELECT @img = CAST(bulkcolumn AS VARBINARY(MAX))
	 FROM OPENROWSET( BULK '@FullFileName', SINGLE_BLOB ) AS x
	 
	 
	-- Insert the data to the table 
	INSERT INTO dbo.ImageData (Name, [Description], [Data], ContentType, FileSize)
	SELECT @Name, @Description, @img, @ContentType, @FileSize

	DECLARE @ID INT
	SET @ID = SCOPE_IDENTITY()

	SELECT @ID
END
ELSE
	SELECT -1



GO
