(
@nPieces TinyINT,
@cAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),
@EmailOnly CHAR(1),
@nPounds DECIMAL(9,4),
