ALTER PROCEDURE [dbo].[p_Lst_Detail_Clone]
	@ID			INT,
	@ID_Detail	INT,
	@TBL	Char(2), --@TBL_From
	@mS_QTY	Money

AS
Set NoCount On

--Clone from ANY TBL_Detail to new StockLst_Detail
--EXEC dbo.p_Lst_Detail_Clone @ID= @ID_Detail= ,@TBL='',@mS_QTY=
-- EXEC dbo.p_Lst_Detail_Clone  @ID=     17636,@ID_Detail=     40448,@TBL='SH',@mS_QTY=       396
-- Returns ID_Detail new

DECLARE @GoodTable BIT
SET @GoodTable = 0

IF @TBL='S'
	SET @GoodTable = 1
ELSE
	IF @TBL='B'
		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1
		ELSE
			IF @TBL='SH'
				SET @GoodTable = 1
			ELSE
				IF @TBL='BH'
					SET @GoodTable = 1
				ELSE
					IF @TBL='WH'
						SET @GoodTable = 1
					ELSE
						--PRINT 'dbo.p_Lst_Detail_Clone: Unkown TBL'

IF @mS_QTY IS NULL
	SET @mS_QTY = ISNULL(@mS_QTY,0)



IF @GoodTable = 0 OR @ID_Detail = 0
	SELECT 0
ELSE
	begin
		
	IF @TBL='S'
	  INSERT INTO dbo.Stocklst_Detail (
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,[Length]
		,[Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,[InvCheck]
		,[ID]
		--,[ID_Detail]
		,[ReceivingID]
		,[InvoiceValue]
		,[LiveCheck]
		,[AccountingCheck]
		,[Quarantine]
		,[S_QTY]
		,[S_P]
		,[S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		   )
		SELECT 
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,'' AS [Length]
		,CASE when [S_PU] = 1 then @mS_QTY else 0 end   AS [Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,'' AS [InvCheck]
		, @ID AS [ID]
		--,[ID_Detail]
		,0 AS [ReceivingID]
		,0 AS [InvoiceValue]
		,0 AS [LiveCheck]
		,0 AS [AccountingCheck]
		,0 AS [Quarantine]
		, @mS_QTY AS [S_QTY]
		,[S_P]
		,ISNULL(@mS_QTY* S_P,0) AS [S_Total]
		,[S_PU]
		,[Prime]
		,[WO]
		FROM dbo.Stocklst_Detail WITH(NOLOCK)
			WHERE ID_Detail = @ID_Detail

	IF @TBL='B'
	  INSERT INTO dbo.StockLst_Detail (
		 [Size_H]
		,[Size_L]
		,[PC]
		,[Dim1]
		,[Dim2]
		,[Dim3]
		,[Length]
		,[Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,[InvCheck]
		,[ID]
		--,[ID_Detail]
		,[ReceivingID]
		,[InvoiceValue]
		,[LiveCheck]
		,[AccountingCheck]
		,[Quarantine]
		,[S_QTY]
		,[S_P]
