		,[Dim2]
		,[Dim3]
		,'' AS [Length]
		,CASE when [S_PU] = 1 then @mS_QTY else 0 end   AS [Weight]
		,[CostValue]
		,[Descript]
		,[Location]
		,[FloorStatus]
		,[Class]
		,[Unit]
		,[RandLen]
		,'' AS [InvCheck]
		, @ID AS [ID]
		--,[ID_Detail]
