ALTER  PROCEDURE [dbo].[p_Lst_Detail_ins]
	@TBL		Char(1),
	@size_h		decimal(9, 4),
	@size_l		decimal(9, 4),
	@pc		    INT,
	@dim1		decimal(18, 4),
	@dim2		decimal(18, 4),
	@dim3		decimal(18, 4),
	@length		varchar(160),
	@weight		decimal(18, 8),
	@descript	varchar(20),
	@location	varchar(10),
	@floorstatus	char(1),
	@class		char(1),
	@RandLen	BIT,
	@ID		int,
	@ID_Detail_Process int,
	@ReceivingID	int,
	@S_QTY		decimal(18, 4),
	@S_P		decimal(18, 4),
	@S_TOTAL	decimal(18, 4),
	@S_PU	TinyInt	

AS

SET NOCOUNT ON

DECLARE @GoodTable BIT
SET @GoodTable = 0

IF @TBL='S'
	SET @GoodTable = 1
ELSE
	IF @TBL='B'
		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1

DECLARE @ID_Detail INT
SET @ID_Detail = 0


IF @GoodTable = 0 OR @ID = 0 --OR @ID_Detail_Process = 0
	SET @ID_Detail = 0
ELSE
	BEGIN
	
	PRINT ' starting Stored Procedure dbo.p_Lst_Detail_ins '
 
--SELECT * FROM dbo.BrokerLst_Process_detail WHERE ID=@id and ID_Detail_Process=@ID_Detail_Process AND What ='ADD'

	 IF @TBL='S'
		begin
		INSERT INTO dbo.StockLst_Process_Detail 
			(ID, ID_Detail_Process, What ) 
		VALUES (@id, @ID_Detail_Process, 'ADD' )

	  INSERT INTO dbo.StockLst_Detail WITH (ROWLOCK)  (
		[size_h],
		[size_l],
		[pc],
		[dim1],
		[dim2],
		[dim3],
		[length],
		[weight],
		[descript],
		[location],
		[floorstatus],
		[class],
		[RandLen],
		[InvCheck],
		[ID],
		[ReceivingID],
		S_QTY,
		S_P	,
		S_TOTAL,
		S_PU 
		) Values (
		@size_h,
		@size_l,
		@pc,
		@dim1,
		@dim2,
		@dim3,
		@length,
		@weight,
		@descript,
		@location,
		@floorstatus,
		@class,
		@RandLen,
		GetDate(),
		@ID,
		@ReceivingID,
		@S_QTY,
		@S_P	,
		@S_TOTAL,
		@S_PU
		)

		SET @ID_Detail = SCOPE_IDENTITY()
		--Print 'Got ID_Detail '+CAST(@ID_Detail AS CHAR(10))

		UPDATE dbo.StockLst_Process_Detail 
		  SET  [ID_Detail] = @ID_Detail 
		  WHERE [ID] = @ID 
		  AND [ID_Detail_Process] = @ID_Detail_Process 
		  AND [What] = 'ADD'

		--SELECT * FROM dbo.BrokerLst_Process_detail WHERE ID=@id and ID_Detail_Process=@ID_Detail_Process AND What ='ADD'
		END

	IF @TBL='B'
		begin
		INSERT INTO dbo.BrokerLst_Process_Detail 
			(ID, ID_Detail_Process, What ) 
		VALUES (@id, @ID_Detail_Process, 'ADD' )

	  INSERT INTO dbo.BrokerLst_Detail WITH (ROWLOCK)  (
		[size_h],
		[size_l],
		[pc],
		[dim1],
		[dim2],
		[dim3],
		[length],
		[weight],
		[descript],
		[location],
		[floorstatus],
		[class],
		[RandLen],
		[InvCheck],
		[ID],
		[ReceivingID],
		S_QTY,
		S_P	,
		S_TOTAL,
		S_PU 
		) Values (
		@size_h,
		@size_l,
		@pc,
		@dim1,
		@dim2,
		@dim3,
		@length,
		@weight,
		@descript,
		@location,
		@floorstatus,
		@class,
		@RandLen,
		GetDate(),
		@ID,
		@ReceivingID,
		@S_QTY,
		@S_P	,
		@S_TOTAL,
		@S_PU
		)

		SET @ID_Detail = SCOPE_IDENTITY()
		--Print 'Got ID_Detail '+CAST(@ID_Detail AS CHAR(10))

		UPDATE dbo.BrokerLst_Process_Detail 
		  SET  [ID_Detail] = @ID_Detail 
		  WHERE [ID] = @ID 
		  AND [ID_Detail_Process] = @ID_Detail_Process 
		  AND [What] = 'ADD'

		--SELECT * FROM dbo.BrokerLst_Process_detail WHERE ID=@id and ID_Detail_Process=@ID_Detail_Process AND What ='ADD'
		END

	IF @TBL='W'
		begin
		INSERT INTO dbo.WIPLst_Process_Detail 
			(ID, ID_Detail_Process, What ) 
		VALUES (@id, @ID_Detail_Process, 'ADD' )

	  INSERT INTO dbo.WIPLst_Detail WITH (ROWLOCK)  (
		[size_h],
		[size_l],
		[pc],
		[dim1],
		[dim2],
		[dim3],
		[length],
		[weight],

		[descript],
		[location],
		[floorstatus],
		[class],
		[RandLen],
		[InvCheck],
		[ID],
		[ReceivingID],
		S_QTY,
		S_P	,
		S_TOTAL,
		S_PU 
		) Values (
		@size_h,
		@size_l,
		@pc,
		@dim1,
		@dim2,
		@dim3,
		@length,
		@weight,

		@descript,
		@location,
		@floorstatus,
		@class,
		@RandLen,
		GetDate(),
		@ID,
		@ReceivingID,
		@S_QTY,
		@S_P	,
		@S_TOTAL,
		@S_PU
		)

		SET @ID_Detail = SCOPE_IDENTITY()
		--Print 'Got ID_Detail '+CAST(@ID_Detail AS CHAR(10))

		UPDATE dbo.WIPLst_Process_Detail 
		  SET  [ID_Detail] = @ID_Detail 
		  WHERE [ID] = @ID 
		  AND [ID_Detail_Process] = @ID_Detail_Process 
		  AND [What] = 'ADD'

		--SELECT * FROM dbo.BrokerLst_Process_detail WHERE ID=@id and ID_Detail_Process=@ID_Detail_Process AND What ='ADD'
		end


	SELECT @ID_Detail

	END

