ALTER PROCEDURE [dbo].[p_Lst_Master_ins]
	@TBL		Char(1),
	@Alloy		char(12),
	@Form		char(2),
	@CC		    char(1),
	@Size		decimal(9,3),
	@Cond		varchar(30),
	@MWeight	decimal(18,8),
	@Specs		varchar(160),
	@Heat		varchar(50),
	@Lot		varchar(10),
	@Paid		decimal(18,8),
	@PO_Item	char(12),
	@PODueDate	smallDateTime,
	@Mill		varchar(10),
	@StkDate	smallDateTime,
	@History	varchar(20),
	@Num		decimal(8,0),
	@POStatus	char(1),
