		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1



DECLARE @ID_Detail_Process INT

IF @GoodTable = 0 
	SELECT 0
ELSE
	begin
	
	PRINT ' starting Stored Procedure dbo.p_Lst_Master_ins '

	IF @TBL='S'
		INSERT INTO dbo.StockLst_Master (
 			Alloy,
