			@History,
			@Num,
			@POStatus,
			@BrandName,
			--,[MillTrace]
			@From_ID,
			@Melt,
			@WO_Detail)


	IF @TBL='B'
		INSERT INTO dbo.BrokerLst_Master (
 			Alloy,
			Form,
			cc,
			[Size],
			Cond,
			MWeight,
			Specs,
			Heat,
			Lot,
			Paid,
			PO_Item,
			PODueDate,
			Mill,
			StkDate,
			History,
			Num,
			POStatus,
			BrandName,
			--,[MillTrace]
