			@PO_Item,
			@PODueDate,
			@Mill,
			@StkDate,
			@History,
			@Num,
			@POStatus,
			@BrandName,
			--,[MillTrace]
			@From_ID,
			@Melt,
			@WO_Detail )
		

	IF @TBL='W'
		INSERT INTO dbo.WIPLst_Master (
 			Alloy,
			Form,
			cc,
			[Size],
			Cond,
			MWeight,
			Specs,
			Heat,
