ALTER PROCEDURE [dbo].[p_Lst_Process_Grab_ins]
	@ID_Detail_Process	int,
	@TBL CHAR(1)
AS

  Set NoCount On

--Process_ID = SELECTED,INCOMING,PARTRECV,RECEIVED,SHIPPED,CORRECTED,SUBED
--'CANCELLED,CORRECTION,Receiving,PartSelect,Sell Stock'
--
--SELECT top 10 * FROM dbo.StockLst_Process ORDER BY ID_Detail_Process DESC
--

DECLARE @GoodTable BIT
SET @GoodTable = 0

IF @TBL='S'
	SET @GoodTable = 1
ELSE
	IF @TBL='B'
		SET @GoodTable = 1
	ELSE
		IF @TBL='W'
			SET @GoodTable = 1

IF @GoodTable = 0
	RETURN;
--***********************************************
IF @TBL='S'
	INSERT INTO dbo.StockLst_Process_Grab WITH (ROWLOCK)  
		(
		[SOitem]
		  ,[PO_item]
		  ,[SalesPerson]
		  ,[StartDate]
		  ,[DueDate]
		  ,[Comment]
		  ,[Process_ID]
		  ,[Processor]
		  ,[AllowSub]
		  ,[PWeight]
		  ,[PU]
		  ,[QTY]
		  ,[S_P]
		  ,[Ordered_QTY]
		  ,[Ordered_P]
		  ,[Pounds]
		  ,[ID_Master]
		  ,[ID_Detail]
		  ,[ID_Detail_Process]
		  ,[ReceivingID]
		  ,[WO]
		  ,[WO_Detail]
		  ,[InqNumP]
		  ,[Prc_Form]
		  ,[Prc_PCs]
		  ,[Prc_Dim1]
		  ,[Prc_Dim2]
		  ,[Prc_Dim3]
		  ,[Descript]
		  ,[FoundStk]
		  )
		SELECT TOP 1
		SP.[SOitem]
		  ,SP.[PO_item]
		  ,SP.[SalesPerson]
		  ,SP.[StartDate]
		  ,SP.[DueDate]
		  ,SP.[Comment]
		  ,SP.[Process_ID]
		  ,SP.[Processor]
		  ,SP.[AllowSub]
		  ,SP.[PWeight]
		  ,SP.[PU]
		  ,SP.[QTY]
		  ,SD.[S_P]
		  ,SP.[Ordered_QTY]
		  ,SP.[Ordered_P]
		  ,SP.[Pounds]
		  ,SD.[ID]
		  ,SP.[ID_Detail]
		  ,SP.[ID_Detail_Process]
		  ,SD.[ReceivingID]
		  ,SP.[WO]
		  ,SP.[WO_Detail]
		  ,SP.[InqNumP]
		  ,SP.[Prc_Form]
		  ,SP.[Prc_PCs]
		  ,SP.[Prc_Dim1]
		  ,SP.[Prc_Dim2]
		  ,SP.[Prc_Dim3]
		  ,dbo.f_DescriptCL(SM.Alloy,SM.CC,SM.CL,SM.Form,SP.[Prc_Dim1],SP.[Prc_Dim2],SP.[Prc_Dim3],SP.[PWeight],SD.RandLen) AS Descript 
		  ,SP.[FoundStk]
	--	  ,GETDATE()
		  FROM dbo.StockLst_Process SP
		  INNER JOIN dbo.StockLst_Detail SD WITH(NOLOCK) ON SP.ID_Detail= SD.ID_Detail
		  inner join dbo.StockLst_Master SM WITH(NOLOCK) ON SD.ID = SM.ID
		  WHERE ID_Detail_Process = @ID_Detail_Process

--***********************************************--
IF @TBL='B'
	INSERT INTO dbo.BrokerLst_Process_Grab WITH (ROWLOCK)  
		(
		[SOitem]
		  ,[PO_item]
		  ,[SalesPerson]
		  ,[StartDate]
		  ,[DueDate]
		  ,[Comment]
		  ,[Process_ID]
		  ,[Processor]
		  ,[AllowSub]
		  ,[PWeight]
		  ,[PU]
		  ,[QTY]
		  ,[S_P]
		  ,[Ordered_QTY]
		  ,[Ordered_P]
		  ,[Pounds]
		  ,[ID_Master]
		  ,[ID_Detail]
		  ,[ID_Detail_Process]
		  ,[ReceivingID]
		  ,[WO]
		  ,[WO_Detail]
		  ,[InqNumP]
		  ,[Prc_Form]
		  ,[Prc_PCs]
		  ,[Prc_Dim1]
		  ,[Prc_Dim2]
		  ,[Prc_Dim3]
		  ,[Descript]
		  ,[FoundStk]
		  )
		SELECT TOP 1
		SP.[SOitem]
		  ,SP.[PO_item]
		  ,SP.[SalesPerson]
		  ,SP.[StartDate]
		  ,SP.[DueDate]
		  ,SP.[Comment]
		  ,SP.[Process_ID]
		  ,SP.[Processor]
		  ,SP.[AllowSub]
		  ,SP.[PWeight]
		  ,SP.[PU]
		  ,SP.[QTY]
		  ,SD.[S_P]
		  ,SP.[Ordered_QTY]
		  ,SP.[Ordered_P]
		  ,SP.[Pounds]
		  ,SD.[ID]
		  ,SP.[ID_Detail]
		  ,SP.[ID_Detail_Process]
		  ,SD.[ReceivingID]
		  ,SP.[WO]
		  ,SP.[WO_Detail]
		  ,SP.[InqNumP]
		  ,SP.[Prc_Form]
		  ,SP.[Prc_PCs]
		  ,SP.[Prc_Dim1]
		  ,SP.[Prc_Dim2]
		  ,SP.[Prc_Dim3]
		  ,dbo.f_DescriptCL(SM.Alloy,SM.CC,SM.CL,SM.Form,SP.[Prc_Dim1],SP.[Prc_Dim2],SP.[Prc_Dim3],SP.[PWeight],SD.RandLen) AS Descript 
		  ,SP.[FoundStk]
	--	  ,GETDATE()
		  FROM dbo.BrokerLst_Process SP
		  INNER JOIN dbo.BrokerLst_Detail SD WITH(NOLOCK) ON SP.ID_Detail= SD.ID_Detail
		  inner join dbo.BrokerLst_Master SM WITH(NOLOCK) ON SD.ID = SM.ID
		  WHERE ID_Detail_Process = @ID_Detail_Process

--***********************************************
IF @TBL='W'
	INSERT INTO dbo.WIPLst_Process_Grab WITH (ROWLOCK)  
		(
		[SOitem]
		  ,[PO_item]
		  ,[SalesPerson]
		  ,[StartDate]
		  ,[DueDate]
		  ,[Comment]
		  ,[Process_ID]
		  ,[Processor]
		  ,[AllowSub]
		  ,[PWeight]
		  ,[PU]
		  ,[QTY]
		  ,[S_P]
		  ,[Ordered_QTY]
		  ,[Ordered_P]
		  ,[Pounds]
		  ,[ID_Master]
		  ,[ID_Detail]
		  ,[ID_Detail_Process]
		  ,[ReceivingID]
		  ,[WO]
		  ,[WO_Detail]
		  ,[InqNumP]
		  ,[Prc_Form]
		  ,[Prc_PCs]
		  ,[Prc_Dim1]
		  ,[Prc_Dim2]
		  ,[Prc_Dim3]
		  ,[Descript]
		  ,[FoundStk]
		  )
		SELECT TOP 1
		SP.[SOitem]
		  ,SP.[PO_item]
		  ,SP.[SalesPerson]
		  ,SP.[StartDate]
		  ,SP.[DueDate]
		  ,SP.[Comment]
		  ,SP.[Process_ID]
		  ,SP.[Processor]
		  ,SP.[AllowSub]
		  ,SP.[PWeight]
		  ,SP.[PU]
		  ,SP.[QTY]
		  ,SD.[S_P]
		  ,SP.[Ordered_QTY]
		  ,SP.[Ordered_P]
		  ,SP.[Pounds]
		  ,SD.[ID]
		  ,SP.[ID_Detail]
		  ,SP.[ID_Detail_Process]
		  ,SD.[ReceivingID]
		  ,SP.[WO]
		  ,SP.[WO_Detail]
		  ,SP.[InqNumP]
		  ,SP.[Prc_Form]
		  ,SP.[Prc_PCs]
		  ,SP.[Prc_Dim1]
		  ,SP.[Prc_Dim2]
		  ,SP.[Prc_Dim3]
		  ,dbo.f_DescriptCL(SM.Alloy,SM.CC,SM.CL,SM.Form,SP.[Prc_Dim1],SP.[Prc_Dim2],SP.[Prc_Dim3],SP.[PWeight],SD.RandLen) AS Descript 
		  ,SP.[FoundStk]
	--	  ,GETDATE()
		  FROM dbo.WIPLst_Process SP
		  INNER JOIN dbo.WIPLst_Detail SD WITH(NOLOCK) ON SP.ID_Detail= SD.ID_Detail
		  inner join dbo.WIPLst_Master SM WITH(NOLOCK) ON SD.ID = SM.ID
		  WHERE ID_Detail_Process = @ID_Detail_Process


