,@Processor = 'Jared Kimbrough',@AllowSub = 'N',@PU =          1,@QTY =          3506.0000,@Pounds =3506,@nID_Detail =      41277
,@ReceivingID = 0,@WO =          0,@WO_Detail =          0
*/

SET @SOitem = dbo.ProperSO( @SOitem ) 
--PRINT dbo.ProperSO( '')
SET @PO_item = dbo.ProperPO( @PO_item )


DECLARE @GoodTable BIT
SET @GoodTable = 0

