	SET @GoodTable = 1
ELSE IF @cTBL='B'
	SET @GoodTable = 1
ELSE IF @cTBL='W'
	SET @GoodTable = 1
ELSE
	RETURN 0


DECLARE @nID_Detail_Process INT = 0

IF @GoodTable = 0 OR @nID_Detail = 0
	SET @nID_Detail_Process= 0
ELSE
	begin
	
	PRINT ' starting Stored Procedure [dbo].[p_Lst_Process_ins_Tran] ';

	BEGIN TRANSACTION Lst_Process;

	IF @cTBL='S'
		INSERT INTO dbo.StockLst_Process WITH (ROWLOCK)  (
