		,AllowSub		,PU				,QTY			,Pounds
		,SOitem			,PO_Item		,WO				,WO_Detail
		,Process_ID		,Processor		,Comment		,ReceivingID
		,Prc_Form		,Prc_PCs		,Prc_Dim1		,Prc_Dim2		,Prc_Dim3
		,Ordered_QTY	,Ordered_P
		) Values (
		 @nID_Detail	,@SalesPerson	,@StartDate		,@DueDate
		,@AllowSub		,@PU			,@QTY			,@Pounds
		,@SOitem		,@PO_Item		,@WO			,@WO_Detail
		,@Process_ID	,@Processor		,@Comment		,@ReceivingID
		,@Prc_Form		,@Prc_PCs		,@Prc_Dim1		,@Prc_Dim2		,@Prc_Dim3
		,@Ordered_QTY	,@Ordered_P		);

	ELSE IF @cTBL='B'
		INSERT INTO dbo.BrokerLst_Process WITH (ROWLOCK)  (
		ID_Detail		,SalesPerson	,StartDate		,DueDate
		,AllowSub		,PU				,QTY			,Pounds
		,SOitem			,PO_Item		,WO				,WO_Detail
		,Process_ID		,Processor		,Comment		,ReceivingID
		,Prc_Form		,Prc_PCs		,Prc_Dim1		,Prc_Dim2		,Prc_Dim3
		,Ordered_QTY	,Ordered_P
		) Values (
		 @nID_Detail	,@SalesPerson	,@StartDate		,@DueDate
		,@AllowSub		,@PU			,@QTY			,@Pounds
		,@SOitem		,@PO_Item		,@WO			,@WO_Detail
		,@Process_ID	,@Processor		,@Comment		,@ReceivingID
		,@Prc_Form		,@Prc_PCs		,@Prc_Dim1		,@Prc_Dim2		,@Prc_Dim3
		,@Ordered_QTY	,@Ordered_P		);

	ELSE IF @cTBL='W'
		INSERT INTO dbo.WIPLst_Process WITH (ROWLOCK)  (
		ID_Detail		,SalesPerson	,StartDate		,DueDate
		,AllowSub		,PU				,QTY			,Pounds
		,SOitem			,PO_Item		,WO				,WO_Detail
		,Process_ID		,Processor		,Comment		,ReceivingID
		,Prc_Form		,Prc_PCs		,Prc_Dim1		,Prc_Dim2		,Prc_Dim3
		,Ordered_QTY	,Ordered_P
		) Values (
		 @nID_Detail	,@SalesPerson	,@StartDate		,@DueDate
		,@AllowSub		,@PU			,@QTY			,@Pounds
		,@SOitem		,@PO_Item		,@WO			,@WO_Detail
		,@Process_ID	,@Processor		,@Comment		,@ReceivingID
		,@Prc_Form		,@Prc_PCs		,@Prc_Dim1		,@Prc_Dim2		,@Prc_Dim3
		,@Ordered_QTY	,@Ordered_P		);
 
	
	SET @nID_Detail_Process = SCOPE_IDENTITY()

	PRINT ' end Stored Procedure dbo.p_Lst_Process_ins_Tran '

	end
	-----------------------------------------------------------
	DECLARE @nID INT = 0;
	DECLARE @cSQLid NVARCHAR(MAX) = '';

	IF @nID_Detail_Process > 0
	begin
		
		--Get ID
		IF @cTBL = 'S'
			SELECT @nID=ISNULL(ID,0) from dbo.StockLst_Detail WHERE ID_Detail = @nID_Detail;
		ELSE IF @cTBL = 'B'
			SELECT @nID=ISNULL(ID,0) from dbo.BrokerLst_Detail WHERE ID_Detail = @nID_Detail;
		ELSE IF @cTBL = 'W'
			SELECT @nID=ISNULL(ID,0) from dbo.WIPLst_Detail WHERE ID_Detail = @nID_Detail;

	end

	-----------------------------------------------------------
	IF @nID > 0
	begin

		--INSERT INTO dbo. Lst_Process_Detail
		IF @cTBL = 'S'
			INSERT INTO dbo.StockLst_Process_Detail (ID, ID_Detail, ID_Detail_Process, What) VALUES (@nID, @nID_Detail, @nID_Detail_Process, 'REMOVED');
		ELSE IF @cTBL = 'B'
			INSERT INTO dbo.BrokerLst_Process_Detail (ID, ID_Detail, ID_Detail_Process, What) VALUES (@nID, @nID_Detail, @nID_Detail_Process, 'REMOVED');
		ELSE IF @cTBL = 'W'
			INSERT INTO dbo.WIPLst_Process_Detail (ID, ID_Detail, ID_Detail_Process, What) VALUES (@nID, @nID_Detail, @nID_Detail_Process, 'REMOVED');

	end

	-----------------------------------------------------------
	IF @nID > 0
	begin

		--Now DELETE that new Process
		IF @cTBL = 'S'
			DELETE dbo.StockLst_Process WHERE ID_Detail_Process=@nID_Detail_Process;
		ELSE IF @cTBL = 'B'
			DELETE dbo.BrokerLst_Process WHERE ID_Detail_Process=@nID_Detail_Process;
		ELSE IF @cTBL = 'W'
			DELETE dbo.WIPLst_Process WHERE ID_Detail_Process=@nID_Detail_Process;
			
	end

	-----------------------------------------------------------
	IF @nID > 0
	begin
	
		--Now DELETE that new Process_Detail
		IF @cTBL = 'S'
			DELETE dbo.StockLst_Process_Detail WHERE ID_Detail_Process=@nID_Detail_Process;
		ELSE IF @cTBL = 'B'
			DELETE dbo.BrokerLst_Process_Detail WHERE ID_Detail_Process=@nID_Detail_Process;
		ELSE IF @cTBL = 'W'
			DELETE dbo.WIPLst_Process_Detail WHERE ID_Detail_Process=@nID_Detail_Process;

	end

	-----------------------------------------------------------
	--BEGIN TRANSACTION Lst_Process;
	IF @nID_Detail_Process > 0 AND @nID > 0
		COMMIT;
	ELSE
		ROLLBACK;
	

  SELECT @nID_Detail_Process;


  --GRANT EXECUTE ON [dbo].[p_Lst_Process_ins_Tran] TO [WINDFALL\HPA] AS [dbo];
GO
