	---------------------------------------------------	

	--SET QUOTED_IDENTIFIER OFF;

	--DELETE FROM dbo.Brokerlst_Master WHERE ID=@ID;
	UPDATE dbo.Brokerlst_Master SET History=LEFT('Lost Detail '+[History],20) 
			,Specs = LEFT('p_Maintenance_BrokerLst_Detail '+[Specs],160)  --Added 9/25/2025
			WHERE ID IN (SELECT DISTINCT M.ID 
			FROM dbo.BrokerLst_Master M 
				WHERE ISNULL((SELECT TOP 1 ID FROM dbo.BrokerLst_Detail D 
				WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0 );

	DELETE FROM dbo.BrokerLst_Master	WHERE ID in 
		(SELECT ID FROM dbo.BrokerLst_Master M
			WHERE ISNULL((SELECT TOP 1 ID_Detail FROM dbo.BrokerLst_Detail D 
						WHERE D.ID = M.ID AND ISNULL(ID_Detail,0)>0 ),0) = 0);

	--SET QUOTED_IDENTIFIER ON;

	END

-----------------------------
RETURN

