ALTER PROCEDURE [dbo].[p_Maintenance_Process_Cancel]

AS

--EXEC dbo.p_Maintenance_Process_Cancel
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday
--print ERP_1.dbo.f_GetSQL_Server_Email()
--print dbo.f_Get_profile_name('');

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = 'David.Kirchner@ERP_1s.com' --ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)
DECLARE @CntSO INT = 0

DECLARE @SOitem CHAR(12), @Process_ID CHAR(10)

SELECT @CntSO = COUNT(*) FROM dbo.StockLst_Process SP
	LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
	WHERE ISNULL(S.cncld,0)>0

IF @CntSO > 0
	BEGIN

	PRINT 'SO Cancelled with Process issue.'

	SELECT TOP 1 @Process_ID=ISNULL(SP.Process_ID,'')
		, @SOitem=ISNULL(SP.SOitem,'')
		FROM dbo.StockLst_Process SP
		LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
		WHERE ISNULL(S.cncld,0)>0 ;

	SELECT @Body = '@SOitem '+@SOitem+CHAR(13)
		+'@Process_ID '+@Process_ID+CHAR(13)+CHAR(13)

	SELECT @Body = @Body+ ('SELECT @CntSO = COUNT(*) FROM dbo.StockLst_Process SP'+CHAR(13)
		+' LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem'+CHAR(13)
		+'WHERE ISNULL(S.cmplt,0)>0'+CHAR(13)

		+' --Found a Stock Process Problem and Deleted them.'+CHAR(13)
		+' Counted: '+ CAST(@CntSO AS CHAR(10))+'.'
		+' on '+RTRIM(GETDATE())  
		+@@SERVERNAME+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Process_Cancel ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Cancelled SO has Stock Process issue.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'

	----------
	/*
	DECLARE @msg VARCHAR(250);
	DECLARE @query varchar(2048);
	DECLARE @cProfile_Name VarChar(50);

	SET @query='SELECT *
		FROM dbo.StockLst_Process SP
		LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
		WHERE ISNULL(S.cncld,0)>0;';

	SET @msg = 'Please refer to the attached spread sheet for the report before deleting.'+CHAR(13)+@query

	SET @cProfile_Name = dbo.f_Get_profile_name('David Kirchner');

	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_Process_SOCancel'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_Process_SOCancel.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;
		*/
	----------
		DELETE FROM dbo.StockLst_Process WHERE ID_Detail_Process IN 
			(SELECT ID_Detail_Process 
			FROM dbo.StockLst_Process SP
			LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
			WHERE ISNULL(S.cncld,0)>0 )

		END

--BrokerLst
SELECT @CntSO = COUNT(*) FROM dbo.BrokerLst_Process SP
	LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
	WHERE ISNULL(S.cncld,0)>0

IF @CntSO > 0
	BEGIN

	PRINT 'SO Cancelled with Process issue.'

	SELECT TOP 1 @Process_ID=ISNULL(SP.Process_ID,'')
		, @SOitem=ISNULL(SP.SOitem,'')
		FROM dbo.BrokerLst_Process SP
		LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
		WHERE ISNULL(S.cncld,0)>0 ;

	SELECT @Body = '@SOitem '+@SOitem+CHAR(13)
		+'@Process_ID '+@Process_ID+CHAR(13)+CHAR(13)

	SELECT @Body = @Body+('SELECT @CntSO = COUNT(*) FROM dbo.BrokerLst_Process SP'+CHAR(13)
		+' LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem'+CHAR(13)
		+'WHERE ISNULL(S.cmplt,0)>0;'+CHAR(13)+CHAR(13)

		+' --Found a Cancelled SO Broker Process Problem and Deleted.'+CHAR(13)
		+' on '+RTRIM(GETDATE())  
		+@@SERVERNAME+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Sales_Summary ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David@ERP_1s.com', 
			@SubjectEmail = 'SO Cancelled Broker Process issue.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'


		DELETE FROM dbo.BrokerLst_Process WHERE ID_Detail_Process IN 
			(SELECT ID_Detail_Process 
			FROM dbo.BrokerLst_Process SP
			LEFT OUTER JOIN dbo.Sales S ON S.SOitem = SP.SOitem
			WHERE ISNULL(S.cncld,0)>0 )

		END

RETURN

