ALTER PROCEDURE [dbo].[p_Maintenance_Process_Complete]

AS

--EXEC p_Maintenance_Process_Complete
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

--Remove INCOMING Process for PO cmplt DELETE code

-- Stopped the code on 2025-10-29
-- Receiving program should do This !

--Kept SELECTED Stock SOitem complete DELETE code
--kept SELECTED Broker SOitem complete DELETE code
--Kept SELECTED WO Complete DELETE code
--Kept SELECTED WO_Detail Complete DELETE code
--Kept IMCOMING WO_Detail Complete DELETE code

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email();
DECLARE @Body varchar(4000);
DECLARE @Cnt INT = 0;


DECLARE @cProfile_Name VarChar(50);
SET @cProfile_Name = dbo.f_Get_profile_name('')

DECLARE @msg VARCHAR(250);
DECLARE @query varchar(2048);

DECLARE @POitem CHAR(12), @SOitem CHAR(12), @Process_ID CHAR(10), @nID_Detail INT, @nID_Detail_Process INT, @Company VARCHAR(30)

-------------------INCOMING Stock

SELECT @Cnt = COUNT(*) --SELECT *
 FROM dbo.StockLst_Process P WITH(NOLOCK)
 INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
 WHERE ( PO.Cmplt = 1 OR PO.Services = 1 OR P.SOitem LIKE '%Equipment%' )
  AND P.Process_ID = 'INCOMING'
  --AND dbo.f_ProperSOitem(P.SOitem) = dbo.f_ProperSOitem('') --and no Proper SOitem


IF @Cnt > 0
	BEGIN


	
	SELECT TOP 1 @POitem=ISNULL(P.PO_item,'')
		, @Process_ID=ISNULL(P.Process_ID,'')
		, @SOitem=ISNULL(P.SOitem,''), @Company=ISNULL(PO.Company,'')
		, @nID_Detail = ISNULL(P.ID_Detail,0)
		, @nID_Detail_Process = ISNULL(P.ID_Detail_Process,0)
			FROM dbo.StockLst_Process P
			INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
			WHERE ( PO.Cmplt = 1 OR PO.Services = 1 OR P.SOitem like '%Equipment%' )
			 AND P.Process_ID = 'INCOMING'

	SELECT @Body = dbo.f_Get_HTML_Header()+CHAR(13)
		+'@POitem '+@POitem+' '+CHAR(13)
		+' '+dbo.f_HTML_link_POitem(@POitem)+CHAR(13)
		+'@SOitem '+@SOitem+' '
		+' '+dbo.f_HTML_link_SOitem(@SOitem)+CHAR(13)
		+'@Process_ID '+@Process_ID+CHAR(13)
		+'@Company '+@Company+CHAR(13)
		+'@ID_Detail '+CAST(@nID_Detail AS CHAR(10) )+CHAR(13)
		+'@ID_Detail_Process '+CAST(@nID_Detail_Process AS CHAR(10) )+CHAR(13)
		+CHAR(10)+CHAR(13)

	SELECT @Body = @Body + dbo.f_HTML_HPA_Footer(0)

	SELECT @Body = @Body+('SELECT P.PO_item,P.SalesPerson,P.Process_ID,P.SOitem,PO.Company'+CHAR(13)
		+' FROM dbo.StockLst_Process P'+CHAR(10)+CHAR(13)
		+' INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem'+CHAR(10)+CHAR(13)
		+'WHERE ( PO.Cmplt = 1 OR PO.Services = 1 OR P.SOitem LIKE ''%Equipment%'' ) '+CHAR(13)
		+' AND P.Process_ID = ''INCOMING'' '+CHAR(13)+CHAR(10)
		+' --PO was Complete and still Found a Stock Process Problem.'+CHAR(10)+CHAR(13)
		+'top POitem: '+@POitem+'. '+'"'+dbo.f_HTML_link_POitem(@POitem)+' '+'"'+CHAR(10)+CHAR(13)
		+' DELETED:'+ RTRIM(CAST(@Cnt AS CHAR(10)))+'.'+CHAR(10)+CHAR(13)
		+' on '+RTRIM(GETDATE())  +@@SERVERNAME+CHAR(10)+CHAR(13)
		+' Agent Job _ERP_1  weekly dbo.p_Maintenance_Process_Complete ' )
		
	SELECT @Body = @Body + dbo.f_HTML_HPA_Footer(0)

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Deleted Stock Process for Complete POitem.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'


		---------------------------------------------------
/*		DELETE FROM dbo.StockLst_Process WHERE ID_Detail_Process IN 
			(SELECT P.ID_Detail_Process 
			 FROM dbo.StockLst_Process P
			 INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
			 WHERE ( PO.Cmplt = 1 OR PO.Services = 1 OR P.SOitem LIKE '%Equipment%' )
			  AND P.Process_ID = 'INCOMING' )
*/
	END

--------------------------------INCOMING Broker
SET @Cnt = 0

SELECT @Cnt = COUNT(*)
 FROM dbo.BrokerLst_Process P
 INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
 WHERE ( PO.Cmplt = 1 OR PO.Services = 1 OR P.SOitem LIKE '%Equipment%' )
  AND P.Process_ID = 'INCOMING';


IF @Cnt > 0
	BEGIN



	SELECT TOP 1 @POitem=ISNULL(P.PO_item,''), @Process_ID=ISNULL(P.Process_ID,'')
		, @SOitem=ISNULL(P.SOitem,''), @Company=ISNULL(PO.Company,'')
		, @nID_Detail = ISNULL(P.ID_Detail,0)
		, @nID_Detail_Process = ISNULL(P.ID_Detail_Process,0)
			FROM dbo.BrokerLst_Process P
			INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
			WHERE ( PO.Cmplt = 1 OR PO.Cancelled = 1 OR PO.Services = 1 OR P.SOitem like '%Equipment%' )
			 AND P.Process_ID = 'INCOMING'

	SELECT @Body = '@POitem '+@POitem+CHAR(13)
		+'@SOitem '+@SOitem+CHAR(13)+' '+dbo.f_HTML_link_SOitem(@SOitem)+CHAR(13)
		+'@Process_ID '+@Process_ID+CHAR(13)
		+'@Company '+@Company+CHAR(13)
		+'@ID_Detail '+CAST(@nID_Detail AS CHAR(10) )+CHAR(13)
		+'@ID_Detail_Process '+CAST(@nID_Detail_Process AS CHAR(10) )+CHAR(13)
		+CHAR(10)+CHAR(13)

	SELECT @Body = @Body+('SELECT P.*, ISNULL(R.Heat,'''') AS rHeat, PO.*'+CHAR(13)
		+' FROM dbo.BrokerLst_Process P'+CHAR(10)+CHAR(13)
 		+' INNER JOIN dbo.PurchaseOrder PO ON P.PO_item = PO.POitem '+CHAR(10)+CHAR(13)
 		+' LEFT OUTER JOIN dbo.Receiving R ON PO.POitem = R.POitem'+CHAR(10)+CHAR(13)
