ALTER PROCEDURE [dbo].[p_Maintenance_Process_Delivered]

AS

--EXEC p_Maintenance_Process_Delivered
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email();
DECLARE @Body varchar(4000);
DECLARE @Cnt INT = 0;
DECLARE @POitem CHAR(12) = '';

DECLARE @cProfile_Name VarChar(50);
SET @cProfile_Name = dbo.f_Get_profile_name('')

DECLARE @msg VARCHAR(250);
DECLARE @query varchar(2048);


SELECT @Cnt = COUNT(*) --SELECT *
 FROM dbo.StockLst_Process P
 INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
 WHERE ( PO.Delivered = 1 OR PO.Services = 1 OR P.SOitem LIKE '%Equipment%' )
  AND P.Process_ID = 'INCOMING'

IF @Cnt > 0
	BEGIN

	PRINT 'Delivered Stock with Process issue.';

	SELECT TOP 1 @POitem = ISNULL(PO.POitem,'')
	 FROM dbo.StockLst_Process P
	 INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem
	 WHERE ( PO.Delivered = 1 OR PO.Services = 1 OR P.SOitem LIKE '%Equipment%' )
	  AND P.Process_ID = 'INCOMING';
	

	SELECT @Body = dbo.f_Get_HTML_Header()+CHAR(13)
		+('SELECT P.* FROM dbo.StockLst_Process P'+CHAR(13)
		+' INNER JOIN dbo.PurchaseOrder PO ON p.PO_item = PO.POitem'+CHAR(13)
		+'WHERE ( PO.Delivered = 1 OR PO.Services = 1 OR P.SOitem LIKE ''%Equipment%'' ) '+CHAR(13)
		+' AND P.Process_ID = ''INCOMING'' '+CHAR(13)
		+' --PO was delivered and still Found a Stock Process Problem.'+CHAR(13)
		+' DELETED:'+ CAST(@Cnt AS CHAR(10))+'.'+CHAR(13)
