ALTER PROCEDURE [dbo].[p_Maintenance_Purchase]

AS

--EXEC dbo.p_Maintenance_Purchase
--ran from Maintenace Plans: ERP_1 Backup saturday

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email();
DECLARE @Body varchar(4000);
DECLARE @Cnt INT = 0;
DECLARE @PO INT = 0;

-----------------------------
-- PurchaeOrder with mixed Hold


SELECT @Cnt = COUNT(*)
--SELECT *
 FROM dbo.PurchaseOrder P
 WHERE P.Hold = 1
 AND ( P.Cmplt = 1 OR P.Cancelled = 1 )

IF @Cnt > 0
	BEGIN

	PRINT 'PurchaseOrder table has Hold mixed with Complete or Cancelled '

	SELECT TOP 1 @PO = P.HPApo
	 FROM dbo.PurchaseOrder P
		WHERE P.Hold = 1
		AND ( P.Cmplt = 1 OR P.Cancelled = 1 )
	 

	SELECT @Body = ('PurchaseOrder table has Hold mixed with Complete or Cancelled '+CHAR(10)+CHAR(13)
	+'SELECT P.Hold, P.Cmplt, P.Cancelled, *
	 FROM dbo.PurchaseOrder P
		WHERE P.Hold = 1
		AND ( P.Cmplt = 1 OR P.Cancelled = 1 )'+CHAR(13)+' '+CHAR(13)
	+'UPDATE dbo.PurchaseOrder 
		SET Hold = 0 
		WHERE Hold = 1
		AND ( Cmplt = 1 OR Cancelled = 1 )' +CHAR(13)+' '+CHAR(13)
	+' --Fixed  PurchaseOrder '+ CAST(@PO AS CHAR(10))+CHAR(13)+CHAR(13)
	+'Counted: '+ CAST(@Cnt AS CHAR(10))+'.'+CHAR(13)
	+' on '+RTRIM(GETDATE())+'. '
	+@@SERVERNAME+' Agent Job _ERP_1 weekly dbo.p_Maintenance_PurchaseOrder ' +CHAR(13)
	+' ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'PurchaseOrder Hold error',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'

	---------------------------------------------------	

	UPDATE dbo.PurchaseOrder 
		SET Hold = 0 
		WHERE Hold = 1
		AND ( Cmplt = 1 OR Cancelled = 1 )

	END
RETURN

