ALTER PROCEDURE [dbo].[p_Maintenance_Sales_Complete]

AS

--EXEC dbo.p_Maintenance_Sales_Complete
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

--p_Maintenance_Sales_Cancel check ALL tables for Cancel/Complete issues
--[p_Maintenance_Sales_Complete only checks dbo.Sales to dbo.Sales_No COMPLETE

--SET QUOTED_IDENTIFIER ON;
---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @cProfile_Name VarChar(50);
SET @cProfile_Name = dbo.f_Get_profile_name('')

--DECLARE @msg VARCHAR(250);
--DECLARE @query varchar(2048);

DECLARE @CntSO INT = 0

-----------------------------
-- Check for Sales_No is marked as Complete while Sales are not'

SELECT @CntSO = COUNT(*) 
--SELECT SN.cmplt,S.cmplt,S.Cncld,S.item,SN.itemtot,*
FROM dbo.Sales_No SN 
	INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
		WHERE ISNULL(SN.cmplt,0) = 1
		AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)

DECLARE @SalesNum INT = 0
DECLARE @ItemTot TinyInt = 0

IF @CntSO > 0
	BEGIN

	PRINT 'Sales_No is marked as Complete while Sales are not'
	
	SELECT TOP 1 @SalesNum = SN.SalesNum
		FROM dbo.Sales_No SN 
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
			WHERE ISNULL(SN.cmplt,0) = 1
			AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)

	SELECT @Body = ('-Sales_No is marked as Complete while Sales are not'+CHAR(13)+CHAR(13)
		+ 'SELECT SN.cmplt AS SNcmplt, S.cmplt AS Scmplt,PS.SOitem_cmplt AS PScmplt, SN.cncld AS SNcncld ,S.Cncld AS Scncld, PS.cancld AS PScancld,S.item,SN.itemtot,SN.SalesRep,* '+CHAR(13)
		+' FROM dbo.Sales_No SN '+CHAR(13)
		+' INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum '+CHAR(13)
		+'  INNER JOIN dbo.PackingSlip PS ON S.SOitem = PS.SOitem '+CHAR(13)
		+' WHERE ISNULL(SN.cmplt,0) = 1 AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)'+CHAR(13)
		+' ORDER BY SN.SalesNum DESC; '+CHAR(13)+CHAR(13)
		+' --Found a Completed Problem.'+CHAR(13)
		+' --Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)
		+'Updated: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13)
		+CHAR(13)+CHAR(13)+'ran this code.'+CHAR(13)
		+'	UPDATE dbo.Sales_No '+CHAR(13)
		+'SET cmplt = 0 '+CHAR(13)
		+'WHERE SalesNum IN ('+CHAR(13)
		+'  SELECT DISTINCT SN.SalesNum'+CHAR(13) 
		+'	FROM dbo.Sales_No SN'+CHAR(13)
		+'	INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum'+CHAR(13)
		+'		WHERE ISNULL(SN.cmplt,0) = 1'+CHAR(13)
		+'		AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)	)'+CHAR(13)
		+CHAR(13)+' on '+RTRIM(GETDATE() )  
		+@@SERVERNAME+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Sales_Complete ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Sales_No is marked as Complete while Sales are not ',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';

		UPDATE dbo.Sales_No SET cmplt = 0 
		WHERE SalesNum IN (
		  SELECT DISTINCT SN.SalesNum
		FROM dbo.Sales_No SN
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
		WHERE ISNULL(SN.cmplt,0) = 1
		AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)	);
			
	---------------------------------------------------	


	/*
	SET @msg = 'Sales_No is marked as Complete while Sales are not. ';  
		
	SET @query='SELECT SN.SalesNum, SN.ItemTot, S.item 
		,S.SOitem, SN.cmplt, S.cmplt, S.Cncld ,SN.SalesRep
	   FROM dbo.Sales_No SN 
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
		WHERE ISNULL(SN.cmplt,0) = 1
		AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0);'


	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_Sales_Complete'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_Sales_Complete.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;
	
	*/
	---------------------------------------------------	
	/*
	UPDATE dbo.Sales_No 
		SET cmplt = 0 
		WHERE SalesNum IN (
		  SELECT DISTINCT SN.SalesNum 
			FROM dbo.Sales_No SN
			INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
				WHERE ISNULL(SN.cmplt,0) = 1
				AND (ISNULL(S.cmplt,0) = 0 AND ISNULL(S.Cncld,0) = 0)
			)
	*/

	END

-----------------------------
-- Check for Sales_No is NOT marked as Complete while ALL Sales are Complete'

SELECT @CntSO = COUNT(*) 
--SELECT SN.SalesNum,  SN.ItemTot ,COUNT( CASE WHEN ISNULL(S.cmplt,0)=1 OR ISNULL(S.cncld,0)=1 THEN 1 ELSE 0 END ) AS Counted
FROM dbo.Sales_No SN 
	INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
		WHERE ISNULL(SN.cmplt,0) = 0
		GROUP BY SN.SalesNum,  SN.ItemTot
		HAVING COUNT( CASE WHEN ISNULL(S.cmplt,0)=1 OR ISNULL(S.cncld,0)=1 THEN 1 ELSE 0 END ) 
				<> SN.ItemTot


IF @CntSO > 0
	BEGIN

	PRINT 'Sales_No is marked as NOT Complete while ALL Sales are '

	--DECLARE @SalesNum INT = 0

	SELECT TOP 1 @SalesNum = SN.SalesNum, @ItemTot = SN.itemtot
		FROM dbo.Sales_No SN 
		INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum
			WHERE ISNULL(SN.cmplt,0) = 0
			GROUP BY SN.SalesNum,  SN.ItemTot
			HAVING COUNT( CASE WHEN ISNULL(S.cmplt,0)=1 OR ISNULL(S.cncld,0)=1 THEN 1 ELSE 0 END ) 
				<> SN.ItemTot

	SELECT @Body = ( '--Sales_No is marked as NOT Complete while ALL Sales are '+char(13)+char(13)
	    +'SELECT SN.SalesNum,  SN.ItemTot '+CHAR(13)
		+',SN.cmplt,S.cmplt,SN.cncld,S.Cncld,S.item,SN.itemtot,SN.SalesRep '+CHAR(13)
 		+'FROM dbo.Sales_No SN '+CHAR(13)
 		+'INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum  '+CHAR(13)
		+'WHERE SN.salesnum IN '+CHAR(13)
		+'( SELECT SN.SalesNum FROM dbo.Sales_No SN '+CHAR(13)
 		+'INNER JOIN dbo.Sales S ON SN.SalesNum = S.SalesNum  '+CHAR(13)
		+'WHERE ISNULL(SN.cmplt,0) = 0  '+CHAR(13)
		+'GROUP BY SN.SalesNum,  SN.ItemTot  '+CHAR(13)
		+'HAVING COUNT( CASE WHEN ISNULL(S.cmplt,0)=1 OR ISNULL(S.cncld,0)=1 THEN 1 ELSE 0 END ) 	<> SN.ItemTot )'+CHAR(13)
		+' ORDER BY SN.SalesNum DESC; '+CHAR(13)+CHAR(13)
