ALTER PROCEDURE [dbo].[p_Maintenance_Sales_No_Quotes]

AS

--EXEC dbo.p_Maintenance_Sales_No_Quotes
--ran from Maintenace Plans: ERP_1 Backup saturday

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0
DECLARE @cProfile_Name VarChar(50);

--DECLARE @msg VARCHAR(250) = 'Please refer to the attached spread sheet for the report.';  
--DECLARE @query varchar(2048);

-----------------------------
-- SalesNum in Sales_No and not Quotes Problem.


SELECT @CntSO = COUNT(*)
--SELECT * --COUNT(*)
 FROM dbo.Sales_No SN 
 LEFT OUTER JOIN dbo.AllQuotes AQ ON SN.salesnum = AQ.salesnum
 WHERE ISNULL(AQ.SalesNum,-1) = -1  
 AND SN.SalesNum > 100000
 AND ISNULL(SN.cncld,0) = 0;

IF @CntSO > 0
	BEGIN
	
	PRINT 'Found a Problem in Sales_No. No matching Quote';

	DECLARE @SalesNum INT = 0

	SELECT TOP 1 @SalesNum = SN.SalesNum
		FROM dbo.Sales_No SN 
		LEFT OUTER JOIN dbo.AllQuotes AQ ON SN.salesnum = AQ.salesnum
		WHERE ISNULL(AQ.SalesNum,-1) = -1  
		AND SN.SalesNum > 100000
		AND ISNULL(SN.cncld,0) = 0;

	SELECT @Body = ('USE ERP_1;'+CHAR(13)+' SELECT  AQ.SOitem AS [AQ],S.SOitem AS [S],SN.SalesNum, SN.ItemTot '+CHAR(13)
	 +',SN.SalesRep,SN.CreateDate'+CHAR(13)
	 +' FROM dbo.Sales_No SN '+CHAR(13)
	 +' LEFT OUTER JOIN dbo.AllQuotes AQ ON SN.salesnum = AQ.salesnum '+CHAR(13)
	 +' LEFT OUTER JOIN dbo.Sales S ON SN.salesnum = S.SalesNum '+CHAR(13)
	 +' WHERE ISNULL(AQ.SalesNum,-1) = -1'+CHAR(13)
	 +' AND SN.SalesNum > 100000'+CHAR(13)
	 +' AND ISNULL(SN.cncld,0) = 0;'+CHAR(13)
	 +' --Fixed Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+' Set as Cancel'+CHAR(13)+CHAR(13)
	 +' --not found in AllQuotes.'+CHAR(13)
	 +' Counted: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '
	 +@@SERVERNAME+'.  in dbo.p_Maintenance_Sales_No_Quotes ' );
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'SO in Sales_No is missing in Quotes.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT';
	
	
		--begin transaction
		 UPDATE dbo.Sales_No SET cncld=1 
		 FROM dbo.Sales_No SN 
		 LEFT OUTER JOIN dbo.AllQuotes AQ ON SN.salesnum = AQ.salesnum
		 WHERE ISNULL(AQ.SalesNum,-1) = -1  
		 AND SN.SalesNum > 100000
		 AND ISNULL(SN.cncld,0) = 0;
		 --commit;
	
	END



RETURN

