ALTER PROCEDURE [dbo].[p_Maintenance_Sales_No_Ver]

AS

--EXEC dbo.p_Maintenance_Sales_No_Ver
--ran from Maintenace Plans: ERP_1 Backup saturday
--Should rename to Weekly Maintance

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

DECLARE @CntSO INT = 0
DECLARE @SalesNum INT = 0

SELECT @CntSO = COUNT(*)
	FROM dbo.Sales_No SN 
	WHERE SN.cncld = 0 
	AND SN.cmplt = 0
	AND ( ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev  WHERE SalesNum = SN.salesnum ) ,0)
		OR ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX([Ver]) FROM dbo.Sales_No_Chng WHERE SalesNum = SN.salesnum  ) ,ISNULL(SN.Amendment,0)) ); 

/*
	SELECT  SN.SalesNum
	, MAX(SN.Amendment) AS Amendment, MAX(SNR.VER) AS Ver 
	FROM dbo.Sales_No SN WITH(NOLOCK) 
	INNER JOIN dbo.Sales_No_Rev SNR WITH(NOLOCK) ON SN.salesnum = SNR.SalesNum
	GROUP BY SN.SalesNum
	HAVING MAX(SNR.VER) <> MAX(SN.amendment)

*/

IF @CntSO > 0
	BEGIN

	PRINT 'Sales Ver Mismatch ';
	
	SELECT TOP 1 @SalesNum = SN.SalesNum
		FROM dbo.Sales_No SN 
		WHERE SN.cncld = 0 
		AND SN.cmplt = 0
		AND ( ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev  WHERE SalesNum = SN.salesnum ) ,0)
			OR ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX([Ver]) FROM dbo.Sales_No_Chng WHERE SalesNum = SN.salesnum  ) ,ISNULL(SN.Amendment,0)) ); 



	SELECT @Body = ('Sales Ver Mismatch '+CHAR(13)
	 +' Counted: '+CAST(@CntSO AS CHAR(10))+CHAR(13)
	 +'begin transaction;'+CHAR(13)
	+'--INSERT INTO dbo.Sales_No_Rev (SalesNum,Ver,Comment)'+CHAR(13)
	+'SELECT DISTINCT SN.SalesNum, SN.amendment, ''VER updated to match Sales_No.Amendment'' AS Comment'+CHAR(13)
	+',ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev  WHERE SalesNum = SN.salesnum ) ,0) AS S_N_Rev '+CHAR(13)
	+',ISNULL((SELECT MAX([Ver]) FROM dbo.Sales_No_Chng WHERE SalesNum = SN.salesnum  ),0) AS S_N_Chng '+CHAR(13)
	+'FROM dbo.Sales_No SN '+CHAR(13)
	+'WHERE SN.cncld = 0 AND SN.cmplt = 0 '+CHAR(13)
	+'	AND ( ISNULL(SN.Amendment,0) <> ISNULL((SELECT MAX(VER) FROM dbo.Sales_No_Rev  WHERE SalesNum = SN.salesnum ) ,0)'+CHAR(13)
