ALTER PROCEDURE [dbo].[p_Maintenance_Sales_NoAddr]

AS

--EXEC dbo.p_Maintenance_Sales_NoAddr
--EXEC dbo.p_Maintenance_Weekly p_Maintenance_Daily
--ran from Maintenace Plans: ERP_1 Backup saturday

--SET QUOTED_IDENTIFIER ON;
---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000);

DECLARE @cProfile_Name VarChar(50);
SET @cProfile_Name = dbo.f_Get_profile_name('')

--DECLARE @msg VARCHAR(250);
--DECLARE @query varchar(2048);

DECLARE @CntSO INT = 0;
DECLARE @SalesNum INT = 0;

-----------------------------
-- Check for Sales_No has no Addr and is not marked as Complete or Cancelled'

--SELECT * FROM dbo.Sales_No WHERE pSoldAddr = 0 AND Cmplt = 0 AND Cncld = 0
SELECT @CntSO = COUNT(*) 
FROM dbo.Sales_No SN 
	WHERE ISNULL(SN.cmplt,0) = 0 AND ISNULL(SN.cncld,0) = 0
	AND ( ISNULL(pSoldAddr,0) = 0 or ISNULL(pShipAddr,0) = 0 )
	AND dbo.f_Is_SO_OnHold(SN.salesnum) = 0


--UPDATE  dbo.Sales_No SET Cmplt = 1 WHERE SalesNum = 91807
IF @CntSO > 0
	BEGIN

	PRINT 'Sales_No Without Address'

	SELECT TOP 1 @SalesNum = SN.SalesNum
		FROM dbo.Sales_No SN 
		WHERE ISNULL(SN.cmplt,0) = 0 AND ISNULL(SN.cncld,0) = 0
		AND ( ISNULL(pSoldAddr,0) = 0 or ISNULL(pShipAddr,0) = 0 )
		AND dbo.f_Is_SO_OnHold(SN.salesnum) = 0;

/*  --The next email is better, just skip this one.
	SELECT @Body = ('SELECT SN.SalesNum,SN.cmplt,SN.Cncld,SN.itemtot,SN.SalesRep,SN.pSoldAddr,SN.pShipAddr,SN.ShipRoute,SN.ShopRecv '+CHAR(13)
		+' FROM dbo.Sales_No SN '+CHAR(13)
		
		+' WHERE ISNULL(SN.cmplt,0) = 1 AND ISNULL(SN.cncld,0) = 0 '+CHAR(13)
		+' AND (ISNULL(SN.pSoldAddr,0) = 0 or ISNULL(SN.pShipAddr,0) = 0)'+CHAR(13)
		+' AND NOT dbo.f_Is_SO_OnHold(SN.salesnum) '+CHAR(13)
		+' ORDER BY SN.SalesNum DESC; '+CHAR(13)+CHAR(13)
		+' --Found a No-Address Problem.'+CHAR(13)
		+'SELECT * FROM dbo.NR_UserTrack WHERE Mess1 LIKE ''Sales_No data for SO:%'' AND Mess1 like ''%SN.SalesNum%'' '+CHAR(13)+CHAR(13)

		+@@SERVERNAME+' Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Sales_NoAddr ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Sales_No without Address',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'
			
	---------------------------------------------------	
*/
/*

	SET @msg = 'Sales_No with no Address. ';  
		
	SET @query='SELECT SN.cmplt,SN.Cncld,SN.itemtot,SN.SalesRep,SN.pSoldAddr,SN.pShipAddr,SN.ShipRoute,SN.ShopRecv 
		FROM dbo.Sales_No SN 
		WHERE ISNULL(SN.cmplt,0) = 1 AND ISNULL(SN.cncld,0) = 0 
		AND (SN.pSoldAddr = 0 or SN.pShipAddr = 0);'
		
	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_Sales_NoAddr'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_Sales_NoAddr.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;

*/

	---------------------------------------------------	
	--Loop thru and Send an Email to all Sales Reps

	DECLARE @cncld bit, @cmplt bit, @PrintedSO bit, @ShopRecv bit

	DECLARE @MaxIterator INT, @Iterator INT  
	DECLARE @SalesPemail VARCHAR(100) = ''
	DECLARE @SalesRep CHAR(20) = ''
	DECLARE @cSaleDate CHAR(10) = ''
	DECLARE @cDueDate CHAR(10) = ''
	
	CREATE TABLE #TallyTable ( Iterator INT IDENTITY(1, 1), SalesNum INT, SalesRep CHAR(20), ShopRecv Bit );
   
	INSERT INTO #TallyTable ( SalesNum, SalesRep )
	SELECT DISTINCT SN.salesnum, SN.salesrep	
		FROM dbo.Sales_No SN 
		WHERE ISNULL(SN.cmplt,0) = 0 AND ISNULL(SN.cncld,0) = 0
		AND ( ISNULL(SN.pSoldAddr,0) = 0 or ISNULL(SN.pShipAddr,0) = 0 )
		AND dbo.f_Is_SO_OnHold(SN.salesnum) = 0

	SELECT @MaxIterator = MAX(Iterator), @Iterator = 1
		FROM   #TallyTable;
 
	SELECT @SalesNum = SalesNum
		, @SalesRep = SalesRep
		FROM   #TallyTable
		WHERE  Iterator = @Iterator;
 
	BEGIN TRY
		WHILE @Iterator <= @MaxIterator 
		BEGIN 
		IF @SalesNum > 0 
			begin
			print 'SalesNum '+CAST( @SalesNum AS CHAR(10))+', Itr '+CAST(@Iterator AS CHAR(10))

			SET @SalesPemail = dbo.f_SaleRep_Email_SO(@SalesNum)
			PRINT @SalesPemail
			--SET @SalesPemail = @SalesPemail+';David.Kirchner@ERP_1s.com'

			SELECT TOP 1 @cSaleDate = CONVERT(CHAR(10), AllQuotes.SaleDate, 101) 
				FROM dbo.AllQuotes 
				INNER JOIN dbo.Sales S ON AllQuotes.SOitem = S.SOitem
				WHERE AllQuotes.SalesNum = @SalesNum
				AND ISNULL(S.cmplt,0) = 0 AND ISNULL(S.cncld,0) = 0

			SELECT TOP 1 @cDueDate = CONVERT(CHAR(10), S.ShipDue, 101) 
				--,cncld ,cmplt ,ShipOn ,Hold
				FROM dbo.Sales S 
				WHERE S.SalesNum = @SalesNum
				AND ISNULL(S.cmplt,0) = 0 AND ISNULL(S.cncld,0) = 0
			
				
			SELECT @cncld = cncld, @cmplt = cmplt, @PrintedSO = PrintedSO, @ShopRecv = ShopRecv
				FROM dbo.Sales_No WHERE SalesNum = @SalesNum

--			SET @msg = 'p_Maintenance_Daily overnite found Sales_No '+TRIM(CAST(@SalesNum AS CHAR(10)))+' has no Address. '+CHAR(10);  
--			SET @msg = @msg + TRIM(@SalesRep)+', this is your reminder to enter the Address!'+CHAR(10);
--			SET @msg = @msg + '</br >'+dbo.f_HTML_link_SO(@SalesNum) + '</br >'
		
			
	
			SET @Body = '<!DOCTYPE html> <html><head><title>HPA Notice</title></head><body>'

			SET @Body = @Body + '<p>p_Maintenance_Daily overnite found Sales_No '+TRIM(CAST(@SalesNum AS CHAR(10)))+' has no Address. </p></br>'
			SET @Body = @Body + '<p> '+TRIM(@SalesRep)+', this is your reminder to enter the Address!</p></br>'
			SET @Body = @Body + '<p> or do you need to Cancel this SO!</p>'
			SET @Body = @Body + '<p>'+dbo.f_HTML_link_SO(@SalesNum) + '</p></br>'
			SET @Body = @Body + '<p>'+dbo.f_get_Order_Description('SO',@SalesNum,'') + '</p></br>'

			SET @Body = @Body + '<p>'+'Sale Date '+@cSaleDate+' -  Ship Due '+ @cDueDate + '</p>'
			SET @Body = @Body +'</br>'

			IF @cncld = 1
				SET @Body = @Body +'-Cancelled '

			IF @cmplt = 1
				SET @Body = @Body +'-Completed '

			IF @PrintedSO = 1
				SET @Body = @Body +'-SO is Printed '
			ELSE
				SET @Body = @Body +'-SO is NOT Printed '

			IF @ShopRecv = 1
				SET @Body = @Body +'-Shop has received the SO '
			ELSE
				SET @Body = @Body +'-Shop has NOT received the SO '

			SET @Body = @Body +'<p>'+ SUSER_SNAME()+' on '+RTRIM(CAST(GETDATE()AS CHAR))+'</p>'
			SET @Body = @Body +'<p>'+@@SERVERNAME+ ' dbo.p_Maintenance_Sales_NoAddr '+'</p></br>'
		
			SET @Body = @Body +'</body></html>'
		
			EXEC dbo.p_eMail_Send
				 @FromEmail = @SalesPemail
				,@ToEmail = @SalesPemail
				,@SubjectEmail = 'Sales Order without Address'
				,@BodyEmail = @Body
				,@BodyType = 'HTML';

			/*
			EXEC dbo.p_eMail_Send
				 @FromEmail = @SalesPemail
				,@ToEmail = 'David.Kirchner@ERP_1s.com'
				,@SubjectEmail = 'Sales Order without Address -Davids Copy'
				,@BodyEmail = @Body
				,@BodyType = 'HTML' 
			*/
			end
		
		SET @Iterator = @Iterator +1;
 
		SELECT @SalesNum = SalesNum
	  		, @SalesRep = SalesRep
			FROM   #TallyTable
			WHERE  Iterator = @Iterator;
	
		SET @SalesPemail = dbo.f_SaleRep_Email_SO(@SalesNum);
		Print 'Next Itr '+CAST(@Iterator AS CHAR(10))

		END; 
 
	END TRY
 
	BEGIN CATCH
	SELECT ERROR_NUMBER() AS ErrorNumber ,
		   ERROR_MESSAGE() AS ErrorMessage;
	END CATCH;
 
	DROP TABLE #TallyTable

	---------------------------------------------------	
	end
RETURN


