ALTER PROCEDURE [dbo].[p_Maintenance_Sales_Summary]

AS

--EXEC dbo.p_Maintenance_Sales_Summary
--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday

--SELECT * FROM dbo.NR_Sales_Summary WHERE Shipped >= CAST(GETDATE()-31 AS DATE)
--SELECT COUNT(*) FROM dbo.NR_Sales_Summary WHERE Year(Shipped)=Year(GetDate()) 

--SET QUOTED_IDENTIFIER ON;

DECLARE @DateLastYear AS Date
SET @DateLastYear = GETDATE()-365

PRINT 'p_Maintenance_Sales_Summary  -Remove 365 days and ReAdd to Summary'
PRINT 'Remove summary for SOitem that we will now add!'

DELETE FROM dbo.NR_Sales_Summary
	WHERE SOitem IN
	(SELECT Sales.SOitem 
		FROM ERP_1.dbo.Sales
			WHERE LEN(Sales.SOitem) > 0
				AND Sales.shipped >= @DateLastYear )

PRINT 'Remove summary for cancelled SO.'
DELETE FROM dbo.NR_Sales_Summary
	WHERE SOitem IN
	(SELECT Sales.soitem 
		FROM ERP_1.dbo.Sales
			WHERE LEN(Sales.SOitem) > 0
				AND ISNULL(Sales.Cncld,0) = 1
				AND Sales.shipped >= @DateLastYear )

PRINT 'Add summary of 365 days of Sales -without- Sz2.'
INSERT INTO dbo.NR_Sales_Summary
([Shipped],[Mnth],[Qtr],[Year],[Alloy],[form],[CC],[CL],[Size],[Sz2],[Pc],[MatlWt],[MatlFt]
,[Typ],[ItemCost],[ItemSales],[SOitem],[Q_P],[Q_QTY]
,[fPS_QTY],[fRMA_QTY],[fInv_QTY],[fPS_total],[fInv_Cost],[fSORecv_Total] )
SELECT 	Sales.shipped
	,Month(Sales.shipped) AS Mnth
	,CASE WHEN Month(Sales.shipped) < 4 THEN 1 WHEN Month(Sales.shipped) < 7 THEN 2 WHEN Month(Sales.shipped) < 10 THEN 3 ELSE 4 END AS Qtr
	,Year(Sales.shipped) AS Yr
	,Allquotes.Alloy, Allquotes.form, dbo.f_CC_ESR(Allquotes.CC) AS CC, Allquotes.CL
	,ERP_1.dbo.f_SizeStandard(Allquotes.Thck) AS Size
	,0 AS Sz2
	,( CASE ERP_1.dbo.f_GetFormPU(Allquotes.Form) WHEN 3 THEN Allquotes.Pieces ELSE 0 END ) As Pc
	,Sales.MatlWt
	,ERP_1.dbo.f_Est_Ft(Sales.MatlWt,Allquotes.Form,Allquotes.Thck,Allquotes.Alloy,Allquotes.Sz2,Allquotes.Pieces) AS MatlFt
	,Sales.Typ
	,Sales.ItemCost
	,sales.ItemSale
--	,Sales.gs_cost,Sales.gs_sale,Sales.gs_cmplt
	,Sales.SOitem
	,AllQuotes.Q_P
	,AllQuotes.Q_QTY
	
	,dbo.fvSales_PS_QTY(Sales.SOitem) AS fPS_QTY
	,dbo.fvSales_RMA_QTY(Sales.SOitem) AS fRMA_QTY
	,dbo.fvSales_Grab_QTY(Sales.SOitem) AS fInv_QTY
	,dbo.fvSales_PS_Total(Sales.SOitem) AS fPS_total
	,dbo.fvSales_Grab_Total(Sales.SOitem) AS fInv_Cost
	,dbo.fvSales_SORecv(Sales.SOitem) AS fSORecv_Total
FROM dbo.Sales LEFT OUTER JOIN dbo.AllQuotes ON Sales.SOitem = Allquotes.SOitem 
	WHERE LEN(Sales.SOitem) > 0
	AND ISNULL(Sales.Cmplt,0) = 1
	AND ISNULL(Sales.Cncld,0) = 0
	AND ISNULL(Sales.IntP,0) = 0
	AND ISNULL(AllQuotes.[Services],0) = 0
	AND Sales.shipped >= @DateLastYear
	AND dbo.f_GetForm_StockBySZ2(AllQuotes.Form) = 0
	AND LEN(AllQuotes.Alloy)>0

PRINT 'Add summary of 365 days of Sales with Sz2.'
INSERT INTO dbo.NR_Sales_summary
([Shipped],[Mnth],[Qtr],[Year],[Alloy],[form],[CC],[CL],[Size],[Sz2],[Pc],[MatlWt],[MatlFt]
,[Typ],[ItemCost],[ItemSales],[SOitem],[Q_P],[Q_QTY]
,[fPS_QTY],[fRMA_QTY],[fInv_QTY],[fPS_total],[fInv_Cost],[fSORecv_Total] )
SELECT 	Sales.shipped
	,Month(Sales.shipped) AS Mnth
	,CASE WHEN Month(Sales.shipped) < 4 THEN 1 WHEN Month(Sales.shipped) < 7 THEN 2 WHEN Month(Sales.shipped) < 10 THEN 3 ELSE 4 END AS Qtr
	,Year(Sales.shipped) AS Yr
	,Allquotes.Alloy, Allquotes.Form, dbo.f_CC_ESR(Allquotes.CC) AS CC, Allquotes.CL
	,ERP_1.dbo.f_SizeStandard(Allquotes.Thck) AS Size
	,AllQuotes.Sz2
	,( CASE ERP_1.dbo.f_GetFormPU(Allquotes.Form) WHEN 3 THEN Allquotes.Pieces ELSE 0 END ) As Pc
	,Sales.MatlWt
	,ERP_1.dbo.f_Est_Ft(Sales.MatlWt,Allquotes.Form,Allquotes.Thck,Allquotes.Alloy,Allquotes.Sz2,Allquotes.Pieces) AS MatlFt
	,Sales.Typ
	,Sales.ItemCost
	,sales.ItemSale
--	,Sales.gs_cost,Sales.gs_sale,Sales.gs_cmplt
	,Sales.SOitem
	,AllQuotes.Q_P
	,AllQuotes.Q_QTY

	,dbo.fvSales_PS_QTY(Sales.SOitem) AS fPS_QTY
	,dbo.fvSales_RMA_QTY(Sales.SOitem) AS fRMA_QTY
	,dbo.fvSales_Grab_QTY(Sales.SOitem) AS fInv_QTY
	,dbo.fvSales_PS_Total(Sales.SOitem) AS fPS_total
	,dbo.fvSales_Grab_Total(Sales.SOitem) AS fInv_Cost
	,dbo.fvSales_PORecv(Sales.SOitem) AS fSORecv_Total
FROM dbo.Sales LEFT OUTER JOIN dbo.AllQuotes ON Sales.SOitem = Allquotes.SOitem 
	WHERE LEN(Sales.SOitem) > 0
	AND ISNULL(Sales.Cmplt,0) = 1
	AND ISNULL(Sales.Cncld,0) = 0
	AND ISNULL(Sales.IntP,0) = 0
	AND ISNULL(AllQuotes.[Services],0) = 0
	AND Sales.shipped >= @DateLastYear
	AND dbo.f_GetForm_StockBySZ2(AllQuotes.Form) = 1
	AND LEN(AllQuotes.Alloy)>0



RETURN


