	 +' --Fix  Sales SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)+CHAR(13)
	 +' --Fix AllQuotes, the Sales SalesNum not found in AllQuotes. Counted: '+ CAST(@CntSO AS CHAR(10))+'.'+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '
	 +@@SERVERNAME+'.  in dbo.p_Maintenance_SalesNum_Quotes ' );
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
