ALTER PROCEDURE [dbo].[p_Maintenance_StockLst_Process]

AS

--EXEC dbo.p_Maintenance_StockLst_Process
--ran from Maintenace Plans: ERP_1 Backup saturday

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email();
DECLARE @Body varchar(4000);
DECLARE @Cnt INT = 0;
DECLARE @ID_Detail INT = 0;

-----------------------------
-- StockLst Process without Detail.


SELECT @Cnt = COUNT(*)
--SELECT *
 FROM dbo.StockLst_Process 
 WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )

IF @Cnt > 0
	BEGIN

	PRINT 'StockLst_Process without StockLst_Detail '

	SELECT TOP 1 @ID_Detail = ID_Detail
	 FROM dbo.StockLst_Process 
	 WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )

	SELECT @Body = ('StockLst_Process without StockLst_Detail '+CHAR(13)
	+'SELECT * FROM dbo.StockLst_Process '+CHAR(13)
	+'WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )'+CHAR(13)
	+' --Fix  StockLst_Detail ID_Detail '+ CAST(@ID_Detail AS CHAR(10))+CHAR(13)+CHAR(13)
	+'Counted: '+ CAST(@Cnt AS CHAR(10))+'.'+CHAR(13)
	+' on '+RTRIM(GETDATE())+'. '
	+@@SERVERNAME+' Agent Job _ERP_1  weekly dbo.p_Maintenance_StockLst_Process ' +CHAR(13)
	+' Delete dbo.StockLst_Process without StockLst_Detail ' )
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'StockLst_Process without StockLst_Detail.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'

	---------------------------------------------------	
	/*
	DECLARE @cProfile_Name VarChar(50);
	SET @cProfile_Name = dbo.f_Get_profile_name('')

	DECLARE @msg VARCHAR(250);
	SET @msg = 'Please refer to the attached spread sheet for the report.'
		+CHAR(13)+'StockLst_Process without StockLst_Detail.';  

	DECLARE @query varchar(2048);
	SET @query='SELECT *
		FROM dbo.StockLst_Process 
		WHERE ID_Detail NOT IN 
		(SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail );';


	EXEC msdb.dbo.sp_send_dbmail
		@profile_name = @cProfile_Name
		, @recipients = 'David.Kirchner@ERP_1s.com'
		, @subject = 'p_Maintenance_StockLst_Process'
		, @body= @msg
		, @body_format = 'TEXT'
		, @query = @query
		, @execute_query_database = 'ERP_1'  
		, @attach_query_result_as_file = 1
		, @query_attachment_filename='p_Maintenance_StockLst_Process.csv'
		, @query_result_header = 1
		, @query_result_width = 400
		, @query_result_separator = ','
		, @exclude_query_output = 0
		, @append_query_error = 1
		, @query_no_truncate = 0
		, @query_result_no_padding = 0;
	*/

	------------------------
	
	DECLARE @POitem CHAR(12), @SOitem CHAR(12), @Process_ID CHAR(10), @WO INT, @WO_Detail INT
		

	SELECT TOP 1 @POitem=ISNULL(P.PO_item,''), @Process_ID=ISNULL(P.Process_ID,'')
		,@SOitem=ISNULL(P.SOitem,''), @WO=ISNULL(P.WO,0), @WO_Detail=ISNULL(P.WO_Detail,0)
		,@ID_Detail = P.ID_Detail
		FROM dbo.StockLst_Process P
		WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )



	SELECT @Body = '@ID_Detail '+CAST(@ID_Detail AS CHAR(10))+CHAR(13)
		+'@POitem '+@POitem+CHAR(13)
		+'@SOitem '+@SOitem+CHAR(13)
		+'@Process_ID '+CAST(@Process_ID AS CHAR(10))+CHAR(13)
		+'@WO '+CAST(@WO AS CHAR(10))+CHAR(13)	
		+'@WO_Detail '+CAST(@WO_Detail AS CHAR(10))+CHAR(13)
		+CHAR(13)

	SELECT @Body = @Body+('SELECT P.*'+CHAR(13)
		+' FROM dbo.StockLst_Process P'+CHAR(13)
		+' WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )'+CHAR(13)
		+' --ID_Detail for this Process is gone.'+CHAR(13) );

	IF dbo.f_ProperPOitem(@POitem) <> dbo.f_ProperPOitem('')
		SET @Body = @Body +'top POitem: '+@POitem+'. '+dbo.f_HTML_link_POitem(@POitem)+' '+CHAR(13);
		
	SET @Body = @Body +' DELETED:'+ CAST(@Cnt AS CHAR(10))+'.'+CHAR(13)
		+' on '+RTRIM(GETDATE())  
		+@@SERVERNAME+' Agent Job _ERP_1  weekly dbo.p_Maintenance_StockLst_Process ' 
		

		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Deleted Stock Process for Missing Stock Detail.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'


	---------------------------------------------------	
	DELETE
		FROM dbo.StockLst_Process 
		WHERE ID_Detail NOT IN (SELECT DISTINCT ID_Detail FROM dbo.Stocklst_Detail )

	END

--Process_ID='QUOTED' 
SELECT @Cnt = COUNT(*) 
--SELECT *
 FROM dbo.StockLst_Process 
 WHERE Process_ID='QUOTED' AND StartDate < GETDATE()-7
 

IF @Cnt > 0
	BEGIN

	PRINT 'StockLst_Process with Quoted Process_ID '
	
	SELECT @Body = ('StockLst_Process with Quoted Process_ID '+CHAR(13)+' '+CHAR(13)
	+'SELECT * FROM dbo.StockLst_Process '+CHAR(13)
	+'WHERE Process_ID=''QUOTED'' AND StartDate < GETDATE()-7)'+CHAR(13)
	+' '+CHAR(10)+' '+CHAR(13)
	+'Deleted: '+ CAST(@Cnt AS CHAR(10))+' as ''Quoted''.'+CHAR(13)
	+' on '+RTRIM(GETDATE())+'. '+CHAR(13)
	+@@SERVERNAME+' Agent Job _ERP_1  weekly dbo.p_Maintenance_StockLst_Process ' +CHAR(13)
	+'Delete StockLst_Process with Quoted Process_ID')


		EXEC dbo.p_eMail_Send
			@FromEmail = @cEmailFrom, 
			@ToEmail = 'David.Kirchner@ERP_1s.com', 
			@SubjectEmail = 'Process with Quoted Process_ID being used by Sales.',
			@BodyEmail = @Body,
			@BodyType = 'TEXT'
			;
	---------------------------------------------------	
	DELETE 
		FROM dbo.StockLst_Process 
		WHERE Process_ID='QUOTED' AND StartDate < GETDATE()-7;

	END

RETURN

