ALTER PROCEDURE [dbo].[p_Maintenance_Weekly]

AS

--EXEC dbo.p_Maintenance_Weekly
--ran from Maintenace Plans: ERP_1 Backup saturday
--'SQL Server Agent \ Jobs \ _ERP_1 Weekly '
---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)

PRINT 'p_Maintenance_Weekly';

SELECT @Body = ('EXEC dbo.p_Maintenance_Weekly '
	+CHAR(10)+CHAR(13)+'started on '+RTRIM(GETDATE())+'. '
	 +@@SERVERNAME+'. Agent Job _ERP_1 Summarize Sales weekly ERP_1 ' );
		

DECLARE @RaptorDate DateTime
DECLARE @PeregrineDate DateTime
DECLARE @Days	tinyInt = 0

SELECT
@RaptorDate = (SELECT MAX(RAQ.InqDate) FROM dbo.AllQuotes RAQ) 
,@PeregrineDate = (SELECT MAX(PAQ.InqDate) FROM dbo.AllQuotes PAQ)
,@Days = (SELECT DateDiff(day,
(SELECT MAX(PAQ.InqDate) FROM dbo.AllQuotes PAQ) 
,(SELECT MAX(RAQ.InqDate) FROM dbo.AllQuotes RAQ) ) )

SET @Body = @Body +CHAR(10)+CHAR(13)
SET @Body = @Body + '    @RaptorDate: '+CAST(@RaptorDate AS CHAR) +CHAR(10)+CHAR(13)
SET @Body = @Body + '@PeregrineDate: '+CAST(@PeregrineDate AS CHAR)+CHAR(10)+CHAR(13)
SET @Body = @Body + ' @Days: '+CAST(@Days AS CHAR) +CHAR(10)+CHAR(13)

EXEC dbo.p_eMail_Send
	@FromEmail = @cEmailFrom, 
	@ToEmail = 'David.Kirchner@ERP_1s.com', 
	@SubjectEmail = 'p_Maintenance_Weekly.',
	@BodyEmail = @Body,
	@BodyType = 'TEXT';


------------------------------------------------------------------------

EXEC dbo.p_Maintenance_Sales_Summary;

EXEC dbo.p_Maintenance_Sales_ItemTot;
EXEC dbo.p_Maintenance_Sales_Complete;
EXEC dbo.p_Maintenance_Sales_Cancel;
EXEC dbo.p_Maintenance_Sales_Hold;

EXEC dbo.p_Maintenance_StockLst_Process;
EXEC dbo.p_Maintenance_StockLst_Detail;  --Now in Maintenance Process Raptor report

EXEC dbo.p_Maintenance_BrokerLst_Process;
EXEC dbo.p_Maintenance_BrokerLst_Detail;

EXEC dbo.p_Maintenance_Process_Complete;
EXEC dbo.p_Maintenance_Process_Cancel;

--EXEC dbo.p_Maintenance_Process_Delivered;

EXEC dbo.p_Maintenance_Failed_Email;

EXEC dbo.p_Maintenance_Sales_Quotes;

--EXEC dbo.p_Maintenance_Sales_No_Quotes;
EXEC dbo.p_Maintenance_SalesNum_Quotes;

EXEC dbo.p_Maintenance_Sales_No_Ver;


PRINT 'EXEC dbo.p_Maintenance_Sales_OnHold'
EXEC dbo.p_Maintenance_Sales_OnHold @Whn='Weekly';

EXEC ERP_1.[dbo].[p_Maintenance_New_ShipAddr];

RETURN

