SET NOCOUNT ON

DECLARE @err INT,
        @RC INT

SET @err = 0
SET @RC = 0

DECLARE @Count INT


SELECT @Count = COUNT(*) FROM dbo.StockLst_Process WHERE SOitem = @SOitem
IF @Count > 0
  BEGIN
    INSERT dbo.Ar.StockLst_Process_History 
		([soitem],[po_item],[SalesPerson],[startdate],[duedate]
		,[comment],[process_id],[processor],[AllowSub],[PWeight]
		,[PPc],[id_detail],[id_detail_process],[ReceivingID],[WO])
    SELECT [soitem],[po_item],[SalesPerson],[startdate],[duedate]
		,[comment],[process_id],[processor],[AllowSub],[PWeight]
		,[PPc],[id_detail],[id_detail_process],[ReceivingID],[WO]
	FROM dbo.StockLst_Process WHERE SOitem = @SOitem 
	
    SELECT @RC = @@ROWCOUNT, @err = @@ERROR
    IF @@ROWCOUNT = 0
       SET @OutParam = 'SO item:'+@SOitem+' not added to History!'  
    ELSE
       BEGIN
         DELETE FROM dbo.StockLst_Process WHERE SOitem = @SOitem 
         SELECT @RC = @@ROWCOUNT, @err = @@ERROR
         IF @@ROWCOUNT = 0
            SET @OutParam = 'SO item:'+@SOitem+' NOT deleted.'  
         ELSE
            SET @OutParam = 'Success'

       END

  END
ELSE
  SET @OutParam = 'SO item:'+@SOitem+' was not Found!'  
 

RETURN
END

GO
