*/
----

PRINT 'Count dbo.McMaster_Quote Records WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ';
SELECT COUNT(*) AS McMaster_Quotes_Cnt FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ;
PRINT ' '


Print 'a  ******************************************************';
PRINT 'a UPDATE dbo.McMaster_Quotes SET [CutLossLbs] WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0';

--SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 Order by ID DESC
UPDATE dbo.McMaster_Quotes
	SET [CutLossLbs] = case 
		when [Form] = '10' then dbo.f_Get_Weight(10,Alloy,'10',CC,[PI_Diameter]*1.02,.2,0,0)/10 
		when [Form] = '20' then dbo.f_Get_Weight(10,Alloy,'20',CC,[PI_Diameter]*1.01,.01,0,0)/10 
		when [Form] = '40' AND [PI_Thck] <= .19 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.01,.07,.07,0)/10 
		when [Form] = '40' AND [PI_Thck] > .19 AND [PI_Thck] <= .3 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.125,.25,0)/10 
		when [Form] = '40' AND [PI_Thck] > .3  AND [PI_Thck] <= .5 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.2,.2,0)/10 
		when [Form] = '40' AND [PI_Thck] > .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,.3,.3,0)/10 
		else 0.0001 end
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ;

------------------
PRINT 'a1 Make sure Cut Loss per PC is at least 0.0001';
PRINT 'UPDATE dbo.McMaster_Quotes SET [CutLossLbs] = 0.00001 ';

UPDATE dbo.McMaster_Quotes
	SET [CutLossLbs] = 0.00001 
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 
	AND [CutLossLbs] < .00001 ;


--------------------------------
PRINT 'b Weight_PC on 1PC';
PRINT 'UPDATE dbo.McMaster_Quotes SET [Weight_PC]  WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0' ;
UPDATE dbo.McMaster_Quotes
	SET [Weight_PC] = case 
		when [Form] = '10' then dbo.f_Get_Weight(10,Alloy,'10',CC,[PI_Diameter]*1.05,[PI_Length],0,0)/10 + [CutLossLbs]
		when [Form] = '20' then dbo.f_Get_Weight(10,Alloy,'20',CC,[PI_Diameter]*1.05,[PI_Length],0,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .19 then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.1,[PI_Width]+.07,  [PI_Length]+.07,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .3  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.09,[PI_Width]+.125,[PI_Length]+.25,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] <= .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.04,[PI_Width]+.15, [PI_Length]+.15,0)/10 + [CutLossLbs]
		when [Form] = '40' AND [PI_Thck] >  .5  then dbo.f_Get_Weight(10,Alloy,'40',CC,[PI_Thck]*1.06,[PI_Width]+.2,  [PI_Length]+.00,0)/10 + [CutLossLbs]
		else 0 end
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0;

IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE form = '40' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,'40',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy )
	begin
	PRINT 'SELECT * FROM dbo.McMaster_Quotes WHERE form = ''40'' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,''40'',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy	';
	SELECT * FROM dbo.McMaster_Quotes WHERE form = '40' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,'40',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy	
	PRINT 'These need fixed.';
	RETURN -1
	end
--------------------------------------

PRINT 'c';
UPDATE dbo.McMaster_Quotes
	SET [Bracket_Lbs] =  dbo.f_Bracket_Pounds(dbo.f_Pound_Bracket([Weight_PC]))
	,[P_Bracket] =  dbo.f_Pound_Bracket([Weight_PC])
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0 ;

PRINT 'c2 DELETE where Bracket_LBS > 2000';
DELETE FROM dbo.McMaster_Quotes
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0
	AND [Bracket_Lbs] > 2000;


IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE form = '40' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,'40',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy )
	begin
	PRINT 'SELECT * FROM dbo.McMaster_Quotes WHERE form = ''40'' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,''40'',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy	';
	SELECT * FROM dbo.McMaster_Quotes WHERE form = '40' and [Quote_Lbs] < 100  AND dbo.f_Get_Weight([FB_Min_PC],Alloy,'40',CC,[PI_Thck],[PI_Width],[PI_Length],0) + ( [CutLossLbs]*[FB_Min_PC] ) >	  2200 AND [PERIOD] = @Period AND Alloy=@Alloy	
	PRINT 'These need fixed.';
	RETURN -1
	end


----
-- use Weight_PC to find P_LB of Min or Worst Pound bracket
print 'd'

--dbo.f_SizeStandard(Q.Thck)
UPDATE dbo.McMaster_Quotes
	SET [P_Lb] = case 
		when form = '10' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0,Bracket_Lbs)*@Factor ,2) 
		when form = '20' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0,Bracket_Lbs)*@Factor ,2) 
		when Form = '40' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length],Bracket_Lbs)*@Factor ,2) 
		else 0 end
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0;
/*
	, case 
		when form = '10' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0,[Bracket_Lbs]) AS Numeric(8,2) )
		when form = '20' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0,[Bracket_Lbs]) AS Numeric(8,2) )
		when Form = '40' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length],[Bracket_Lbs]) AS Numeric(8,2) )
		else 0 end AS cP_LB_Bracket_Lbs
*/

--return 0

----
PRINT 'e DELETE WHERE ISNULL([P_Lb],0)=0 ';

DELETE FROM dbo.McMaster_Quotes
	WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = 0
	AND ISNULL([P_Lb],0)=0;


