				SET P_Lb = case 
						when form = '10' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0, [Bracket_Lbs]) AS Numeric(8,2) )
						when form = '20' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0, [Bracket_Lbs]) AS Numeric(8,2) )
						when Form = '40' then CAST( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length], [Bracket_Lbs]) AS Numeric(8,2) )
						else 0 end
