	--SET Price_Net = case when Price_UoM='Each Piece' then CAST( (P_Pc * Pieces) AS Numeric(8,2) )
	--					 when Price_UoM='Per Pound'  then CAST( (P_Lb * Quote_LBS) AS Numeric(8,2) ) end
	SET Price_Net = CAST( (P_Pc * Pieces) AS Numeric(8,2) )
	WHERE Alloy = @Alloy AND [Period] = @Period ;


--SELECT * FROM dbo.McMaster_Quotes WHERE [Period] = '2020-11-03'

----------------------------------------------------------------
PRINT 'Add the McM_Desc UPDATE dbo.McMaster_Quotes for bar';

UPDATE dbo.McMaster_Quotes
	SET McM_Desc = RTRIM(TradeName)+' '+RTRIM(dbo.f_Form_Name('10'))+', '+RTRIM(dbo.f_DescriptionMetricReport(FB_Min_PC, '10', PI_Diameter, PI_Length,0, ([Weight_Pc]+[CutLossLbs])*FB_Min_PC, 0, 0, 0, 0, 0)) --+' Long'
	, [Descript] = RTRIM(Alloy)+' '+RTRIM(dbo.f_DescriptionMetricReport(Pieces, Form, [PI_Diameter], [PI_Length], 0, Quote_LBS, 0,0,'','',''))  
	WHERE Alloy = @Alloy AND [Period] =  @Period  AND Form = '10' ;

PRINT 'Add the McM_Desc UPDATE dbo.McMaster_Quotes for wire';

UPDATE dbo.McMaster_Quotes
	SET McM_Desc = RTRIM(TradeName)+' '+RTRIM(dbo.f_Form_Name('20'))+', '+RTRIM(dbo.f_DescriptionMetricReport(FB_Min_PC, '20', PI_Diameter, PI_Length,0, ([Weight_Pc]+[CutLossLbs])*FB_Min_PC, 0, 0, 0, 0, 0))  
	,[Descript] = RTRIM(Alloy)+' '+RTRIM(dbo.f_DescriptionMetricReport(Pieces, Form, [PI_Diameter], [PI_Length], 0, Quote_LBS, 0,0,'','',''))  
	WHERE Alloy = @Alloy AND [Period] =  @Period AND Form = '20' ;


PRINT 'Add the McM_Desc Plate/Sheet';
PRINT 'UPDATE dbo.McMaster_Quotes SET McM_Desc';

UPDATE dbo.McMaster_Quotes
	SET McM_Desc = RTRIM(TradeName)+' '
	+ case when [PI_Thck] <= .19 then RTRIM(dbo.f_Form_Name('50')) else RTRIM(dbo.f_Form_Name('40')) end
	+', '+RTRIM(dbo.f_DescriptionMetricReport(FB_Min_PC, '40', PI_Thck, PI_Width, PI_Length, ([Weight_Pc]+[CutLossLbs])*FB_Min_PC, 0, 0, 0, 0, 0)) --+' Long'
	,[Descript] = RTRIM(Alloy)+' '+RTRIM(dbo.f_DescriptionMetricReport(Pieces, Form, [PI_Thck], [PI_Width], [PI_Length], Quote_LBS, 0,0,'','',''))  
FROM dbo.McMaster_Quotes
	WHERE Alloy = @Alloy AND [Period] = @Period AND Form = '40' ;

-----------------------------------------

-- SELECT * FROM dbo.McMaster_Quotes WHERE [Period] = '2020-11-03'
PRINT 'SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period ';
SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period ;

PRINT '*****************************************************************************';
PRINT ' You made it to the end of the code';
PRINT '*****************************************************************************';

END
