		-----------------------------------------------------------------------
		--------------------------------------------------------------------
		PRINT 'Find FB_Min_Pc with Bracket Pounds and [Quote_LBS]'
		PRINT '2c FB_Min_PC = FLOOR([Quote_LBS]/(([Weight_PC]+[CutLossLbs])) ';

		UPDATE dbo.McMaster_Quotes
			SET [FB_Min_PC] = FLOOR([Quote_LBS]/(([Weight_PC]+[CutLossLbs])) )
			--SET [FB_Min_PC] = ROUND([Bracket_Lbs]/([Weight_Pc]+[CutLossLbs]), 10 )
		WHERE Alloy = @Alloy AND [Period] = @Period 
			AND [PriceBreak] = @PriceBreak
			AND [FB_Min_PC] <= FLOOR([Quote_LBS]/(([Weight_PC]+[CutLossLbs])) ) ;


		------------------------
		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE [Period] = @Period AND [PriceBreak] = @PriceBreak AND [FB_Min_PC] < [PriceBreak]+1)
			begin
				PRINT 'Found  [FB_Min_PC] < [PriceBreak]+1 in PriceBreak ' +CAST( @PriceBreak AS CHAR(3));
				SELECT [FB_Min_PC],[PriceBreak],* FROM dbo.McMaster_Quotes WHERE [Period] = @Period AND [PriceBreak] = @PriceBreak AND [FB_Min_PC] < [PriceBreak]+1;
				RETURN -1
			end

		------------------------

		PRINT '2c3  [Pieces],[FB_Min_PC]';
		UPDATE dbo.McMaster_Quotes
			SET [Pieces] = [Bracket_Min_PC]
			--,[FB_Min_PC] = [Bracket_Min_PC]
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
				AND [Bracket_Min_PC] > 0 ;

		PRINT '2c2 [Bracket_Min_PC] ,[FB_Min_PC]';
		UPDATE dbo.McMaster_Quotes
			SET [Bracket_Min_PC] = [Pieces]
			,[FB_Min_PC] = [Pieces]
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
				AND [Bracket_Min_PC] < [Pieces] ;


		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND Pieces <= 1 AND @PriceBreak>0)
		begin
			SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND Pieces <= 1 AND @PriceBreak>0 ;
			PRINT '2c4  Found Pieces = 1 in PriceBreak ' +CAST( @PriceBreak AS CHAR(3));
			RETURN -1
		end
-- EXEC dbo.p_McMaster_23 @Period='2023-02-03',  @Alloy='6B   '; 

		-------------------------- 
		
		IF EXISTS(SELECT ID FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND [Quote_LBS] = 0)
		begin
			PRINT '2d FOUND a Quote_LBS of 0';
			SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND [Quote_LBS] = 0;
			return -1
		end


/*

		PRINT '2e SET P_Lb ';
		---------------------
		UPDATE dbo.McMaster_Quotes
		SET [P_Lb] = case 
			when form = '10' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'10',CC,'',[PI_Diameter],[PI_Length],0, ([Weight_Pc]+[CutLossLbs])*Pieces)*@Factor ,2)
			when form = '20' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'20',CC,'',[PI_Diameter],[PI_Length],0, ([Weight_Pc]+[CutLossLbs])*Pieces)*@Factor ,2)
			when Form = '40' then ROUND( dbo.f_GetPriceCC_CL(dbo.f_Price_Alloy(Alloy),'40',CC,'',[PI_Thck],[PI_Width],[PI_Length], ([Weight_Pc]+[CutLossLbs])*Pieces)*@Factor ,2)
			else 0 end
		WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak  
			AND dbo.f_Bracket_Pounds([P_Bracket]) > [Bracket_Lbs] ;

		--UPDATE dbo.McMaster_Quotes  SET P_Lb = dbo.f_GetPriceCC_CL(Alloy,'10',CC,'',[PI_Diameter],[PI_Length],0,([Weight_Pc]+[CutLossLbs])*Pieces)*@Factor WHERE [Period] = @Period AND Form = '10' AND [PriceBreak] = @PriceBreak

	
		PRINT '2f end of @PriceBreak > 0 AND @NewRecCount > 0';
	end  --end of @PriceBreak > 0 AND @NewRecCount > 0

-- EXEC dbo.p_McMaster @Period='2020-12-14',  @Alloy='C-276'

*/
/*
	--********************************************************************************** end of @PriceBreak > 0
	--**********************************************************************************
	---------
	--Update P_PC with new P_LB
	PRINT '3aa';	


		SELECT ROUND( ( P_Lb * ([Weight_Pc]+[CutLossLbs]) * [Pieces])*@Factor,2) as testP_Pc
			FROM dbo.McMaster_Quotes
				WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak

			

		UPDATE dbo.McMaster_Quotes  
			SET P_Pc = ROUND( ( P_Lb * ([Weight_Pc]+[CutLossLbs]) * [Pieces]) ,2) 
			WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak
*/
	
		---------------
	IF EXISTS( SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND ( [P_Lb] IS NULL  OR [P_Pc] IS NULL ))
	begin
		Print ' found null - [P_Lb] IS NULL  OR [P_Pc] IS NULL';
		SELECT * FROM dbo.McMaster_Quotes WHERE Alloy = @Alloy AND [Period] = @Period AND [PriceBreak] = @PriceBreak AND ( [P_Lb] IS NULL  OR [P_Pc] IS NULL );
	
		RETURN -1
	end

	PRINT 'End of PriceBreak loop -WHILE @PriceBreak < 9 AND @NewRecCount > 0';
	PRINT 'PriceBreak = '+CAST(@PriceBreak AS CHAR(10)) ;
	PRINT ' @NewRecCount = '+CAST(@NewRecCount AS CHAR(10)) ;

	PRINT '3bb SET @PriceBreak = @PriceBreak + 1';
	PRINT '***************************************************************************'
		------------------
	SET @PriceBreak = @PriceBreak + 1
	PRINT 'Start next @PriceBreak at '+CAST(@PriceBreak AS CHAR(10));
	PRINT '***************************************************************************';
	PRINT '  ';

END


------------------------------
PRINT '6 Remove duplicates P_PC';
PRINT '**************************************************************************';

DECLARE @nPBreak TINYINT = 1
--Start at 1, never delete the PriceBreak 0
--Keep PriceBreak under 10
WHILE @nPBreak < 10
BEGIN

/*	SELECT dbo.f_McMasterDuplicate([Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]) AS DUP,
