		AND McMaster_Quotes.[PriceBreak] = @nPBreak
		AND dbo.f_McMasterDuplicate([Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]) > 0 ;
*/
	IF EXISTS(	SELECT * FROM dbo.McMaster_Quotes 
		WHERE McMaster_Quotes.Alloy = @Alloy AND McMaster_Quotes.[Period] = @Period
		AND McMaster_Quotes.[PriceBreak] = @nPBreak
		AND dbo.f_McMasterDuplicate([Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]) > 0 
			)
		BEGIN
			SELECT '*' AS Duplicate, [Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]
			 FROM dbo.McMaster_Quotes 
				WHERE McMaster_Quotes.Alloy = @Alloy AND McMaster_Quotes.[Period] = @Period
				AND McMaster_Quotes.[PriceBreak] = @nPBreak
				AND dbo.f_McMasterDuplicate([Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]) > 0 ;



			PRINT 'DELETE where is Duplicate. dbo.f_McMasterDuplicate()'
			DELETE FROM dbo.McMaster_Quotes 
				WHERE McMaster_Quotes.Alloy = @Alloy AND McMaster_Quotes.[Period] = @Period
				AND McMaster_Quotes.[PriceBreak] = @nPBreak
				AND dbo.f_McMasterDuplicate([Period],[Alloy],[Form],[cc],[Thck],[PI_Width],[PI_Length],[PriceBreak],[P_Pc]) > 0 ;
			
		END

---------------------------------------------------
	
	SET @nPBreak = @nPBreak + 1
	PRINT ' End @nPBreak = ' +CAST(@nPBreak AS CHAR(10))+' Delete Dup';

END

