ALTER PROCEDURE [dbo].[p_PO_Sales_dShip]
	@cSOitem CHAR(10),
	@nShipWhere DEC(1)

AS

--EXEC dbo.p_PO_Sales_dShip '"+cSOitem+"',"+ALLTRIM(STR(nShipWhere)) +";"
--Mark Ship with dShip if PO 
SET NOCOUNT ON

DECLARE @err INT
SET @err = 0


--Test Parameters
IF LEN(@cSOitem) < 7
	SET @err = 6;

IF @nShipWhere < 1
	SET @err = 1;

--

IF @err > 0
	RETURN @err;

--
--BEGIN TRANSACTION Purchase_Finalize;
PRINT 'Start [p_PO_Sales_dShip] ';

IF @nShipWhere =2 OR @nShipWhere =4 OR @nShipWhere =6
	begin

	IF EXISTS(SELECT COUNT(*) AS Cntd FROM dbo.Sales WHERE SOitem = @cSOitem)
		begin
		--Update the StockLst_Detail	
			PRINT 'UPDATE dbo.Sales SET dShip=1 WHERE SOitem = ['+@cSOitem+']';	

			UPDATE dbo.Sales SET dShip=1 WHERE SOitem = @cSOitem
		end

	end


PRINT ' End  [p_PO_Sales_dShip]  ';

SELECT @err

