ALTER PROCEDURE [dbo].[p_PriceTable_Linear]
	
AS
BEGIN

-- EXEC dbo.p_PriceTable_Linear
/*
SELECT PT_ID, Alloy,Form,Thk, CC, CL,[Size], Size2, Size3,W0, W5, W10, W25, W50, W100, W200, W500, W1000, W2000, WBase
	FROM [dbo].[PriceTable] WITH(NoLOCK)  WHERE PT_ID IN (
689, 217, 218, 219, 222, 223, 224, 225, 226, 227, 228, 229, 230, 231, 232, 1324, 763, 522, 523, 524, 525, 526, 527, 528, 529, 456, 457, 458, 459, 460, 461, 462, 463, 464, 465, 741, 647, 644, 743, 646, 645, 530, 531, 532, 466, 467, 468, 469, 470, 471, 472, 473, 672, 90, 91, 92, 702, 93, 94, 95, 96, 97, 742, 98, 99, 100, 101, 102, 103, 494, 847, 711, 495, 421, 423, 424, 704, 703, 772, 773, 856, 333, 334, 335, 336, 337, 375, 376, 377, 378, 487, 710, 488, 489, 490, 491, 398, 686, 1383, 399, 400, 401, 402, 403, 404, 753, 343, 585
)
*/

SET NOCOUNT ON

DECLARE @cProblemIDs VARCHAR(MAX) = ''

DECLARE @PT_ID INT,
	@Alloy CHAR(12),
	@Form CHAR(2), 
	@CC CHAR(1), 
	@CL CHAR(1), 
	@Thk CHAR(5),
	@Size NUMERIC(9,4), 
	@Size2 NUMERIC(8,3), 
	@Size3 NUMERIC(8,3),
	@W0 NUMERIC(7,2), 
	@W5 NUMERIC(7,2), 
	@W10 NUMERIC(7,2), 
	@W25 NUMERIC(7,2),
	@W50 NUMERIC(7,2),
	@W100 NUMERIC(7,2),
	@W200 NUMERIC(7,2),
	@W500 NUMERIC(7,2),
	@W1000 NUMERIC(7,2),
	@W2000 NUMERIC(7,2),
	@WBase NUMERIC(7,2)

DECLARE PT_Line CURSOR FOR 

SELECT PT_ID,
	Alloy,
	Form,
	Thk, 
	CC, 
	CL,
	[Size], 
	Size2, 
	Size3,
	W0, 
	W5, 
	W10, 
	W25, 
	W50, 
	W100, 
	W200, 
	W500, 
	W1000, 
	W2000, 
	WBase
FROM [dbo].[PriceTable] WITH(NoLOCK)  
OPEN PT_Line; 
 
-- Perform the first fetch.  
FETCH NEXT FROM PT_Line
INTO @PT_ID
	,@Alloy
	,@Form
	,@CC
	,@CL
	,@Thk
	,@Size
	,@Size2
	,@Size3
	,@W0
	,@W5
	,@W10
	,@W25
	,@W50
	,@W100
	,@W200
	,@W500
	,@W1000
	,@W2000
	,@WBase

-- Check @@FETCH_STATUS to see if there are any more rows to fetch.  
WHILE @@FETCH_STATUS = 0  
BEGIN  
	-- This is executed as long as the previous fetch succeeds.  
	IF @W5 > @W0
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W10 > @W5
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W25 > @W10
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W50 > @W25
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W100 > @W50
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W200 > @W100
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W500 > @W200
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W1000 > @W500
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @W2000 > @W1000
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '
	ELSE
	IF @WBase > @W2000
		SET @cProblemIDs = @cProblemIDs +char(39)+TRIM(CAST(@PT_ID AS CHAR(10)))+char(39)+', '

   FETCH NEXT FROM PT_Line
   INTO @PT_ID	,@Alloy	,@Form ,@CC, @CL, @Thk ,@Size ,@Size2 ,@Size3
	,@W0 ,@W5 ,@W10 ,@W25 ,@W50 ,@W100 ,@W200 ,@W500 ,@W1000 ,@W2000 ,@WBase

-- IF LEFT(@cProblemIDs,2) = '''' AND LEN(@cProblemIDs) < 10
--	SET @cProblemIDs = SUBSTRING( @cProblemIDs, 2, LEN(@cProblemIDs)-1)

END  
  
CLOSE PT_Line;  
DEALLOCATE PT_Line; 

SET @cProblemIDs = LEFT(@cProblemIDs,LEN(@cProblemIDs)-1)
PRINT @cProblemIDs

/*
SELECT PT_ID, Alloy,Form,Thk, CC, CL,[Size], Size2, Size3,W0, W5, W10, W25, W50, W100, W200, W500, W1000, W2000, WBase
	FROM [dbo].[PriceTable] WITH(NoLOCK)  
	WHERE CAST(PT_ID AS CHAR(10)) IN ( @cProblemIDs )
	--WHERE PT_ID IN ( @cProblemIDs )
*/


-- EXEC dbo.p_PriceTable_Linear
END

GO
