ALTER PROCEDURE [dbo].[p_PriceTable_Linear_Fix]
	
AS

BEGIN

-- EXEC dbo.p_PriceTable_Linear first to see isues.
--Then EXEC dbo.p_PriceTable_Linear_Fix

/*
SELECT PT_ID, Alloy,Form,Thk, CC, CL,[Size], Size2, Size3,W0, W5, W10, W25, W50, W100, W200, W500, W1000, W2000, WBase
	FROM [dbo].[PriceTable] WITH(NoLOCK)  WHERE PT_ID IN (
689, 217, 218, 219, 222, 223, 224, 225, 226, 227, 228, 229, 230, 231, 232, 1324, 763, 522, 523, 524, 525, 526, 527, 528, 529, 456, 457, 458, 459, 460, 461, 462, 463, 464, 465, 741, 647, 644, 743, 646, 645, 530, 531, 532, 466, 467, 468, 469, 470, 471, 472, 473, 672, 90, 91, 92, 702, 93, 94, 95, 96, 97, 742, 98, 99, 100, 101, 102, 103, 494, 847, 711, 495, 421, 423, 424, 704, 703, 772, 773, 856, 333, 334, 335, 336, 337, 375, 376, 377, 378, 487, 710, 488, 489, 490, 491, 398, 686, 1383, 399, 400, 401, 402, 403, 404, 753, 343, 585
)
*/

SET NOCOUNT ON

DECLARE @PT_ID INT,
	@Alloy CHAR(12),
	@Form CHAR(2), 
	@CC CHAR(1), 
	@CL CHAR(1), 
	@Thk CHAR(5),
	@Size NUMERIC(9,4), 
	@Size2 NUMERIC(8,3), 
	@Size3 NUMERIC(8,3),
	@W0 NUMERIC(7,2), 
	@W5 NUMERIC(7,2), 
	@W10 NUMERIC(7,2), 
	@W25 NUMERIC(7,2),
	@W50 NUMERIC(7,2),
	@W100 NUMERIC(7,2),
	@W200 NUMERIC(7,2),
	@W500 NUMERIC(7,2),
	@W1000 NUMERIC(7,2),
	@W2000 NUMERIC(7,2),
	@WBase NUMERIC(7,2)

DECLARE PT_Line CURSOR FOR 

SELECT PT_ID,
	Alloy,
	Form,
	Thk, 
	CC, 
	CL,
	[Size], 
	Size2, 
	Size3,
	W0, 
	W5, 
	W10, 
	W25, 
	W50, 
	W100, 
	W200, 
	W500, 
	W1000, 
	W2000, 
	WBase
FROM [dbo].[PriceTable] WITH(NoLOCK)  
OPEN PT_Line; 
 
-- Perform the first fetch.  
FETCH NEXT FROM PT_Line
INTO @PT_ID
	,@Alloy
	,@Form
	,@CC
	,@CL
	,@Thk
	,@Size
	,@Size2
	,@Size3
	,@W0
	,@W5
	,@W10
	,@W25
	,@W50
	,@W100
	,@W200
	,@W500
	,@W1000
	,@W2000
	,@WBase

-- Check @@FETCH_STATUS to see if there are any more rows to fetch.  
WHILE @@FETCH_STATUS = 0  
BEGIN  
	-- This is executed as long as the previous fetch succeeds.  
	IF @W5 > @W0
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'    @W0='+CAST( @W0 AS CHAR(10))
			+'    @W5='+CAST( @W5 AS CHAR(10))
			+' W5 Calc is='+TRIM(CAST( (@W0+@W10)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W5 = case when (@W0+@W5)/2 < @W0 then (@W0+@W5)/2
				else (@W0+@W25)/2 end

		UPDATE dbo.PriceTable SET W5 = @W5
			WHERE PT_ID = @PT_ID
	end

	IF @W10 > @W5
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'    @W5='+CAST( @W5 AS CHAR(10))
			+'   @W10='+CAST( @W10 AS CHAR(10))
			+' W10 Calc is='+TRIM(CAST( (@W5+@W25)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W10 = case when (@W5+@W10)/2 < @W10 then (@W5+@W10)/2
				else (@W10+@W25)/2 end

		UPDATE dbo.PriceTable SET W10 = @W10
			WHERE PT_ID = @PT_ID
	end

	IF @W25 > @W10
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'   @W10='+CAST( @W10 AS CHAR(10))
			+'   @W25='+CAST( @W25 AS CHAR(10))
			+' W25 Calc is='+TRIM(CAST( (@W10+@W50)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W25 = case when (@W10+@W25)/2 < @W25 then (@W10+@W25)/2
				else (@W25+@W50)/2 end

		UPDATE dbo.PriceTable SET W25 = @W25
			WHERE PT_ID = @PT_ID
	end
	
	IF @W50 > @W25
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'   @W25='+CAST( @W25 AS CHAR(10))
			+'   @W50='+CAST( @W50 AS CHAR(10))
			+' W50 Calc is='+TRIM(CAST( (@W25+@W100)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W50 = case when (@W25+@W50)/2 < @W50 then (@W25+@W50)/2
				else (@W50+@W100)/2 end

		UPDATE dbo.PriceTable SET W50 = @W50
			WHERE PT_ID = @PT_ID
	end
	
	IF @W100 > @W50
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'   @W50='+CAST( @W50 AS CHAR(10))
			+'  @W100='+CAST( @W100 AS CHAR(10))
			+' W100 Calc is='+TRIM(CAST( (@W50+@W200)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W100 = case when (@W50+@W100)/2 < @W100 then (@W50+@W100)/2
				else (@W100+@W200)/2 end

		UPDATE dbo.PriceTable SET W100 = @W100
			WHERE PT_ID = @PT_ID
	end
	
	IF @W200 > @W100
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'  @W100='+CAST( @W100 AS CHAR(10))
			+'  @W200='+CAST( @W200 AS CHAR(10))
			+' W200 Calc is='+TRIM(CAST( (@W100+@W500)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W200 = case when (@W100+@W200)/2 < @W200 then (@W100+@W200)/2
				else (@W200+@W500)/2 end
		
		UPDATE dbo.PriceTable SET W200 = @W200
			WHERE PT_ID = @PT_ID
	end
	
	IF @W500 > @W200
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'  @W200='+CAST( @W200 AS CHAR(10))
			+'  @W500='+CAST( @W500 AS CHAR(10))
			+' W500 Calc is='+TRIM(CAST( (@W200+@W1000)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W500 = case when (@W200+@W500)/2 < @W500 then (@W200+@W500)/2
				else (@W500+@W1000)/2 end
		
		UPDATE dbo.PriceTable SET W500 = @W500
			WHERE PT_ID = @PT_ID
	end
	
	IF @W1000 > @W500
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+'  @W500='+CAST( @W500 AS CHAR(10))
			+' @W1000='+CAST( @W1000 AS CHAR(10))
			+' W1000 Calc is='+TRIM(CAST( (@W500+@W2000)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W1000 = case when (@W500+@W1000)/2 < @W1000 then (@W500+@W1000)/2
				else (@W1000+@W2000)/2 end
		
		UPDATE dbo.PriceTable SET W1000 = @W1000
			WHERE PT_ID = @PT_ID
	end
	
	IF @W2000 > @W1000
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+' @W1000='+CAST( @W1000 AS CHAR(10))
			+' @W2000='+CAST( @W2000 AS CHAR(10))
			+' W2000 Calc is='+TRIM(CAST( (@W1000+@WBase)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @W2000 = case when (@W1000+@W2000)/2 < @W2000 then (@W1000+@W2000)/2
				else (@W2000+@WBase)/2 end
		
		UPDATE dbo.PriceTable SET w2000 = @W2000
			WHERE PT_ID = @PT_ID
	end
	
	IF @WBase > @W2000
	begin
		PRINT 'PT_ID='+CAST( @PT_ID AS CHAR(10))
			+'  Alloy= '+@Alloy+' Form= '+@Form
			+' W2000='+CAST( @W2000 AS CHAR(10))
			+' WBase='+CAST( @WBase AS CHAR(10))
			+' W2000 Calc is='+TRIM(CAST( (@W2000+@WBase)/2 AS CHAR(10)))
			+' Thk '+@Thk

		SET @WBase = case 
			when (@W2000+@WBase)/2 > @WBase then (@W2000+@WBase)/2 
			when @WBase*.95 < @W2000 then @WBase*.95
			when @W2000 *.9 < @WBASE then @W2000*.9
			else @W2000-1 end

		UPDATE dbo.PriceTable SET WBase = @WBase
			WHERE PT_ID = @PT_ID
		
		PRINT '- lowered Base price to '+CAST(@WBase AS CHAR(10))
		
	end

   FETCH NEXT FROM PT_Line
   INTO @PT_ID	,@Alloy	,@Form ,@CC, @CL, @Thk ,@Size ,@Size2 ,@Size3
	,@W0 ,@W5 ,@W10 ,@W25 ,@W50 ,@W100 ,@W200 ,@W500 ,@W1000 ,@W2000 ,@WBase

END  
  
CLOSE PT_Line;  
DEALLOCATE PT_Line; 

-- EXEC dbo.p_PriceTable_Linear_Fix
-- EXEC dbo.p_PriceTable_Linear
END

