ALTER PROCEDURE [dbo].[p_Purchase_Finalize]
	@nID_Detail INT,
	@cTBL CHAR(1),
	@nID_Detail_Process INT,
	@nPerUnit MONEY,
	@nUnits MONEY,
	@cPOitem CHAR(13),
	@nVendor_InvoiceID INT

AS

SET NOCOUNT ON

DECLARE @err INT
SET @err = 0


--Test Parameters
IF @nID_Detail < 1
	SET @err = 1;

IF NOT ( @cTBL = 'S' or @cTBL = 'B' or @cTBL = 'W' )
	SET @err = 2;

--@nID_Detail_Process may not be known.
IF @nID_Detail_Process < 0
	SET @err = 3;

IF @nPerUnit < 0
	SET @err = 4;

IF @nUnits < 0
	SET @err = 5;

IF LEN(@cPOitem) < 7
	SET @err = 6;

IF @nVendor_InvoiceID < 1
	SET @err = 7;

--

IF @err > 0
	RETURN @err;

--
BEGIN TRANSACTION Purchase_Finalize;
PRINT 'Start [p_Purchase_Finalize] with TRANSACTION Purchase_Finalize';

IF EXISTS(SELECT COUNT(*) AS Cntd FROM dbo.StockLst_Detail  WHERE ID_Detail = @nID_Detail)
	begin
	--Update the StockLst_Detail		
	PRINT 'Update Lst_Detail with InvoiceValue,CostValue';

	BEGIN TRY

	IF @cTBL = 'S'
		UPDATE dbo.StockLst_Detail 
			SET InvoiceValue = @nPerUnit
			,CostValue = @nPerUnit
			WHERE ID_Detail = @nID_Detail;

	IF @cTBL = 'B'
		UPDATE dbo.BrokerLst_Detail 
			SET InvoiceValue = @nPerUnit
			,CostValue = @nPerUnit
			WHERE ID_Detail = @nID_Detail;

	IF @cTBL = 'W'
		UPDATE dbo.WIPLst_Detail 
			SET InvoiceValue = @nPerUnit
			,CostValue = @nPerUnit
			WHERE ID_Detail = @nID_Detail;

	END TRY
	BEGIN CATCH
		-- Execute the error retrieval routine.
		PRINT 'ERROR: Update Lst_Detail with InvoiceValue,CostValue'
		--EXECUTE dbo.p_GetErrorInfo;
		EXECUTE dbo.p_LogError;
		SET @err = 8;
	END CATCH;

	end

IF @err > 0
	begin
	ROLLBACK TRANSACTION Purchase_Finalize;
	RETURN @err
	end
ELSE
	PRINT 'END: Update Lst_Detail with InvoiceValue,CostValue';



IF EXISTS( SELECT COUNT(*) FROM dbo.StockLst_Value WHERE ID_Detail = @nID_Detail
		AND TBL=@cTBL 
		--AND InvoiceValue > 0 
		) 
	begin
	--
	PRINT 'UPDATE dbo.StockLst_Value InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal';
		
	BEGIN TRY

	--IF @cTBL = 'S' use cTBL
	UPDATE dbo.StockLst_Value SET 
			ID_Detail=@nID_Detail,
			TBL=@cTBL,
			ID_Detail_Process=@nID_Detail_Process,
			InvoiceValue=@nPerUnit,
			CurrUnitPrice=@nPerUnit,
			CurrUnits=@nUnits,
			CurrTotal=@nPerUnit*@nUnits,
			POitem=@cPOitem,
			VI_ID_Detail=@nVendor_InvoiceID,
			LastEdit=GetDate()
			WHERE ID_Detail = @nID_Detail
			AND TBL=@cTBL

	END TRY
	BEGIN CATCH
		-- Execute the error retrieval routine.
		PRINT 'ERROR: UPDATE dbo.StockLst_Value InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal'
		--EXECUTE dbo.p_GetErrorInfo;
		EXECUTE dbo.p_LogError;
		SET @err = 9;
	END CATCH;

	IF @err = 0
		PRINT 'END:UPDATE dbo.StockLst_Value InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal';

	end
ELSE
	begin
	--found a StockLst_Value record!
	--
	PRINT 'INSERT dbo.StockLst_Value (ID_Detail,TBL,ID_Detail_Process,InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal,POitem,VI_ID_Detail)';
		
	BEGIN TRY

	INSERT dbo.StockLst_Value (ID_Detail,TBL,ID_Detail_Process,InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal,POitem,VI_ID_Detail) VALUES 
		(@nID_Detail,@cTBL,@nID_Detail_Process,@nPerUnit,@nPerUnit,@nUnits,@nPerUnit*@nUnits,@cPOitem,@nVendor_InvoiceID)

	END TRY
	BEGIN CATCH
		-- Execute the error retrieval routine.
		PRINT 'ERROR: INSERT dbo.StockLst_Value ('
		--EXECUTE dbo.p_GetErrorInfo;
		EXECUTE dbo.p_LogError;
		SET @err = 10;
	END CATCH;

	IF @err = 0
		PRINT 'END: INSERT dbo.StockLst_Value (ID_Detail,TBL,ID_Detail_Process,InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal,POitem,VI_ID_Detail)';


	end


IF @err > 0
	begin
	ROLLBACK TRANSACTION Purchase_Finalize;
	RETURN @err
	end

--------------------------------
--Fix Lst_Process
BEGIN TRY
	
	PRINT 'DELETE Lst_Process for @nID_Detail AND Process_ID = [INCOMING]'

	IF @cTBL = 'S'
		DELETE FROM dbo.StockLst_Process 
			WHERE (ID_Detail = @nID_Detail
			AND (Process_ID = 'INCOMING  ' OR Process_ID = 'PARTRECV'))
			OR Process_ID = 'CORRECTION '
			OR Process_ID = 'CANCELLED  ';

	IF @cTBL = 'B'
		DELETE FROM dbo.BrokerLst_Process 
			WHERE (ID_Detail = @nID_Detail
			AND (Process_ID = 'INCOMING  ' OR Process_ID = 'PARTRECV'))
			OR Process_ID = 'CORRECTION '
			OR Process_ID = 'CANCELLED  ';

	IF @cTBL = 'W'
		DELETE FROM dbo.WIPLst_Process 
			WHERE (ID_Detail = @nID_Detail
			AND (Process_ID = 'INCOMING  ' OR Process_ID = 'PARTRECV'))
			OR Process_ID = 'CORRECTION '
			OR Process_ID = 'CANCELLED  ';

END TRY
BEGIN CATCH
	-- Execute the error retrieval routine.
	PRINT 'ERROR: DELETE Lst_Process for @nID_Detail AND (Process_ID = [INCOMING] OR Process_ID = [PARTRECV])'
	--EXECUTE dbo.p_GetErrorInfo;
	EXECUTE dbo.p_LogError;
	SET @err =11;
END CATCH;

IF @err = 0
	PRINT 'END: DELETE Lst_Process for @nID_Detail AND (Process_ID = [INCOMING] OR Process_ID = [PARTRECV])'

------------------------------

IF XACT_STATE() = -1
	SET @err = 99;    --	ROLLBACK TRANSACTION;

IF @err = 0
	begin
	COMMIT TRANSACTION Purchase_Finalize;
	PRINT 'COMMIT TRANSACTION Purchase_Finalize'
	end
ELSE
	begin
	ROLLBACK TRANSACTION Purchase_Finalize;
	PRINT 'ROLLBACK TRANSACTION Purchase_Finalize;'
	PRINT CAST(@err AS CHAR(10))
	end

PRINT 'End   [p_Purchase_Finalize] ';

--GRANT EXECUTE ON [dbo].[p_Purchase_Finalize] TO [WINDFALL\HPA] AS [dbo];

/*
--For Testing results!

DECLARE @nID_Detail INT , @cTBL CHAR(1), @nID_Detail_Process INT, @nPerUnit MONEY, @nUnits MONEY,  @cPOitem CHAR(13),     @nVendor_InvoiceID INT
SELECT @nID_Detail =7014 , @cTBL ='B', @nID_Detail_Process =0,  @nPerUnit= 13.0500,@nUnits= 8.6000,@cPOitem='   503317-01',@nVendor_InvoiceID= 2469

SELECT ID_Detail,TBL,ID_Detail_Process,InvoiceValue,CurrUnitPrice,CurrUnits,CurrTotal,POitem,VI_ID_Detail,LastEdit	FROM dbo.StockLst_Value
 WHERE ID_Detail = @nID_Detail AND TBL=@cTBL

IF @cTBL='B'
	SELECT InvoiceValue,CostValue,@cTBL AS TBL FROM dbo.BrokerLst_Detail WHERE ID_Detail = @nID_Detail
ELSE
	SELECT InvoiceValue,CostValue,@cTBL AS TBL FROM dbo.Stocklst_Detail WHERE ID_Detail = @nID_Detail

SELECT * FROM dbo.PurchaseOrder WHERE POitem=@cPOitem

SELECT * FROM dbo.Vendor_Invoice VI 
LEFT OUTER JOIN dbo.Vendor_Invoice_Detail VID ON VID.Vendor_Invoice_ID = VI.ID 
WHERE ID = @nVendor_InvoiceID

IF @cTBL='S'
	SELECT @cTBL AS TBL,Process_ID FROM dbo.StockLst_Process WHERE ID_Detail = @nID_Detail
ELSE
	SELECT @cTBL AS TBL,Process_ID FROM dbo.BrokerLst_Process WHERE ID_Detail = @nID_Detail

SELECT TOP 20 * FROM  AuditDB.dbo.ErrorLog ORDER By EventDate DESC
*/
SELECT @err

--GRANT EXECUTE ON [dbo].[f_Calc_SS_CCL] TO [WINDFALL\HPA] AS [dbo];
GO
