SET @OldPOitem = '  5000000-01'
SELECT * FROM dbo.AllQuotes WHERE POitem > @OldPOitem
SELECT * FROM dbo.WorkOrder WHERE POitem > @OldPOitem
SELECT * FROM dbo.StartingStock WHERE POitem > @OldPOitem
SELECT * FROM dbo.PurchaseOrder WHERE POitem > @OldPOitem
SELECT * FROM dbo.BrokerLst_Master WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Master WHERE PO_item > @OldPOitem 
SELECT * FROM dbo.BrokerLst_Process WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Process WHERE PO_item > @OldPOitem
SELECT * FROM dbo.StockLst_Value WHERE POitem > @OldPOitem
-- EXEC dbo.p_PurchaseOrder_Change_POitem '   501918-03','
*/
RETURN
END

