ALTER PROCEDURE [dbo].[p_QA_PR_84_01]
	-- Add the parameters for the stored procedure here
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
DECLARE @startMonthDate DATETIME = DATEADD(month, DATEDIFF(month, 0, DATEADD(Month, -12, GETDATE())), 0)
	SELECT [QA_ISS_ID]
		  ,[SOItem]
		  ,e.FName + ' ' + e.LName as Name
		  ,[Time]
		  ,[Notes]
	  FROM [dbo].[QA_Inspection_Statistical_Sampling] iss
	  INNER JOIN ERP_1.dbo.Employee e on iss.EmployeeID = e.ID
	  WHERE [Time] > @startMonthDate
  	  ORDER BY [Time] desc
END
GO
