ALTER  PROCEDURE [dbo].[p_Random_Password]
(@PassWord Char(10) OUTPUT)
AS

--DECLARE @PassWord Char(10)
--EXEC dbo.p_Random_Password @PassWord

DECLARE @String char(62)
SET @String = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz' 

SELECT @PassWord = 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) +
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + 
	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1)

--Random 6-10 Char
--SELECT @PassWord = SUBSTRING(	SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) + SUBSTRING(@String,CONVERT(tinyint,RAND()*62)+1,1) ,1,CONVERT(tinyint,RAND()*5)+6)
PRINT @PassWord


--GRANT EXECUTE ON [dbo].[p_Random_Password] TO [WINDFALL\HPA] AS [dbo];

GO
/****** Object:  StoredProcedure [dbo].[p_Rc_to_BHN]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_Rc_to_BHN]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_Rc_to_BHN] AS' 
END
GO
ALTER PROCEDURE [dbo].[p_Rc_to_BHN] 
    @HRc_value CHAR(4),
    @BHN_value SmallInt OUTPUT
AS
BEGIN
    DECLARE @conversion_factor DECIMAL(10,2);
	DECLARE @nRC TinyInt = 0

	SET @nRC = CAST( RIGHT(@HRc_value,3) AS TinyInt )

	IF @nRC < 1
		SET @nRC = CAST( RIGHT(@HRc_value,2) AS TinyInt )


    -- Check if the HRC value is within a reasonable range (typically 20-70 for HRC)
    IF @nRC >= 20 AND @nRC <= 70 
		begin
        SET @conversion_factor = 13000;
        SET @BHN_value = @conversion_factor / (@nRC - 20);
		end
    ELSE
        THROW 50001, 'HRC value must be between 20 and 70', 1;
   
END;

 --GRANT EXECUTE ON [dbo].[p_Rc_to_BHN] TO [WINDFALL\HPA] AS [dbo];
GO
