		,[Started],[StartDate], [Finished]
		,[Oper_ID],[Oper_Note]
		,Cncld, CnclDate
	) VALUES (
		 @rtr_ID ,@nDetail 
		,1, GetDate() ,1
		,@nOper_ID
		,'Operation Cancel'
		,1, GetDate()
		) ;

	end




