	PRINT 'Found Detail '+CAST(@nDetail AS CHAR(10))+' to UPDATE'
end
ELSE
begin
	SELECT @nDetail = MAX(ISNULL(Detail,0)) FROM dbo.rtr_Detail WHERE rtr_ID = @rtr_ID AND Oper_ID = 523;
	PRINT 'Did not found Detail, resetting Detail to '+CAST(@nDetail AS CHAR(10))+' to INSERT'
end


