IF @rtr_ID = 0
	begin
	--need to insert rtr

	PRINT 'INSERT dbo.rtr p_rtr_Select_Material_Done'

	INSERT INTO dbo.[rtr] WITH (ROWLOCK)  (
	SOitem
    ,WO
    ,WO_Detail
	,[Started],[Finished]
	)
    Values (
	 @cOrderNumber
    ,@nOrderNumber
    ,@nOrderNumber
	,1,0
	)

	SET @rtr_ID = SCOPE_IDENTITY()
	--SCOPE_IDENTITY(): returns the last identity value generated in the current scope (i.e. stored procedure, trigger, function, etc).

	/*
	IF @cOrderType = 'WO'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE WO = @nWO AND WO > 0;
	ELSE 
	IF @cOrderType = 'WO_Detail'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE WO_Detail = @nWO_Detail AND WO_Detail > 0;
	ELSE 
	IF @cOrderType = 'SOitem'
		SELECT TOP 1 @rtr_ID = ID FROM dbo.rtr WITH (ROWLOCK) WHERE SOitem = dbo.f_ProperSOitem(@cSOitem) AND NOT SOitem = dbo.f_ProperSOitem('');
	*/

	IF @rtr_ID = 0
		begin
			PRINT 'EXEC dbo.p_rtr_Select_Material_Done '+@cOrderType+' INSERT dbo.rtr Failed!'
			RETURN
		end


	end
  
  
IF @rtr_ID > 0
	RETURN


DECLARE @nDetail INT = 99
DECLARE @Update INT = 0

SELECT @nDetail = MAX(Detail) FROM dbo.rtr_Detail WHERE rtr_ID = @rtr_ID AND Oper_ID = 523 AND TBL = @TBL AND ID_Detail_Process = @ID_Detail_Process;
IF @nDetail > 99
	SET @Update = 1
ELSE
	SELECT @nDetail = MAX(ISNULL(Detail,0)) FROM dbo.rtr_Detail WHERE rtr_ID = @rtr_ID AND Oper_ID = 523;

IF @Update = 1
	begin

	PRINT 'UPDATE dbo.rtr_Detail '

	UPDATE dbo.rtr_Detail 
		SET FinishDate = GetDate(), [Finished] = 1, TBL = @TBL
		WHERE rtr_Detail.rtr_ID = @rtr_ID 
		AND rtr_Detail.Oper_ID = 523
		AND TBL = @TBL
		AND rtr_Detail.ID_Detail_Process = @ID_Detail_Process;

	end
ELSE
	begin

	IF @nDetail < 99
		SET @nDetail = 99;

	SET @nDetail = @nDetail + 1;
	PRINT 'INSERT dbo.rtr_Detail '+CAST(@nDetail AS CHAR)

	INSERT INTO dbo.rtr_Detail 
		([rtr_ID],[Detail],[Started],[StartDate], [Finished],[FinishDate]
		,[Oper_ID],[Oper_Note]
		,[POitem],[Cncld],[EstTime],[ActTime],[TBL],[ID_Detail_Process])
			VALUES 
		(@rtr_ID ,@nDetail ,1 ,GetDate() ,1, GETDATE()
		,523
		,'Select Material Process '+@TBL+' ID_Detail_Process='+CAST(@ID_Detail_Process AS CHAR )
		,''		,0		,0		,0		,@TBL ,@ID_Detail_Process ) ;

	end



