ALTER PROCEDURE [dbo].[p_Sales_Ver_Mismatch]

AS

--EXEC dbo.p_Sales_Ver_Mismatch
--ran from Maintenace Plans: 

--https://raptor/ReportS/report/Sales%20Reports/Sales%20Version%20Issue

---------------------------------------------------------------------
DECLARE @cEmailFrom VARCHAR(30) = ERP_1.dbo.f_GetSQL_Server_Email()
DECLARE @Body varchar(4000)


SELECT SN.SalesNum, MAX(SN.Amendment) AS Amendment, MAX(SNR.VER) AS Rev_Ver 
	FROM dbo.Sales_No SN WITH(NOLOCK) 
	INNER JOIN dbo.Sales_No_Rev SNR WITH(NOLOCK) ON SN.salesnum = SNR.SalesNum
	WHERE SN.cncld = 0 
	GROUP BY SN.SalesNum
	HAVING MAX(SNR.VER) <> MAX(SN.amendment);

DECLARE @CntSO INT = 0
SELECT @CntSO = COUNT(*)
--SELECT *
	FROM dbo.Sales_No SN WITH(NOLOCK) 
	WHERE SN.cncld = 0 
	--AND SN.cmplt = 0
		AND ( 
		   ( ISNULL(SN.Amendment,0) < ( SELECT ISNULL(MAX(VER),0) FROM dbo.Sales_No_Rev   WHERE SalesNum = SN.salesnum ) )
	--	OR ( ISNULL(SN.Amendment,0) < ( SELECT ISNULL(MAX(VER),0) FROM dbo.Sales_No_Chng  WHERE SalesNum = SN.salesnum ) )			
			);


DECLARE @SN_Max tinyint = 0
DECLARE @SNR_Max tinyint = 0
DECLARE @SNC_Max tinyint = 0

IF @CntSO > 0
	BEGIN

	PRINT 'Sales Ver Mismatch in Sales_No';
	
	DECLARE @SalesNum INT = 0
	SELECT TOP 1 @SalesNum = SN.SalesNum
	FROM dbo.Sales_No SN WITH(NOLOCK) 
	INNER JOIN dbo.Sales_No_Rev SNR WITH(NOLOCK) ON SN.salesnum = SNR.SalesNum
	WHERE SN.cncld = 0 
	GROUP BY SN.SalesNum
	HAVING MAX(SNR.VER) <> MAX(SN.amendment);

	PRINT 'Results for SalesNum '+CAST(@SalesNum AS CHAR(10));
	SELECT @SalesNum AS SalesNum;

	SELECT MAX(VER) AS Amendment, 'Sales_No_Rev' AS txt FROM dbo.Sales_No_Rev WITH(NOLOCK) WHERE SalesNum =@SalesNum ;
	SELECT Amendment            , 'Sales_No' AS txt FROM dbo.Sales_No WITH(NOLOCK) WHERE SalesNum =@SalesNum;
	SELECT MAX([Ver]) AS Ver    , 'Sales_No_Chang' AS txt  FROM dbo.Sales_No_Chng WITH(NOLOCK) WHERE SalesNum = @SalesNum;

	SELECT @SNR_Max=MAX(VER)    FROM dbo.Sales_No_Rev WITH(NOLOCK) WHERE SalesNum =@SalesNum ;
	SELECT @SN_Max=Amendment  FROM dbo.Sales_No WITH(NOLOCK) WHERE SalesNum =@SalesNum;
	SELECT @SNC_Max=MAX([Ver]) FROM dbo.Sales_No_Chng WITH(NOLOCK) WHERE SalesNum = @SalesNum;

	PRINT '@SN_Max  '+CAST(@SN_Max AS CHAR(10));
	PRINT '@SNR_Max '+CAST(@SNR_Max AS CHAR(10));
	PRINT '@SNC_Max '+CAST(@SNC_Max AS CHAR(10));
	PRINT 'UPDATE dbo.Sales_No Set Amendment = @SNR_Max WHERE SalesNum = '+CAST(@SalesNum AS CHAR(10));

	UPDATE dbo.Sales_No Set Amendment = @SNR_Max WHERE SalesNum =@SalesNum ;

	SELECT @Body = ('Sales Ver Mismatch '+CHAR(13)
	 +' Counted: '+CAST(@CntSO AS CHAR(10))+CHAR(13)
	 +' --Fixed  Sales_No SalesNum '+ CAST(@SalesNum AS CHAR(10))+CHAR(13)+CHAR(13)
	 +'@SN_Max '+CAST(@SN_Max AS CHAR(10))+CHAR(13)
	 +'@SNR_Max '+CAST(@SNR_Max AS CHAR(10))+CHAR(13)
	 +'@SNC_Max '+CAST(@SNC_Max AS CHAR(10))+CHAR(13)
	 +'. Updated Sales_No Amendment to Max Version'+Cast(@SNR_Max AS CHAR(10)) +' from '+CAST(@SN_Max AS CHAR(10))+CHAR(13)
	 +' on '+RTRIM(GETDATE())+'. '
	 +@@SERVERNAME+'. Agent Job _ERP_1 Summarize Sales weekly dbo.p_Maintenance_Sales_No_Ver ' );
		

	EXEC dbo.p_eMail_Send
		@FromEmail = @cEmailFrom, 
		@ToEmail = 'David.Kirchner@ERP_1s.com', 
		@SubjectEmail = 'Sales Ver Mismatch',
		@BodyEmail = @Body,
		@BodyType = 'TEXT';

	----------

	
	END

RETURN;

--GRANT EXECUTE ON [dbo].[p_Sales_No_Ver_Mismatch] TO [WINDFALL\HPA]
GO
/****** Object:  StoredProcedure [dbo].[p_SalesGoalsWeekly]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_SalesGoalsWeekly]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_SalesGoalsWeekly] AS' 
END
GO
-- =============================================
-- Author:		Sean Lykins
-- Create date: 1/18/2012
-- Modified date: 11/20/2015
-- Description:	Used for Sales Goals - Weekly Report
-- =============================================
ALTER PROCEDURE [dbo].[p_SalesGoalsWeekly] 
	-- Add the parameters for the stored procedure here
	@sys_usr_abr char(1) = ''
	--,@DaysOld int = 0
	,@weeksOld int = 1
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
set datefirst 1
declare @sdate datetime,
		@edate datetime,
		@bdays int,
		@EpactCalc INT,  
        @PaschalDaysCalc INT, 
        @NumOfDaysToSunday INT, 
        @EasterMonth INT, 
        @EasterDay INT, 
        @Y INT
        --@WeekEnd INT,
        --@WeekStart INT
SET @bdays = 5
--SET @WeekEnd = 0
--SET @WeekStart = 7
SET @Y = YEAR(GETDATE())
SET @EpactCalc = (24 + 19 * (@Y % 19)) % 30 
SET @PaschalDaysCalc = @EpactCalc - (@EpactCalc / 28) 
SET @NumOfDaysToSunday = @PaschalDaysCalc - ( 
	(@Y + @Y / 4 + @PaschalDaysCalc - 13) % 7 
) 
SET @EasterMonth = 3 + (@NumOfDaysToSunday + 40) / 44 
SET @EasterDay = @NumOfDaysToSunday + 28 - ( 
	31 * (@EasterMonth / 4) 
) 
IF datename (dw, CONVERT(Date, GETDATE())) = 'Monday'
	BEGIN
	IF (MONTH(dbo.f_udf_nthWeekDay(5,'MON',YEAR(GETDATE()),05)) = 05)
		BEGIN
		IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, dbo.f_udf_nthWeekDay(5,'MON',YEAR(GETDATE()),05)))
			BEGIN
			SET @bdays -= 1
			END
		END	
	ELSE
		BEGIN
		IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, dbo.f_udf_nthWeekDay(4,'MON',YEAR(GETDATE()),05)))
			BEGIN
			SET @bdays -= 1
			END
		END
	END
IF datepart(dw, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/24')) != 6 AND datepart(dw, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/24')) != 7
	BEGIN
	IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/24')))
		BEGIN
		SET @bdays -= 1
		END	
	END	
IF datepart(dw, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/25')) != 6 AND datepart(dw, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/25')) != 7
	BEGIN
	IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, CONVERT(DATE, CAST(YEAR(GETDATE()-7) AS CHAR(4)) + '/12/25')))
		BEGIN
		SET @bdays -= 1
		END
	END	
IF datepart(dw, RTRIM(CONVERT(CHAR,YEAR(GETDATE())))+ '0101') != 6 AND datepart(dw, RTRIM(CONVERT(CHAR,YEAR(GETDATE())))+ '0101') != 7
	BEGIN
	IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, CONVERT(DATE, CAST(YEAR(GETDATE()) AS CHAR(4)) + '/01/01')))
		BEGIN
		SET @bdays -= 1
		END
	END	
IF datepart(dw, RTRIM(CONVERT(SMALLDATETIME,RTRIM(@Y) + RIGHT('0'+RTRIM(@EasterMonth), 2) + RIGHT('0'+RTRIM(@EasterDay), 2))-2)) != 6 AND datepart(dw, RTRIM(CONVERT(SMALLDATETIME,RTRIM(@Y) + RIGHT('0'+RTRIM(@EasterMonth), 2) + RIGHT('0'+RTRIM(@EasterDay), 2))-2)) != 7
	BEGIN
	IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, CONVERT(SMALLDATETIME,RTRIM(@Y) + RIGHT('0'+RTRIM(@EasterMonth), 2) + RIGHT('0'+RTRIM(@EasterDay), 2))-2))
		BEGIN
		SET @bdays -= 1
		END	
	END	
IF datepart(dw, CONVERT(SMALLDATETIME,RTRIM(CONVERT(CHAR,YEAR(GETDATE())))+ '0704')) != 6 AND datepart(dw, CONVERT(SMALLDATETIME,RTRIM(CONVERT(CHAR,YEAR(GETDATE())))+ '0704')) != 7
	BEGIN
	IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, CONVERT(DATE, CAST(YEAR(GETDATE()) AS CHAR(4)) + '/07/04')))
		BEGIN
		SET @bdays -= 1
		END	
	END	
IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, dbo.f_udf_nthWeekDay(4,'THU',@Y,11)))
	BEGIN
	SET @bdays -= 2
	END	
IF (DATEPART(Week, GETDATE()) - @weeksOld = DATEPART(Week, dbo.f_udf_nthWeekDay(1,'MON',@Y,09)))
	BEGIN
	SET @bdays -= 1
	END	
IF @sys_usr_abr = ANY (SELECT distinct [ans] FROM [dbo].[AppSetup] WHERE prp = 'ActiveSales')
	BEGIN
	SELECT --DISTINCT  ROW_NUMBER() OVER(ORDER BY QuoteDate DESC) AS 'Completed Quotes'
	1 AS 'Completed Quotes'
	,[alloy]
	,[form]
	,[cc]
	,[pieces]
	,[thck]
	,[sz2]
	,[sz3]
	,[p_lb]
	,[p_pc]
	,[p_ft]
	,[cuts]
	,[otherfld]
	,[otherp]
	,[lotp]
	,[lotcost]
	,inqdate
	,RTRIM([un]) AS 'Employee'
	,[quotedate]
	,@bdays AS 'bDays'
	FROM dbo.[allquotes] INNER JOIN dbo.AppSetup ON salesp = ans
	WHERE DATEPART(Week, QuoteDate) = DATEPART(Week, GETDATE()) - @weeksOld
	AND YEAR(DATEADD(WEEK, DATEDIFF(WEEK, '19050101', GETDATE()-7), '19050101')) = YEAR(quotedate)
	--AND open_ = 0
	AND (p_lb != 0 OR p_ft != 0 OR p_pc != 0 or lotp != 0 or otherp != 0)
	AND @sys_usr_abr = salesp
	AND prp = 'ActiveSales' --Changed query to use ActiveSales
	AND LEN(un) > 1
	ORDER BY QuoteDate DESC
	END
ELSE
	BEGIN
	SELECT --DISTINCT ROW_NUMBER() OVER(ORDER BY QuoteDate DESC) AS 'Completed Quotes'
	1 AS 'Completed Quotes'
	,[alloy]
	,[form]
	,[cc]
	,[pieces]
	,[thck]
	,[sz2]
	,[sz3]
	,[p_lb]
	,[p_pc]
	,[p_ft]
	,[cuts]
	,[otherfld]
	,[otherp]
	,[lotp]
	,[lotcost]
	,inqdate
	,RTRIM([un]) AS 'Employee'
	,[quotedate]
	,@bdays AS 'bDays'
	FROM [dbo].[allquotes]
		INNER JOIN [dbo].AppSetup ON salesp = ans
	WHERE DATEPART(Week, QuoteDate) = DATEPART(Week, GETDATE()) - @weeksOld
	AND YEAR(DATEADD(WEEK, DATEDIFF(WEEK, '19050101', GETDATE()-7), '19050101')) = YEAR(quotedate)
	--AND open_ = 0
	AND (p_lb != 0 OR p_ft != 0 OR p_pc != 0 or lotp != 0 or otherp != 0)
	AND prp = 'ActiveSales' --Changed query to use ActiveSales
	AND LEN(un) > 1
	ORDER BY QuoteDate DESC
	END;
END
GO
