-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
ALTER PROCEDURE [dbo].[p_SalesNum]
	@nSalesNum INT
AS
BEGIN

--EXEC dbo.p_SalesNum 114454;
--EXEC dbo.p_SalesNum 110439;

--Declare @nSalesNum INT = 114454
DECLARE @cSoitem CHAR(10) = dbo.f_ProperSOitem( CAST( @nSalesNum AS CHAR(7) )+ '-01')
DECLARE @nCnt INT = 0

SELECT @nCnt=COUNT(*) FROM dbo.AllQuotes WHERE SalesNum = @nSalesNum;
IF @nCnt > 0
	begin
	print 'DELETE FROM dbo.AllQuotes WHERE SalesNum = '+CAST(@nSalesNum AS CHAR(10))+';';
	SELECT * FROM dbo.AllQuotes WHERE SalesNum = @nSalesNum;
	end

SELECT @nCnt=COUNT(*) FROM dbo.Ar.AllQuotes_History WHERE SalesNum = @nSalesNum;
IF @nCnt > 0
	begin
