/****** Object:  StoredProcedure [dbo].[p_Search_Programs]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER OFF
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_Search_Programs]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_Search_Programs] AS' 
END
GO

ALTER PROCEDURE [dbo].[p_Search_Programs]
(
@Search VARCHAR(250)
)
AS
-- EXEC dbo.p_Search_Programs '%AllQuotes%'
-- EXEC dbo.p_Search_Programs '%PU %'
--RETURNS Function or Procedure that refences object

BEGIN
SET NOCOUNT ON


--DECLARE @Search VARCHAR(250)
--SET @Search = '%AllQuotes%'

select		distinct
			ObjectType		= o.type_desc
		,	ObjectName		= o.name
		,	CodeSequence	= c_display.colid
		,	Code			= c_display.[text]
from		sys.objects o
inner join	sys.syscomments c_search
			on c_search.id = o.[object_id]
inner join	sys.syscomments c_display
			on c_display.id = o.[object_id]
where		o.type_desc not in ('INTERNAL_TABLE','SERVICE_QUEUE','SYSTEM_TABLE')
and			c_search.[text] like @Search
order by	1, 2, 3


END
GO
/****** Object:  StoredProcedure [dbo].[p_Set_Sales_Hold_Status]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_Set_Sales_Hold_Status]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_Set_Sales_Hold_Status] AS' 
END
GO



ALTER PROCEDURE [dbo].[p_Set_Sales_Hold_Status]
(
@cSOitem char(10)
)
AS

-- EXEC dbo.p_Set_Sales_Hold_Status ' 114593-01'

BEGIN
SET NOCOUNT ON
declare @err int,
        @RC int

set @err = 0
set @rc = 0

DECLARE @nCount INT = 0

SELECT @nCount = COUNT(*)  
	FROM dbo.Sales_Hold_Status WITH(NOLOCK) 
	WHERE SOitem = dbo.f_ProperSOitem(@cSOitem)

IF @nCount > 0  --Found 
begin
	DECLARE @cHold_Type CHAR(10) = ''
	DECLARE @lHold_Value BIT = 0

	DECLARE @lBit BIT = 0
	DECLARE @lQA BIT = 0
	DECLARE @lAR BIT = 0
	DECLARE @lINV BIT = 0
	DECLARE @lEQP BIT = 0
	DECLARE @lCSTR BIT = 0
	DECLARE @RCV BIT = 0

	DECLARE #tmpHold_Status CURSOR READ_ONLY FOR 
	SELECT [Hold_Type],[Hold_Value] 
	FROM dbo.Sales_Hold_Status WITH(NOLOCK) 
	 WHERE SOitem = dbo.f_ProperSOitem(@cSOitem)
	 ORDER BY [WHEN] 
	
	OPEN #tmpHold_Status

	FETCH NEXT FROM #tmpHold_Status INTO @cHold_Type, @lHold_Value
	WHILE (@@fetch_status <> -1)
	BEGIN
		IF (@@fetch_status <> -2)
		BEGIN
			IF @cHold_Type = 'QA'
				SET @lQA = @lHold_Value
			ELSE  
			IF @cHold_Type = 'AR'
				SET @lAR = @lHold_Value
			ELSE
			IF @cHold_Type = 'INV'
				SET @lINV = @lHold_Value
			ELSE
			IF @cHold_Type = 'EQP'
				SET @lEQP = @lHold_Value
			ELSE
			IF @cHold_Type = 'CSTR'
				SET @lCSTR = @lHold_Value
			ELSE
			IF @cHold_Type = 'RCV'
				SET @RCV = @lHold_Value

		FETCH NEXT FROM #tmpHold_Status INTO @cHold_Type, @lHold_Value
		
		END
	END
	
	CLOSE #tmpHold_Status
	DEALLOCATE #tmpHold_Status

	--
	SET @lBit = ( @lQA | @lAR | @lINV | @lEQP )
	--

	PRINT 'dbo.p_Set_Sales_Hold_Status: OverAll SOitem '''+@cSOitem+''' is '+CAST(@lBit AS CHAR(1))


	UPDATE dbo.Sales
		SET HOLD = @lBit
		WHERE SOitem = dbo.f_ProperSOitem(@cSOitem)
		AND HOLD != @lBit


end
END




GO
