SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_SetEmployee_DateLeft]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_SetEmployee_DateLeft] AS' 
END
GO
-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 08/06/2018
-- Description:	Created a simple proceedure to set an employee's dateleft value to remove them from OT views
-- =============================================
ALTER PROCEDURE [dbo].[p_SetEmployee_DateLeft] 
	-- Add the parameters for the stored procedure here
	@empId bigint = 0
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	if exists(select * from dbo.TC_Replacement_Employees where EmployeeId = @empId)
	begin
		update dbo.TC_Replacement_Employees
		set DateLeft = GETDATE()
		where EmployeeId = @empId
	end
END
GO
