ALTER PROCEDURE [dbo].[P_Show_AllQuote_Sales]
( @cAlloy VARCHAR(12)
, @cForm VARCHAR(2)
, @cSalesP CHAR(1) 
)
AS
--EXEC dbo.[P_Show_AllQuote_Sales] @cAlloy = '6B',@cForm = '10',@cSalesP = 'S'

IF LEN(LTRIM(@cAlloy))= 0
	SET @cAlloy  = '%'
ELSE
	SET @cAlloy  = (@cAlloy)

SET @cForm   = LTRIM(@cForm)+'%'
SET @cSalesP = LTRIM(@cSalesP)+'%'

PRINT @cAlloy
PRINT @cForm
PRINT @cSalesP

--[dbo].[f_CCStandard](ISNULL(CC,'')) AS CC
--Turns A,B,C into '2'

SELECT DISTINCT Alloy, Form, CC, dbo.f_SizeStandard (ISNULL(Thck,0)) AS THCK, YEAR(ShipDate) AS ShipYear, MONTH(ShipDate) AS ShipMonth 
	INTO #CurrentYearSales
	FROM dbo.AllQuotes
	WHERE Alloy LIKE @cAlloy AND Form LIKE @cForm AND SalesP LIKE @cSalesP
	AND YEAR(ShipDate) = YEAR(GETDATE())

SELECT DISTINCT Alloy, Form, CC, dbo.f_SizeStandard (ISNULL(Thck,0)) AS THCK, YEAR(ShipDate) AS ShipYear, MONTH(ShipDate) AS ShipMonth
	INTO #PastYearSales
	FROM dbo.AllQuotes
	WHERE Alloy LIKE @cAlloy AND Form LIKE @cForm AND SalesP LIKE @cSalesP 
	AND YEAR(ShipDate) = YEAR(GETDATE())-1

SELECT DISTINCT Alloy, Form, CC, dbo.f_SizeStandard (ISNULL(Thck,0)) AS THCK, YEAR(ShipDate) AS ShipYear, MONTH(ShipDate) AS ShipMonth
	INTO #Past2YearSales
	FROM dbo.AllQuotes WHERE Alloy LIKE @cAlloy AND Form LIKE @cForm AND SalesP LIKE @cSalesP
	AND YEAR(ShipDate) = YEAR(GETDATE())-2

SELECT DISTINCT Alloy, Form, CC, dbo.f_SizeStandard (ISNULL(Thck,0)) AS THCK, YEAR(ShipDate) AS ShipYear, MONTH(ShipDate) AS ShipMonth
	INTO #Past3YearSales
	FROM dbo.AllQuotes WHERE Alloy LIKE @cAlloy AND Form LIKE @cForm AND SalesP LIKE @cSalesP
	AND YEAR(ShipDate) = YEAR(GETDATE())-3


--Current Year
SELECT AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck
,AQ1.ShipYear
,ISNULL(SUM([01]),0) AS [m01],ISNULL(SUM([02]),0) AS [m02]
,ISNULL(SUM([03]),0) AS [m03],ISNULL(SUM([04]),0) AS [m04]
,ISNULL(SUM([05]),0) AS [m05],ISNULL(SUM([06]),0) AS [m06]
,ISNULL(SUM([07]),0) AS [m07],ISNULL(SUM([08]),0) AS [m08]
,ISNULL(SUM([09]),0) AS [m09],ISNULL(SUM([10]),0) AS [m10]
,ISNULL(SUM([11]),0) AS [m11],ISNULL(SUM([12]),0) AS [m12]
FROM #CurrentYearSales AS AQ1
--
INNER JOIN 
(SELECT Alloy, Form, CC, Thck, Weight
, ShipDate
, Month(ShipDate) AS [Month] FROM dbo.AllQuotes
WHERE Alloy LIKE @cAlloy
AND Form LIKE @cForm
AND SalesP LIKE @cSalesP
AND YEAR(ShipDate) = YEAR(GETDATE())
) AS AQ2
PIVOT ( SUM(Weight) FOR [Month] IN ([01],[02],[03],[04],[05],[06],[07],[08],[09],[10],[11],[12])
) AS AQ3
ON AQ1.Alloy = AQ3.Alloy AND AQ1.Form = AQ3.Form AND AQ1.CC = AQ3.CC AND AQ1.Thck = AQ3.Thck 
AND AQ1.ShipYear = YEAR(AQ3.ShipDate)
AND AQ1.ShipMonth = Month(AQ3.ShipDate)

GROUP BY AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck, AQ1.ShipYear

UNION
--Past Year
SELECT AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck
,AQ1.ShipYear
,ISNULL(SUM([01]),0) AS [m01],ISNULL(SUM([02]),0) AS [m02]
,ISNULL(SUM([03]),0) AS [m03],ISNULL(SUM([04]),0) AS [m04]
,ISNULL(SUM([05]),0) AS [m05],ISNULL(SUM([06]),0) AS [m06]
,ISNULL(SUM([07]),0) AS [m07],ISNULL(SUM([08]),0) AS [m08]
,ISNULL(SUM([09]),0) AS [m09],ISNULL(SUM([10]),0) AS [m10]
,ISNULL(SUM([11]),0) AS [m11],ISNULL(SUM([12]),0) AS [m12]
FROM #PastYearSales AS AQ1
--
INNER JOIN 
(SELECT Alloy, Form, CC, Thck, Weight
, ShipDate
, Month(ShipDate) AS [Month] FROM dbo.AllQuotes
WHERE Alloy LIKE @cAlloy
AND Form LIKE @cForm
AND SalesP LIKE @cSalesP
AND YEAR(ShipDate) = YEAR(GETDATE())-1
) AS AQ2
PIVOT ( SUM(Weight) FOR [Month] IN ([01],[02],[03],[04],[05],[06],[07],[08],[09],[10],[11],[12])
) AS AQ3
ON AQ1.Alloy = AQ3.Alloy AND AQ1.Form = AQ3.Form AND AQ1.CC = AQ3.CC AND AQ1.Thck = AQ3.Thck 
AND AQ1.ShipYear = YEAR(AQ3.ShipDate)
AND AQ1.ShipMonth = Month(AQ3.ShipDate)

GROUP BY AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck, AQ1.ShipYear

UNION
--Past 2nd Year
SELECT AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck
,AQ1.ShipYear
,ISNULL(SUM([01]),0) AS [m01],ISNULL(SUM([02]),0) AS [m02]
,ISNULL(SUM([03]),0) AS [m03],ISNULL(SUM([04]),0) AS [m04]
,ISNULL(SUM([05]),0) AS [m05],ISNULL(SUM([06]),0) AS [m06]
,ISNULL(SUM([07]),0) AS [m07],ISNULL(SUM([08]),0) AS [m08]
,ISNULL(SUM([09]),0) AS [m09],ISNULL(SUM([10]),0) AS [m10]
,ISNULL(SUM([11]),0) AS [m11],ISNULL(SUM([12]),0) AS [m12]
FROM #Past2YearSales AS AQ1
--
INNER JOIN 
(SELECT Alloy, Form, Thck, CC, Weight
, ShipDate
, Month(ShipDate) AS [Month] FROM dbo.AllQuotes
WHERE Alloy LIKE @cAlloy
AND Form LIKE @cForm
AND SalesP LIKE @cSalesP
AND YEAR(ShipDate) = YEAR(GETDATE())-2
) AS AQ2
PIVOT ( SUM(Weight) FOR [Month] IN ([01],[02],[03],[04],[05],[06],[07],[08],[09],[10],[11],[12])
) AS AQ3
ON AQ1.Alloy = AQ3.Alloy AND AQ1.Form = AQ3.Form AND AQ1.CC = AQ3.CC AND AQ1.Thck = AQ3.Thck 
AND AQ1.ShipYear = YEAR(AQ3.ShipDate)
AND AQ1.ShipMonth = Month(AQ3.ShipDate)

GROUP BY AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck, AQ1.ShipYear

UNION
--Past 3nd Year
SELECT AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck
,AQ1.ShipYear
,ISNULL(SUM([01]),0) AS [m01],ISNULL(SUM([02]),0) AS [m02]
,ISNULL(SUM([03]),0) AS [m03],ISNULL(SUM([04]),0) AS [m04]
,ISNULL(SUM([05]),0) AS [m05],ISNULL(SUM([06]),0) AS [m06]
,ISNULL(SUM([07]),0) AS [m07],ISNULL(SUM([08]),0) AS [m08]
,ISNULL(SUM([09]),0) AS [m09],ISNULL(SUM([10]),0) AS [m10]
,ISNULL(SUM([11]),0) AS [m11],ISNULL(SUM([12]),0) AS [m12]
FROM #Past3YearSales AS AQ1
--
INNER JOIN 
(SELECT Alloy, Form, Thck, CC, Weight
, ShipDate
, Month(ShipDate) AS [Month] FROM dbo.AllQuotes
WHERE Alloy LIKE @cAlloy
AND Form LIKE @cForm
AND SalesP LIKE @cSalesP
AND YEAR(ShipDate) = YEAR(GETDATE())-3
) AS AQ2
PIVOT ( SUM(Weight) FOR [Month] IN ([01],[02],[03],[04],[05],[06],[07],[08],[09],[10],[11],[12])
) AS AQ3
ON AQ1.Alloy = AQ3.Alloy AND AQ1.Form = AQ3.Form AND AQ1.CC = AQ3.CC AND AQ1.Thck = AQ3.Thck 
AND AQ1.ShipYear = YEAR(AQ3.ShipDate)
AND AQ1.ShipMonth = Month(AQ3.ShipDate)

GROUP BY AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck, AQ1.ShipYear

ORDER BY AQ1.Alloy, AQ1.Form, AQ1.CC, AQ1.Thck, AQ1.ShipYear
GO
/****** Object:  StoredProcedure [dbo].[p_Show_StockLst_Stock]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_Show_StockLst_Stock]') AND type in (N'P', N'PC'))
