ALTER  Procedure [dbo].[p_Show_StockLst_Stock]
(
@cAlloy char(12),
@cForm CHAR(2),
@cCC CHAR(1),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(18,4),
@nSize3 DECIMAL(18,4)
)

AS

--EXEC dbo.p_Show_StockLst_Stock 'C-276','40','1',.5,48,120
--EXEC dbo.p_Show_StockLst_Stock 'C-276','65','1',1,40,240
--EXEC dbo.p_Show_StockLst_Stock 'C-276','20','1',0.035,10,0
-- Used in HPA-Quotes-STK

-- REPLIES:
-- Size1=Stock List standard size. Standard Sike being listed
-- Size2=Stock List Size2.  Form 20,22,23 Size2 is Pounds.
-- Heats=Detailed Items found for @cAlloy,@cForm,@cCC,@nThickness,@nSize2. Not different heats.
-- LBS= Quantity found for @cAlloy,@cForm,@cCC,@nThickness,@nSize2. Could be Quantity of PC or Feet.
-- Selected= What is Sold out of LBS.
-- Incoming= What has not arrived out of LBS.

SET NOCOUNT ON

DECLARE @nSize NUMERIC(9,3)
SET @nSize = CAST(@nThickness AS NUMERIC(9,3) )

DECLARE @SizeHigh NUMERIC(9,4)
DECLARE @SizeLow NUMERIC(9,4)
SET @SizeHigh = @nThickness * 1.15
SET @SizeLow = @nThickness * .9


DECLARE @luse3rdDim bit
SELECT @luse3rdDim = dbo.f_GetForm_use3rdDim(@cForm)


IF @cForm >= '60' 
	begin
    IF @nSize2 > 0
		begin
		SELECT 
		M.[Size] AS [Size1]
		,CAST(D.Dim2 AS INT) AS 'Sz2' --Sz2 is exact like Sch 40
		,COUNT( D.Weight) AS 'Heats'
		,CAST( SUM(D.Weight) AS INT) AS 'Lbs'

		,( SELECT CAST (
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND Stocklst_Detail.Dim2 = @nSize2
		 AND StockLst_Process.Process_ID = 'SELECTED'
		) AS 'Sold'

		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND Stocklst_Detail.Dim2 = @nSize2
		 AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
		) AS 'Incoming'
		
		FROM dbo.Stocklst_Master M 
		INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
		LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
		
		  WHERE m.Alloy = @cAlloy
		  AND m.Form = @cForm 
		  AND m.CC = @cCC
		  AND (M.[Size] = @nSize  
		   ) AND D.Dim2 = @nSize2
	--	   AND D.Dim2 >= @nSize2

		GROUP BY M.[Size], D.Dim2
		ORDER BY M.[Size], D.Dim2
		end
	ELSE
		begin
		--@nSize2 is 0
		SELECT 
		M.[Size] AS [Size1]
		--,CAST(D.Dim2 AS INT) AS 'Sz2' --Sz2 is exact like Sch 40
		,0 AS Sz2
		,COUNT( D.Weight) AS 'Heats'
		,CAST( SUM(D.Weight) AS INT) AS 'Lbs'

		,( SELECT CAST (
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) 
		 AND StockLst_Process.Process_ID = 'SELECTED'
		) AS 'Sold'
		
		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) 
		 AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
		) AS 'Incoming'
		
		FROM dbo.Stocklst_Master M 
		INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
		LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
		
		  WHERE m.Alloy = @cAlloy
		  AND m.Form = @cForm 
		  AND m.CC = @cCC
		  AND (M.[Size] = @nSize  
		   ) 

		GROUP BY M.[Size]
		ORDER BY M.[Size]
		end
	end
ELSE
	IF @cForm = '20' OR @cForm = '22' OR @cForm = '23'
		begin
		SELECT 
		M.[Size] AS [Size1]
		,CAST( @nSize2 AS INT) AS 'Sz2' --Sz2 is a min width or length
		,COUNT( D.Weight) AS 'Heats'
		,CAST( SUM(D.Weight) AS INT) AS 'Lbs'
		
		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND StockLst_Process.Process_ID = 'SELECTED'
		) AS 'Sold'

		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
		) AS 'Incoming'
		
		FROM dbo.Stocklst_Master M 
		INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
		LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
		
		  WHERE m.Alloy = @cAlloy
		  AND m.Form = @cForm 
		  AND m.CC = @cCC
		  AND (M.[Size] = @nSize OR 
		  (ISNULL(D.size_h,99) <= @SizeHigh AND ISNULL(D.size_H,99) >= @SizeLow )  OR
		  (ISNULL(D.size_l,.001) <= @SizeHigh AND ISNULL(D.size_l,.001) >= @SizeLow ) )
		  AND D.[weight] >= @nSize2
		  
		GROUP BY M.[Size]
		ORDER BY M.[Size]
		end
	ELSE
		begin
		--@cForm < '60'   and not 20,22,23
		SELECT 
		M.[Size] AS [Size1]
		,CAST( @nSize2 AS INT) AS 'Sz2' --Sz2 is a min width or length
		,COUNT( D.Weight) AS 'Heats'
		,CAST( SUM(D.Weight) AS INT) AS 'Lbs'
		
		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND StockLst_Process.Process_ID = 'SELECTED'
		) AS 'Sold'
		
		,( SELECT CAST(
		 ISNULL( SUM(StockLst_Process.PWeight) ,0) AS INT)
		FROM dbo.Stocklst_Master 
		INNER JOIN dbo.Stocklst_Detail ON Stocklst_Master.[id]=Stocklst_Detail.[id] 
		LEFT OUTER JOIN dbo.StockLst_Process ON Stocklst_Detail.ID_Detail = StockLst_Process.ID_Detail
		 WHERE Stocklst_Master.Alloy = @cAlloy
		  AND Stocklst_Master.Form = @cForm 
		  AND Stocklst_Master.CC = @cCC
		  AND ( Stocklst_Master.[Size] = M.[Size]
		) AND (StockLst_Process.Process_ID = 'INCOMING' OR StockLst_Process.Process_ID = 'PARTRECV')
		) AS 'Incoming'
		
		FROM dbo.Stocklst_Master M 
		INNER JOIN dbo.Stocklst_Detail D ON M.[id]=D.[id]
		LEFT OUTER JOIN dbo.StockLst_Process P ON D.ID_Detail = P.ID_Detail
		
		  WHERE m.Alloy = @cAlloy
		  AND m.Form = @cForm 
		  AND m.CC = @cCC
		  AND (M.[Size] = @nSize OR 
		  (ISNULL(D.size_h,99) <= @SizeHigh AND ISNULL(D.size_H,99) >= @SizeLow )  OR
		  (ISNULL(D.size_l,.001) <= @SizeHigh AND ISNULL(D.size_l,.001) >= @SizeLow ) )
		  AND D.Dim2 >= @nSize2
		  
		GROUP BY M.[Size]
		ORDER BY M.[Size]
		end






GO
