ALTER PROCEDURE [dbo].[p_SO_Mark_Complete]
( @SalesNum INT) 
AS
-- EXEC [dbo].[p_SO_Mark_Complete] 93799
BEGIN

--Order Late SO
--DECLARE @SalesNum INT = 93799

SELECT * FROM dbo.AllQuotes WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Ship WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Sales_No WHERE SalesNum = @SalesNum
SELECT * FROM dbo.Sales WHERE SalesNum = @SalesNum
SELECT * FROM dbo.NR_UserTrack WHERE Mess1 LIKE '%'+LTRIM( RTRIM( CAST( @SalesNum AS CHAR (10) )))+'%' AND Mess1  LIKE '%Packing Slip Number %'ORDER BY ErrorDate

UPDATE dbo.Ship SET Complete = 1 WHERE SalesNum = @SalesNum
UPDATE dbo.Sales_No SET Cmplt = 1 WHERE SalesNum = @SalesNum
UPDATE dbo.Sales SET Cmplt = 1 WHERE SalesNum = @SalesNum

END

