ALTER         PROCEDURE [dbo].[p_StockLst_Detail_ins]
	@size_h		decimal(9, 4),
	@size_l		decimal(9, 4),
	@pc		INT,
	@dim1		decimal(18, 4),
	@dim2		decimal(18, 4),
	@dim3		decimal(18, 4),
	@length		varchar(160),
	@weight		decimal(18, 8),
	@costvalue	money,
	@descript	varchar(20),
	@location	varchar(10),
	@floorstatus	char(1),
	@class		char(1),
	@unit		varchar(6),
	@RandLen	BIT,
	@id		int,
	@ID_Detail_Process int
AS

  Set NoCount On
  --Need a StockLst Process to INSERT 

BEGIN TRY
  INSERT INTO dbo.StockLst_Process_detail 
    ( [ID], [ID_Detail_Process], [What] ) VALUES 
    ( @ID, @ID_Detail_Process, 'ADD' )
END TRY
BEGIN CATCH
	EXEC dbo.p_LogError
END CATCH

BEGIN TRY
  DECLARE @ID_Detail int    
  INSERT INTO dbo.[StockLst_Detail] WITH (ROWLOCK)  (
	[size_h],
	[size_l],
	[pc],
	[dim1],
	[dim2],
	[dim3],
	[length],
	[weight],
	[costvalue],
	[descript],
	[location],
	[floorstatus],
	[class],
	[unit],
	[RandLen],
	[InvCheck],
	[id] )

    Values (
	@size_h,
	@size_l,
	@pc,
	@dim1,
	@dim2,
	@dim3,
	@length,
	@weight,
	@costvalue,
	@descript,
	@location,
	@floorstatus,
	@class,
	@unit,
	@RandLen,
	GETDATE(),
	@id
)

SET @ID_Detail = SCOPE_IDENTITY()
END TRY
BEGIN CATCH
	EXEC dbo.p_LogError
END CATCH

BEGIN TRY
UPDATE dbo.StockLst_Process_Detail 
  SET  [ID_Detail] = @ID_Detail 
  WHERE [ID] = @ID 
  AND [ID_Detail_Process] = @ID_Detail_Process 
  AND [What] = 'ADD'

END TRY
BEGIN CATCH
	EXEC dbo.p_LogError
END CATCH

SELECT @ID_Detail
RETURN @ID_Detail









GO
