ALTER    PROCEDURE [dbo].[p_StockLst_Master_ins]
	@Alloy		char(12),
	@Form		char(2),
	@cc		char(1),
	@Cond		varchar(30),
	@Size		decimal(9,3),
	@PAID		decimal(18,8),
	@MWeight	decimal(18,8),
	@specs		varchar(160),
	@Heat		varchar(50),
	@Lot		varchar(10),
