	cc,
	Cond,
	[Size],
	PAID,
	MWeight,
	specs,
	Heat,
	Lot,
	PO_Item,
	PODueDate,
	History,
	Mill,
	StkDate,
	Num,
	POStatus,
	BrandName,
	--[MillTrace],
	From_ID,
	Melt )

    Values (
	@Alloy,
	@Form,
	@cc,
	@Cond,
	@Size,
	@PAID,
	@MWeight,
	@specs,
	@Heat,
	@Lot,
	@pPO_Item,
	@PODueDate,
	@History,
	@Mill,
	@StkDate,
	@Num,
	@POStatus,
	@BrandName,
	--[MillTrace],
	@From_ID,
	@Melt )

  SELECT SCOPE_IDENTITY()



  --GRANT EXECUTE ON [dbo].[p_StockLst_Master_ins] TO [WINDFALL\HPA] AS [dbo];


