ALTER PROCEDURE [dbo].[p_StockLst_Master_ReAdd]
	@ID_History	int
AS
 
--Return the New ID for StockLst_Master
--and update the non null fields Alloy,Form,[Size],Cond,Heat, PAID,MWeight

DECLARE @ID_Old INT
SELECT @ID_Old = ID FROM dbo.Ar.StockLst_Master_History WHERE ID_History = @ID_History
DECLARE @ID_New INT

IF EXISTS( SELECT * FROM dbo.StockLst_Master WHERE ID = @ID_Old )	
	SELECT 0
ELSE
	begin  
	
	--Not Null Feilds
	DECLARE @Alloy CHAR(12)
	DECLARE @Form CHAR(2)
	DECLARE @Size DECIMAL(9,3)
	DECLARE @Heat VARCHAR(50)
	
	--initialize
	SET @Alloy = ' '
	SET @Form = ' '
	SET @Size = 0
	SET @Heat = ' '

	--Update variables with the real data
	SELECT @Alloy = Alloy
		, @Form = Form
		, @Size = Size
		, @Heat = Heat 
		FROM dbo.Ar.StockLst_Master_History WHERE ID_History = @ID_History

	DECLARE @Cond VARCHAR(50)
	DECLARE @Paid MONEY
	DECLARE @MWeight Decimal(18,8)
	
	--Reset these
	SET @Cond = 'Recovered from Deleted History'
	SET @Paid = 0
	SET @MWeight = 0

--SET IDENTITY_INSERT dbo.StockLst_Master ON	--Does not work with replication!
--SET IDENTITY_INSERT dbo.StockLst_Master OFF

	  
	INSERT INTO dbo.StockLst_Master (
		Alloy
		,Form
		,[Size]
		,Cond
		,PAID
		,MWeight
		,Heat
		,From_ID )
		VALUES (
		@Alloy
		,@Form
		,@Size
		,@Cond
		,@PAID
		,@MWeight
		,@Heat
		,@ID_History )

	SET @ID_New = SCOPE_IDENTITY()


	--IF EXISTS( SELECT * FROM dbo.StockLst_Master WHERE ID = @ID_New )	
		SELECT @ID_New
	--ELSE
	--	SELECT 0
	
	--PRINT @ID_New
	end

  



GO
