ALTER PROCEDURE [dbo].[P_StockLst_Process_LBS]
(
@ID_Detail	INT
)
AS
BEGIN

DECLARE @MasterLB		FLOAT
DECLARE @MasterProcLB	FLOAT
DECLARE @DetailLB		FLOAT
DECLARE @DetailProcLB	FLOAT

--exec dbo.p_StockLst_Process_LBs 3967

SET NOCOUNT ON

DECLARE @err INT,
        @RC INT

SET @err = 0
SET @RC = 0

DECLARE @MasterID INT

SELECT @MasterLB = M.mWeight, @MasterID = M.ID FROM dbo.StockLst_Master M, dbo.StockLst_Detail D WHERE M.ID = D.ID AND D.ID_Detail = @ID_Detail

SELECT @MasterProcLB = SUM(P.pWeight) FROM dbo.StockLst_Master M, dbo.StockLst_Detail D, dbo.StockLst_Process P 
	WHERE M.ID = @MasterID AND D.ID = M.ID AND P.ID_Detail = D.ID_Detail
	AND ( P.Process_ID  = 'SELECTED' 
		OR P.Process_ID  = 'Shipped'
		OR P.Process_ID  = 'Partl Ship' )

SELECT @DetailLB = Weight FROM dbo.StockLst_Detail WHERE ID_Detail = @ID_Detail 

SELECT @DetailProcLB = SUM(pWeight) FROM dbo.StockLst_Process 
	WHERE ID_Detail = @ID_Detail 
	AND ( Process_ID  = 'SELECTED' 
		OR Process_ID  = 'Shipped'
		OR Process_ID  = 'Partl Ship' )

--NOT 'INCOMING','PARTRECV','CORRECTION','Receiving'


SELECT @MasterLB AS MasterLB
,@MasterProcLB AS MasterProcLB
,@DetailLB AS DetailLB
,@DetailProcLB AS DetailProcLB



END

