	-- Add the parameters for the stored procedure here

AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

declare @err int,
		@tablename sysname,
		@errormessage nvarchar(2000)

Declare @TitleName nvarchar(128), @Price money, @au_fname nvarchar(32), @au_name nvarchar(64), @CommissionRating int

BEGIN TRY

	begin transaction

	select @errormessage = 'insert into Titles table failed',
		 @tablename = 'Titles'
	insert dbo.Titles (TitleName, Price)
	values (@TitleName, @Price)

	select @errormessage = 'insert into Authors table failed',
