-- =============================================
-- Author:		Brandon van de Venter
-- Create date: 09/29/2020
-- Description:	Updates Sales_Hold_Status table to remove hold with an orderType variable which defaults to 1 (SOitem)
-- Updates:
-- 10/05/2020 - Changed POitem lookup to use new view [dbo].[v_PO_Hold_History] which will also return POs which were placed on hold without inserting a history item into [dbo].[Sales_Hold_Status]
-- 10/09/2020 - Changed POitem to update PurchaseOrder table directly. PurchaseOrder trigger will insert into [dbo].[Sales_Hold_Status]
-- 09/30/2022 - Fixed issue causing SO Item holds to not work
-- =============================================
ALTER PROCEDURE [dbo].[p_Update_Sales_Hold_Status_By_Type] 
	-- Add the parameters for the stored procedure here
	@OrderNumber char(12),
	@Hold_Type char(10),
	@Who varchar(255),
	@Comment varchar(255),
	@orderType smallint = 1 -- 1 = SOitem, 2 = POitem, 3 = ???
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	DECLARE 
		-- Sales_Hold_Status Values we care about
		@SalesNum int = -1,
		@Hold_Value bit = 0,
		@InsertedId int = 0

	IF (@orderType = 1) -- SOitem
	BEGIN
	
		SET @OrderNumber = dbo.f_ProperSOitem(@OrderNumber);

		-- Get first/latest matching entry for the SOitem
		SELECT TOP(1)
			@SalesNum = [SalesNum],
			@Hold_Value = [Hold_Value]
		FROM dbo.Sales_Hold_Status WITH(NOLOCK)
		WHERE dbo.f_ProperSOitem(SOitem) = @OrderNumber
			AND Hold_Type = @Hold_Type -- THIS IS ***IMPORTANT***, DO NOT CHANGE THIS
		ORDER BY [WHEN] desc

		IF (@SalesNum > 0 AND @Hold_Value = 1) -- Only continue if a row was found AND order is on hold
		BEGIN
			-- Insert new row into Sales_Hold_Status
			INSERT INTO [dbo].[Sales_Hold_Status] 
			(
				[SOitem]
				,[SalesNum]
				,[POitem]
				,[Hold_Type]
				,[Hold_Value]
				,[Who]
				,[What]
				,[Comment]
			)
			VALUES 
			(
				@OrderNumber,
				@SalesNum,
				NULL,
				@Hold_Type,
				0,
				@Who,
				LTRIM(RTRIM(@Hold_Type)) + ' OFF Hold',
				LTRIM(RTRIM(@Comment))
			)
		END

		set @InsertedId = SCOPE_IDENTITY();
	END

	ELSE IF (@orderType = 2) -- POitem
	BEGIN

		SET @OrderNumber = dbo.f_ProperPOitem(@OrderNumber);

		EXEC AS LOGIN = @who;

		-- Only continue if order is on hold. SalesNum is not required for a POitem
		IF (dbo.f_Is_POitemHeld(@OrderNumber) = 1)
		BEGIN
			-- UPDATE PurchaseOrder table directly
			UPDATE dbo.PurchaseOrder SET Hold = ~(ISNULL(dbo.f_Is_POitemHeld(@OrderNumber),0)) WHERE POitem = @OrderNumber

			-- UPDATE TRIGGER on dbo.PurchaseOrder will insert into [dbo].[Sales_Hold_Status], the following will get the resulting insert
			SELECT TOP (1) @InsertedId = ID
			FROM [dbo].[Sales_Hold_Status] WITH(NOLOCK)
			WHERE [POitem] = @OrderNumber 
			ORDER BY [When] desc

			IF (LTRIM(RTRIM(@Comment)) <> '')
			BEGIN
				UPDATE [dbo].[Sales_Hold_Status] SET Comment = LTRIM(RTRIM(@Comment)) WHERE ID = @InsertedId
			END
		END

		REVERT -- This reverts EXEC as user = @who; 
	END

	-- update sales table 
	-- DONE IN Sales_Hold_Status_Insert trgger
	-- exec dbo.p_Set_Sales_Hold_Status @cSOitem = @SOitem

	SELECT * FROM [dbo].[Sales_Hold_Status] WHERE ID = @InsertedId

END
--GRANT EXECUTE ON [dbo].[p_Update_Sales_Hold_Status_By_Type] TO [WINDFALL\HPA] AS [dbo];
GO
