ALTER  PROCEDURE [dbo].[p_UpdateSales_PoCost]
(
@POitem CHAR(12)
)
AS
BEGIN

--EXEC dbo.P_updateSales_PoCost '@POitem'


SET NOCOUNT ON
DECLARE @err INT,
        @RC INT
	
SET @err = 0
SET @RC = 0

DECLARE @nPOcost Money
SET @nPOcost = 0

--PRINT 'POitem '+ CAST(@POitem AS CHAR(12))

--Find Sales that need this POitem
IF EXISTS( SELECT SOitem FROM dbo.PurchaseOrder WHERE POitem = @POitem )
	begin

	PRINT 'Found a SOitem in PurchaseOrder'

	DECLARE @Poitem2 CHAR(12)
	DECLARE @SOitem CHAR(10)
	DECLARE @POCost money
	DECLARE @ReconcileTotal Money
	DECLARE @BestTotal Money

	DECLARE @NumberRecords int, @nRowCount int



	-- Insert the resultset we want to loop through
	-- into the temporary table

	CREATE TABLE #ActiveSO (
	  RowID int IDENTITY(1, 1)
	  ,SOitem char(10)
	  ,POCost Money
	  ,ReconcileTotal Money
		)

--SELECT SOitem FROM dbo.PO_SOdist WHERE POitem = '   509283-01' 
	IF EXISTS( 	SELECT SOitem FROM dbo.PO_SOdist WHERE POitem = @POitem )
	begin
		
		--PRINT 'Using a SOitem found in PO_SOdist'

		INSERT INTO #ActiveSO (SOitem,POCost,ReconcileTotal)
			SELECT SOitem, SUM(Total) AS POCost, SUM(ReconcileTotal) AS ReconcileTotal
			FROM dbo.PO_SOdist 
			WHERE SOitem IN (
				SELECT SOitem
				FROM dbo.PO_SOdist 
				WHERE POitem = @POitem
			) GROUP BY SOitem

		-- Get the number of records in the temporary table
		SET @NumberRecords = @@ROWCOUNT
	end

	IF @NumberRecords = 0
		IF EXISTS(SELECT SOitem	FROM dbo.PurchaseOrder WHERE POitem = @POitem AND NOT dbo.f_ProperSOitem(SOitem) = dbo.f_ProperSOitem('') )
		begin
			
			--PRINT 'Did not Find a SOitem in PO_SOdist, using PurchaseOrder'

			INSERT INTO #ActiveSO (SOitem,POCost,ReconcileTotal)
				SELECT SOitem, StockLst_Total AS POCost, ReconcileTotal
				FROM dbo.PurchaseOrder
				WHERE POitem = @POitem
				AND NOT dbo.f_ProperSOitem(SOitem) = dbo.f_ProperSOitem('')
		

			SET @NumberRecords = @@ROWCOUNT
		end


--	IF @NumberRecords = 0
--			DROP TABLE #ActiveSO

	--IF @NumberRecords > 0
	SET @nRowCount = 1

	-- loop through all records in the temporary table
	-- using the WHILE loop construct
	-- find all SOitems that may have been touched by the POitem.

	WHILE @nRowCount <= @NumberRecords
	BEGIN
		
		--PRINT 'Row '+CAST(@nRowCount AS CHAR(10))

		SELECT @SOitem = SOitem
			,@POCost = POCost
			,@ReconcileTotal = ReconcileTotal
			,@BestTotal = ISNULL(ReconcileTotal,POCost)
		  FROM #ActiveSO
		  WHERE RowID = @nRowCount

		--PRINT ' Update dbo.Sales'
			
/*		BROKEN: 'QUOTED_IDENTIFIER'
		UPDATE dbo.Sales 
		  SET POcost = CAST(@BestTotal AS Decimal(9,2))
		  , ItemCost = CAST(@BestTotal+ISNULL(Sales.StkCost,0)  AS Decimal(9,2))
		  WHERE SOitem = @SOitem
*/

		--PRINT 'Row Updated= ' + CAST(@nRowCount AS CHAR(10))
		
		SET @nRowCount = @nRowCount + 1
	END

	-- drop the temporary table
	DROP TABLE #ActiveSO

	end
END
GO
