-- =============================================
-- Author:		Sean Lykins
-- Create date: 12/20/2011
-- Description:	Decipher vendor QA types
-- =============================================
ALTER PROCEDURE [dbo].[p_Vendor_QAType] 
	-- Add the parameters for the stored procedure here
	@typeNum bigint = 0 
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @Manufacturer BIT
	SET @Manufacturer = 0
	Declare @Distributor BIT
	SET @Distributor = 0
	DECLARE @Service BIT
	SET @Service = 0
	DECLARE @Calibration BIT
	SET @Calibration = 0
	DECLARE @MaterialTesting BIT
	SET @MaterialTesting = 0
	DECLARE @GageEquipment BIT
	SET @GageEquipment = 0
	DECLARE @Other BIT
	SET @Other = 0
	
	IF @typeNum >= 64
		begin
		SET @Other = 1
		SET @typeNum -= 64
		end
		
	IF @typeNum >= 32
		begin
		SET @GageEquipment = 1
		SET @typeNum -= 32
		end

	IF @typeNum >= 16
		begin
		SET @MaterialTesting = 1
		SET @typeNum -= 16
		end
		
	IF @typeNum >= 8
		begin
		SET @Calibration = 1
		SET @typeNum -= 8
		end

	IF @typeNum >= 4
		begin
		SET @Service = 1
		SET @typeNum -= 4
		end

	IF @typeNum >= 2
		begin
		SET @Distributor = 1
		SET @typeNum -= 2
		end

	IF @typeNum >= 1
		begin
		SET @Manufacturer = 1
		SET @typeNum -= 1
		end

	SELECT @Manufacturer AS Manufacturer
	, @Distributor AS Distributor
	, @Service AS Service
	, @Calibration AS Calibration
	, @MaterialTesting AS MaterialTesting
	, @GageEquipment AS 'Gage\Equipment'
	, @Other AS Other
END
GO
