/****** Object:  StoredProcedure [dbo].[p_VPR_Quarter]    Script Date: 12/26/2025 5:48:52 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
IF NOT EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'[dbo].[p_VPR_Quarter]') AND type in (N'P', N'PC'))
BEGIN
EXEC dbo.sp_executesql @statement = N'CREATE PROCEDURE [dbo].[p_VPR_Quarter] AS' 
END
GO
-- =============================================
-- Author:		Sean Lykins
-- Create date: 2015 02 24
-- Description:	VPR Quarterly data
-- =============================================
ALTER PROCEDURE [dbo].[p_VPR_Quarter] 
	-- Add the parameters for the stored procedure here
	@vendcode int = 0, 
	@datemin2 datetime,
	@datemax datetime
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	SET @datemin2 = DateAdd(Quarter,-1, CONVERT(varchar,CASE WHEN Month(GETDATE()) >= 10 THEN 10 WHEN Month(GETDATE()) >= 7 THEN 7 WHEN Month(GETDATE()) >= 4 THEN 4 ELSE 1 END) 
	+ '/01/' + CONVERT(varchar, Year(GETDATE())))
	SET @datemax = DateAdd(DAY,-1, CONVERT(varchar, CASE WHEN Month(GETDATE()) >= 10 THEN 10 WHEN Month(GETDATE()) >= 7 THEN 7 WHEN Month(GETDATE()) >= 4 THEN 4 ELSE 1 END) 
	+ '/01/' + CONVERT(varchar, Year(GETDATE())))
SELECT SUM(ISNULL(r.RejectPC,0)) AS 'Pieces Rejected'
		,SUM(CONVERT(int,ISNULL(r.Pass,0))) AS 'Acceptable Documentation'
		,COUNT(r.Pass) AS 'Number of Documentation'
		,SUM(CASE WHEN ISNULL(r.pieces,0) = 0 THEN CASE WHEN ISNULL(r.poitem,'') != '' THEN 1 ELSE 0 END ELSE ISNULL(r.pieces,0) END) AS 'Total Pieces'
		,(SELECT COUNT(sub.poitem)
			FROM(SELECT p2.poitem
					FROM ERP_1.dbo.Vendor v
						INNER JOIN [dbo].PurchaseOrder p2 ON v.VendCode = p2.VendCode
						LEFT OUTER JOIN [dbo].Receiving r2 ON r2.poitem = p2.poitem
					WHERE V.vendcode = @vendcode
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) < ISNULL(r2.received,GETDATE())
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) >= @datemin2 
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) <= @datemax
						AND ISNULL(p2.cancelled,0) = 0 
					GROUP BY p2.poitem
			) as sub
		  ) AS 'Qty of PO Items Late'
		,(SELECT AVG(sub.DaysLate)
			FROM(SELECT case When DATEDIFF(d,ISNULL(HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')),ISNULL(r2.received,GETDATE())) > 0
						then DATEDIFF(d,ISNULL(HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')),ISNULL(r2.received,GETDATE()))
						else 0 end as DaysLate
					FROM ERP_1.dbo.Vendor v
						INNER JOIN [dbo].PurchaseOrder p2 ON v.VendCode = p2.VendCode
						LEFT OUTER JOIN [dbo].Receiving r2 ON r2.poitem = p2.poitem
					WHERE V.vendcode = @vendcode
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) >= @datemin2 
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) <= @datemax
						AND ISNULL(p2.cancelled,0) = 0 
			) as sub
		  ) AS 'AvgDaysLate'
		,(SELECT SUM(CASE WHEN p2.poitem IS NULL THEN 0 ELSE 1 END)
					FROM ERP_1.dbo.Vendor v
						INNER JOIN [dbo].PurchaseOrder p2 ON v.VendCode = p2.VendCode
						LEFT OUTER JOIN [dbo].Receiving r2 ON r2.poitem = p2.poitem
					WHERE V.vendcode = @vendcode
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) >= @datemin2 
						AND ISNULL(p2.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) <= @datemax
						AND ISNULL(p2.cancelled,0) = 0 
			) AS 'Total PO Items'
		 ,@vendcode as vendcode
FROM [dbo].Receiving r
	RIGHT OUTER JOIN [dbo].PurchaseOrder p ON r.poitem = p.poitem
WHERE p.VendCode = @vendcode 
		AND ISNULL(p.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) >= @datemin2 
		AND ISNULL(p.HPA_Due_Max,CONVERT(Datetime,'1900-01-01 00:00:00.000')) <= @datemax
		AND ISNULL(p.cancelled,0) = 0
END
GO
