ALTER PROCEDURE [dbo].[p_WaterJet]
( @nThickness DECIMAL(9,4) )
AS
-- EXEC [dbo].[p_WaterJet] .5
BEGIN

--Find Thickness 
DECLARE @nStandardSizeMin	NUMERIC(9,4)
DECLARE @nStandardSizeMax	NUMERIC(9,4)
DECLARE @nStandardSize		NUMERIC(9,4)
SET @nStandardSize		= 0
SET @nStandardSizeMin	= 0
SET @nStandardSizeMax	= 0

SELECT TOP 1 @nStandardSizeMin = thick FROM dbo.WaterJet WHERE  Thick >= @nThickness - (@nThickness*.05) ORDER BY Thick 
SELECT TOP 1 @nStandardSizeMax = thick FROM dbo.WaterJet WHERE  Thick <= @nThickness + (@nThickness*.05) ORDER BY Thick DESC

IF @nStandardSizeMin = @nThickness
	SET @nStandardSize = @nStandardSizeMin
ELSE
	IF @nStandardSizeMax > 0
		SET @nStandardSize = @nStandardSizeMax
	ELSE
		SET @nStandardSize = @nStandardSizeMin 
	
--Return data in select
IF @nStandardSize > 0
	begin
	SELECT TOP 1 
	  [Thick]
      ,[Inch20]
      ,[Min20]
      ,[Inch40]
      ,[Min40]
      ,[Inch60]
      ,[Min60]
      ,[Inch80]
      ,[Min80]
      ,[Inch100]
      ,[Min100]
   	FROM [dbo].[WaterJet]
	WHERE [Thick] = @nStandardSize
	
	end
ELSE
	begin
	SELECT 
	  [Thick]
      ,[Inch20]
      ,[Min20]
      ,[Inch40]
      ,[Min40]
      ,[Inch60]
      ,[Min60]
      ,[Inch80]
      ,[Min80]
      ,[Inch100]
      ,[Min100]
	 FROM [dbo].[WaterJet]
	 WHERE 0>0
	 end

RETURN

END

