ALTER     PROCEDURE [dbo].[p_Weight] 
(
@nPieces TinyINT,
@cAlloy char(12),
@cForm CHAR(2),
@nThickness DECIMAL(9,4),
@nSize2 DECIMAL(9,3),
@nSize3 DECIMAL(9,3),
--@nPounds DECIMAL(9,4) OUTPUT,
@nPounds FLOAT(24) OUTPUT,
@nPoundsInCut DECIMAL(9,4) OUTPUT,
@cMessage CHAR(2000) OUTPUT
)
AS
--nPounds = 0
--nPoundsInCut = 0
--cMessage = ''
--
--sql_sp = "{CALL  p_Weight ("
--sql_sp = sql_sp + ""+ "1" + ","
--sql_sp = sql_sp + "'"+ cAlloy+ "',"
--sql_sp = sql_sp + "'"+ cForm+ "'," 
--sql_sp = sql_sp + ""+ LEFT(STR(nStdSize,9,4),8)+ "," && 3 decimals, not 4
--sql_sp = sql_sp + ""+ STR(nSize2,9,3)+ ","
--sql_sp = sql_sp + ""+ STR(nSize3,9,3)+ ","
--sql_sp = sql_sp + "?@nPounds,"
--sql_sp = sql_sp + "?@nPoundsInCut,"
--sql_sp = sql_sp + "?@cMessage "
--sql_sp = Sql_sp + ")}"
--nSQLEXEC = SQLEXEC(nConnHandle, SQL_SP )
BEGIN
SET NOCOUNT ON
SET @cMessage = ''

DECLARE @nSawCurf DECIMAL(4,2)
SET @nSawCurf = .3


IF @nPieces < 1
	SET @nPieces = 1

DECLARE @nDensity DECIMAL(9,4)
SET @nDensity = IsNull(dbo.AlloyDensity( dbo.AlloyName(@cAlloy) ),0)
IF @nDensity = 0
   BEGIN
    SET @nDensity = .29
    SET @cMessage = RTRIM(@cMessage)+' Alloy Density not found!'
   END
ELSE
   SET @cMessage = RTRIM(@cMessage)+'Used Density of '+STR(@nDensity,5,3)
--Find Thickness used in PriceTable


SET @nPounds = 0
SET @nPoundsInCut = 0

IF @cForm = '10' 
   BEGIN
	--CHANGE FROM @nThickness*1.023 2-9-94
	--USING CASE STRUCTURE WITH ERIKS INFO
	IF @nThickness = 0
		BEGIN
		SET @nPounds = 0
		SET @nPoundsInCut = 0
		END
	ELSE
	IF @nThickness < 3
		BEGIN
		SET @nPounds = (POWER(@nThickness+.01,2)* 3.23 * @nDensity* @nSize2* @nPieces /4)
		SET @nPoundsInCut = (POWER(@nThickness+.005,2)* 3.23* @nDensity*(@nSawCurf)* @nPieces /4)
		END
	ELSE
	IF @nThickness < 6
		BEGIN
		SET @nPounds = (POWER(@nThickness+.020,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nPoundsInCut = (POWER(@nThickness+.015,2)* 3.23* @nDensity* .375* @nPieces /4)
		END
	ELSE
		BEGIN
		SET @nPounds = (POWER(@nThickness+.032,2)* 3.23* @nDensity* @nSize2* @nPieces /4)
		SET @nPoundsInCut = (POWER(@nThickness+.032,2)* 3.23* @nDensity* .5* @nPieces /4)
		END
   END
ELSE
IF @cForm = '11' 
   BEGIN
	--Flat Bar
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nPoundsInCut = (@nDensity* @nThickness* 1.03* @nSize2*(@nSawCurf)* @nPieces )
   END
ELSE
IF @cForm = '12'
	BEGIN
	 --HEX Bar
	SET @nPounds = @nDensity*@nThickness*@nThickness*.866*@nSize2* @nPieces
	SET @nPoundsInCut = (@nDensity* @nThickness*@nThickness* .866*(@nSawCurf)* @nPieces )
	END
ELSE
IF @cForm = '13' 
	BEGIN
	--Square Bar
	SET @nPounds = (@nDensity* @nThickness* 1.03* @nSize2* @nSize3* @nPieces )
	SET @nPoundsInCut = (@nDensity* @nThickness* 1.03* @nSize2*(@nSawCurf)* @nPieces )
	END
ELSE
IF @cForm = '20' 
	BEGIN
	--Wire Spool
	SET @nPounds = @nSize2* @nPieces 
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '21' 
	BEGIN
	--TIG Wire cuts
	SET @nPounds = @nSize3 * @nPieces 
	--SET @nPounds = (@nDensity* @nThickness* 1.01* @nSize2* @nSize3* @nPieces )
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '30' 
	BEGIN
	--Coated Electrodes
	SET @nPounds = @nSize3 * @nPieces 
	SET @nPoundsInCut = 0
	END
ELSE
IF @cForm = '40' 
	BEGIN
	--Plate / Sheet
	SET @nPounds = (@nDensity* @nThickness* 1.015* @nSize2* @nSize3* @nPieces )
	IF @nThickness > .060 OR @cAlloy = '6B' OR @cAlloy = '6BH'
		SET @nPoundsInCut =((@nDensity* @nThickness* 1.03* (@nSize2+(@nSawCurf))* (@nSize3+(@nSawCurf))* @nPieces )  )-@nPounds
	ELSE
		SET @nPoundsInCut = 0

	END
ELSE
IF @cForm = '60'
   BEGIN
	SET @nPounds = @nDensity *@nSize3*@nSize2*3.23* (@nThickness-@nSize2)* @nPieces 
	SET @nPoundsInCut = 0
   END
ELSE
IF @cForm = '65'
   BEGIN
	DECLARE @nPipeWeight DECIMAL(9,4)
	SET @nPipeWeight = IsNull(dbo.PipeWeight(@nThickness,@nSize2),0)
	IF @nPipeWeight = 0
		   SET @cMessage = RTRIM(@cMessage)+' Pipe Weight not found!'

	SET @nPounds = (@nDensity* @nPipeWeight* @nSize3* @nPieces )
	SET @nPoundsInCut = 0
   END
ELSE
IF @cForm = '80'
   BEGIN
	--SET @nPounds = ROUND((@nDensity* @nThickness* 1.015*3.23/4* (POWER(@nSize2,2)- POWER(@nSize3,2))* @nPieces ),1)
	SET @nPounds = (@nDensity* @nThickness* 1.03* (@nSize2)* (@nSize2)* @nPieces )
	DECLARE @pcurf DECIMAL(9,5)
	IF @nThickness < .5  
		SET @pcurf = .5
	ELSE
		SET @pcurf = @nThickness

	SET @nPoundsInCut  = (@nDensity* @nThickness* 1.03* (@nSize2+ @pcurf)* (@nSize2+ @pcurf)* @nPieces ) - @nPounds
   END

RETURN
END

