--SELECT top 10 * FROM dbo.WIPLst_Process ORDER BY ID_Detail_Process DESC
--
--GRANT EXECUTE ON [dbo].[p_WIPLst_Process_ins7] TO [WINDFALL\HPA]

SET @SOitem = dbo.ProperSO( @SOitem )
SET @PO_item = dbo.ProperPO( @PO_item )

INSERT INTO dbo.WIPLst_Process WITH (ROWLOCK)  (
	ID_Detail,
	SalesPerson,
	StartDate,
	DueDate,
	AllowSub,
	PU,
	QTY,
	Pounds,
