		INSERT INTO dbo.NR_UserTrack (Mess1,cProgram,ServerName) 
			SELECT LEFT(''AllQuotes ID''+LTRIM(CAST(inserted.ID AS CHAR(10)))+'' data for SOitem:''+inserted.SOitem+'' was changed. ''+ @cReturn ,1024) 
