PRINT '' INSERT dbo.Ar.BrokerLst_Detail_History FROM inserted  [BrokerLst_Detail_Insert]''
INSERT dbo.Ar.BrokerLst_Detail_History 
	([ID_Detail_Process],
	[ProcessValue],
	[What],
	[size_h],
	[size_l],
	[pc],
	[dim1],
	[dim2],
	[dim3],
	[length],
	[weight],
	[costvalue],
	[descript],
	[location],
	[floorstatus],
	[class],
