	[ReceivingID],
	[InvoiceValue],
	[Quarantine],
	[S_QTY],
	[S_P],
	[S_Total],
	[S_PU],
	[Prime])
SELECT 	case when ISNULL(spd.ID_Detail_Process,0) > 0 then spd.ID_Detail_Process else @nID_Detail_Process end,
	(inserted.S_QTY * inserted.S_P),
	''ADD'',
