	inserted.[pc],
	inserted.[dim1],
	inserted.[dim2],
	inserted.[dim3],
	inserted.[length],
	inserted.[weight],
	inserted.[costvalue],
	inserted.[descript],
	inserted.[location],
	inserted.[floorstatus],
	inserted.[class],
	inserted.[unit],
