	,[InqNumP]
	,[Prc_QTY]
	,[Prc_Form]
	,[Prc_PCs]
	,[Prc_Dim2]
	,[Prc_Dim3]
	,FoundSTK)
   SELECT suser_sname() AS [Who],
	''AFTER EDIT'' AS [What],
	GETDATE() AS [When],
	deleted.[SOitem],
	deleted.[PO_Item],
	deleted.[SalesPerson],
	deleted.[StartDate],
	deleted.[DueDate],
	deleted.[Comment],
	deleted.[Process_ID],
	deleted.[Processor],
	deleted.[AllowSub],
	deleted.[PWeight],
	deleted.[PPc],
	deleted.[PFt],
	deleted.[PU],
	deleted.[QTY],
	deleted.[Ordered_QTY],
	deleted.[Ordered_P],

	deleted.[Pounds],
	deleted.[ID_Detail],
	deleted.[ID_Detail_Process],
	''F'',
	deleted.[ReceivingID],
	deleted.[WO]
	,deleted.[WO_Detail]
	,deleted.[InqNumP]
	,deleted.[Prc_QTY]
	,deleted.[Prc_Form]
	,deleted.[Prc_PCs]
	,deleted.[Prc_Dim2]
	,deleted.[Prc_Dim3]
	,deleted.FoundSTK
    FROM inserted, deleted
	WHERE inserted.[ID_Detail_Process] = deleted.[ID_Detail_Process]
	   and NOT ( inserted.[SOitem] = deleted.[SOitem] 
	   and inserted.[PO_Item]     = deleted.[PO_Item] 
	   and inserted.[SalesPerson] = deleted.[SalesPerson]
	   and inserted.[StartDate]   = deleted.[StartDate]  
	   and inserted.[Comment]     = deleted.[Comment]  
	   and inserted.[Processor]   = deleted.[Processor]  
	   and inserted.[AllowSub]    = deleted.[AllowSub]
	   and inserted.[PWeight]     = deleted.[PWeight]
	   and inserted.[PPc]         = deleted.[PPc] 
	   and inserted.[PU]          = deleted.[PU]
	   and inserted.[QTY]         = deleted.[QTY]
	   and inserted.[Pounds]      = deleted.[Pounds] )
	and ( UPDATE([SOitem]) 
		or UPDATE([PO_Item])
		or UPDATE([SalesPerson])
		or UPDATE([StartDate])
		or UPDATE([Comment])
		or UPDATE([Processor])
		or UPDATE([AllowSub])
		or UPDATE([PWeight])
		or UPDATE([PPc])
		or UPDATE([PU])
		or UPDATE([QTY])
		or UPDATE([Pounds])
		or UPDATE([Prc_QTY])
		or UPDATE([FoundSTK]) )

END
