           , [xComp] = ISNULL(inserted.Phone,SPACE(10))+ISNULL(SOUNDEX(inserted.Company),SPACE(4))
           , [LastEdit] = CAST(GetDate() AS SmallDateTime)
		   , [NoNoiseName] = dbo.f_NoNoiseName(inserted.Company) 
		 FROM [inserted]
		 WHERE [QuickCompany].ID = inserted.ID


	end
	
