		FROM inserted 
		INNER JOIN deleted ON inserted.SalesNum = deleted.SalesNum
			WHERE -- ISNULL(inserted.ItemTot,0) = 0 AND
			ISNULL(inserted.ItemTot,0) <> ISNULL(deleted.ItemTot,0)
			AND UPDATE(ItemTot)
	end


