AS


PRINT ''Trigger Start [StockLst_Detail_Update]'';
DECLARE @cProgram Char(60) = ''TRIGGER dbo.StockLst_Detail_Update''

DECLARE @Count int
SET @Count = @@ROWCOUNT;
        
IF @Count > 100
BEGIN
    RAISERROR(''Cannot UPDATE more than 100 records of Lst_Detail at one time.'',16,1) 
    ROLLBACK TRANSACTION
