	,[Prc_Form]
	,[Prc_PCs]
	,[Prc_Dim2]
	,[Prc_Dim3]
	,FoundSTK )
   SELECT 	suser_sname() AS [Who],
	''BEFOREEDIT'' AS [What],
	GETDATE() AS [When],
	inserted.[SOitem] ,
	inserted.[PO_Item],
	inserted.[SalesPerson],
	inserted.[StartDate],
	inserted.[DueDate],
	inserted.[Comment],
	inserted.[Process_ID],
	inserted.[Processor],
	inserted.[AllowSub],
	inserted.[PWeight],
	inserted.[PPc],
	inserted.[PFt],
	inserted.[PU],
	inserted.[QTY],
