	   and inserted.[Pounds]      = deleted.[Pounds] 
	   and inserted.[FoundSTK]    = deleted.[FoundSTK] )
		and ( UPDATE([SOitem]) 
		or UPDATE([PO_Item])
		or UPDATE([SalesPerson])
		or UPDATE([StartDate])
		or UPDATE([Comment])
		or UPDATE([Processor])
		or UPDATE([AllowSub])
		or UPDATE([PWeight])
		or UPDATE([PPc])
		or UPDATE([PU])
		or UPDATE([QTY])
		or UPDATE([Pounds])
		or UPDATE([Prc_QTY])
		or UPDATE([FoundSTK]))

   INSERT dbo.Ar.StockLst_Process_History 
	([Who],
