		or UPDATE([SalesPerson])
		or UPDATE([StartDate])
		or UPDATE([Comment])
		or UPDATE([Processor])
		or UPDATE([AllowSub])
		or UPDATE([PWeight])
		or UPDATE([PPc])
		or UPDATE([PU])
		or UPDATE([QTY])
		or UPDATE([Pounds])
		or UPDATE([Prc_QTY])
							)
/*
	   and NOT ( inserted.[SOitem] = deleted.[SOitem] 
	   and inserted.[PO_Item]     = deleted.[PO_Item] 
	   and inserted.[SalesPerson] = deleted.[SalesPerson]
