DECLARE @ID INT = 0
DECLARE @WO INT = 0

PRINT ''SELECT TOP 1 ID, WO''
--SELECT TOP 1 ID = @ID, WO = @WO
SET @ID = (SELECT TOP 1 inserted.ID
	FROM inserted )
SET @WO = (SELECT TOP 1 inserted.WO
	FROM inserted )
PRINT @WO

PRINT '' INSERT dbo.Ar.WIPLst_Detail_History FROM inserted.   [WIPLst_Detail_Insert]''
INSERT dbo.Ar.WIPLst_Detail_History 
	([ID_Detail_Process],
	[ProcessValue],
	[What],
	[size_h],
	[size_l],
	[pc],
	[dim1],
	[dim2],
	[dim3],
	[length],
	[weight],
	[costvalue],
	[descript],
	[location],
	[floorstatus],
	[class],
	[unit],
	[RandLen],
	[InvCheck],
	[id],
	[id_detail],
	[ReceivingID],
	[InvoiceValue],
	[AccountingCheck],
	[Quarantine],
	[S_QTY],
	[S_P],
	[S_Total],
	[S_PU],
	[Prime]
	,[WO]
	,sStockLst_ID_Detail
	,fStockLst_ID_Detail
	)
SELECT 	ISNULL(spd.ID_Detail_Process,0),
	(inserted.S_QTY * inserted.S_P),
	''ADD'',
	inserted.[size_h],
	inserted.[size_l],
	inserted.[pc],
	inserted.[dim1],
	inserted.[dim2],
	inserted.[dim3],
	inserted.[length],
	inserted.[weight],
	inserted.[costvalue],
	inserted.[descript],
	inserted.[location],
	inserted.[floorstatus],
	inserted.[class],
	inserted.[unit],
	inserted.[RandLen],
	inserted.[InvCheck],
	inserted.[id],
	inserted.[id_detail],
	inserted.[ReceivingID],
	inserted.[InvoiceValue],
	inserted.[AccountingCheck],
	inserted.[Quarantine],
	inserted.[S_QTY],
	inserted.[S_P],
	inserted.[S_Total],
	inserted.[S_PU],
	inserted.[Prime],
	inserted.[WO],
	inserted.sStockLst_ID_Detail,
	inserted.fStockLst_ID_Detail
 FROM inserted
 LEFT OUTER JOIN dbo.WIPLst_Process_Detail spd ON inserted.ID = spd.ID 
	AND inserted.WO = spd.WO 
		--AND spd.Who = SUSER_SNAME() AND ( spd.What = ''ADD'' OR spd.What = ''Work Order'' )

/*
PRINT '' INSERT dbo.Ar.WIPLst_Process_GS_History    [WIPLst_Detail_Insert]''

 INSERT dbo.Ar.WIPLst_Process_GS_History 
	(What,
	[When],
	[SOitem],
