	,[InqNumP]
	,[Prc_QTY]
	,[Prc_Form]
	,[Prc_PCs]
	,[Prc_Dim2]
	,[Prc_Dim3]
	,FoundSTK)
   SELECT suser_sname() AS [Who],
	''BEFOREEDIT'' AS [What],
