	   and inserted.[Pounds]      = deleted.[Pounds]
	   and inserted.[FoundSTK]    = deleted.[FoundSTK] )
		and ( UPDATE([SOitem]) 
		or UPDATE([PO_Item])
		or UPDATE([SalesPerson])
		or UPDATE([StartDate])
		or UPDATE([Comment])
		or UPDATE([Processor])
		or UPDATE([AllowSub])
		or UPDATE([PWeight])
		or UPDATE([PPc])
		or UPDATE([PU])
		or UPDATE([QTY])
		or UPDATE([Pounds])
		or UPDATE([Prc_QTY]) 
		or UPDATE([FoundSTK]) )


   INSERT dbo.Ar.WIPLst_Process_History 
	([Who],[What],[When],
	[SOitem],
	[PO_Item],
	[SalesPerson],
	[StartDate],
	[DueDate],
	[Comment],
	[Process_ID],
	[Processor],
	[AllowSub],
	[PWeight],
	[PPc],
	[PFt],
	[PU],
