	[ID_Detail_Process],
	[Validated],
	[ReceivingID],
	[WO]
	,[WO_Detail]
	,[InqNumP]
	,[Prc_QTY]
	,[Prc_Form]
	,[Prc_PCs]
	,[Prc_Dim2]
	,[Prc_Dim3]
	,FoundSTK)
   SELECT suser_sname() AS [Who],
	''AFTER EDIT'' AS [What],
	GETDATE() AS [When],
	deleted.[SOitem],
	deleted.[PO_Item],
	deleted.[SalesPerson],
	deleted.[StartDate],
	deleted.[DueDate],
	deleted.[Comment],
	deleted.[Process_ID],
	deleted.[Processor],
	deleted.[AllowSub],
	deleted.[PWeight],
	deleted.[PPc],
	deleted.[PFt],
	deleted.[PU],
	deleted.[QTY],
	deleted.[Ordered_QTY],
	deleted.[Ordered_P],

	deleted.[Pounds],
