create TRIGGER [dbo].[Wire_Dies_Update] 
ON [dbo].[Wire_Dies] 
	FOR UPDATE 
	NOT FOR REPLICATION
AS

PRINT ''Trigger Start [Wire_Dies_Update]'';

    
---big UPDATES are in error
DECLARE @Count int
SET @Count = @@ROWCOUNT;
   
IF @Count > 1000
BEGIN
